import { Request, Response, NextFunction } from 'express';
import { serverDb } from '../database.js';

interface ClientState {
  burstTokens: number;
  lastRequest: number;
  minuteCount: number;
  minuteReset: number;
  hourlyCount: number;
  hourlyReset: number;
}

const clientStates = new Map<string, ClientState>();
const activeRequests = new Map<string, number>();

let globalDailyUsage = 0;
let globalDailyReset = 0;

function updateAndCheckState(key: string, isAnonymous: boolean, now: number): { allowed: boolean, state: ClientState } {
  let state = clientStates.get(key);
  if (!state || now > state.hourlyReset) {
    state = {
      burstTokens: isAnonymous ? 3 : 10,
      lastRequest: now,
      minuteCount: 0,
      minuteReset: now + 60000,
      hourlyCount: 0,
      hourlyReset: now + 3600000,
    };
    clientStates.set(key, state);
  } else if (now > state.minuteReset) {
    state.minuteCount = 0;
    state.minuteReset = now + 60000;
  }

  const timePassed = now - state.lastRequest;
  const maxTokens = isAnonymous ? 3 : 10;
  const refillRate = isAnonymous ? 10000 : 2000; // ms per token

  state.burstTokens = Math.min(maxTokens, state.burstTokens + Math.floor(timePassed / refillRate));
  state.lastRequest = now;

  let allowed = true;
  if (state.burstTokens <= 0) allowed = false;

  const maxPerMinute = isAnonymous ? 5 : 30;
  if (state.minuteCount >= maxPerMinute) allowed = false;

  const maxPerHour = isAnonymous ? 20 : 100;
  if (state.hourlyCount >= maxPerHour) allowed = false;

  return { allowed, state };
}

export async function aiAbuseLimiter(req: Request, res: Response, next: NextFunction) {
  const isAnonymous = !req.user || req.user.userId === 'guest';
  const clientIp = req.ip || '127.0.0.1';
  const clientFingerprint = req.headers['x-anonymous-id'] as string || '';

  // Track IP and Fingerprint separately to prevent rotating one to bypass limits
  const ipKey = `ip_${clientIp}`;
  const fingerKey = clientFingerprint ? `finger_${clientFingerprint}` : null;
  const userKey = !isAnonymous ? `user_${req.user!.userId}` : null;

  // Keys to check
  const keysToCheck = isAnonymous ? [ipKey] : [userKey!];
  if (isAnonymous && fingerKey) keysToCheck.push(fingerKey);

  // 1. Concurrency limit
  const maxConcurrency = isAnonymous ? 1 : 3;
  for (const key of keysToCheck) {
    const currentActive = activeRequests.get(key) || 0;
    if (currentActive >= maxConcurrency) {
      return res.status(429).json({
        success: false,
        code: 'RATE_LIMITED',
        error: 'Terlalu banyak permintaan secara bersamaan. Silakan tunggu permintaan sebelumnya selesai.'
      });
    }
  }

  // 2. Global Circuit Breaker
  const now = Date.now();
  if (now > globalDailyReset) {
    globalDailyUsage = 0;
    const tomorrow = new Date();
    tomorrow.setUTCHours(24, 0, 0, 0);
    globalDailyReset = tomorrow.getTime();
  }

  const GLOBAL_DAILY_LIMIT = process.env.GLOBAL_AI_BUDGET ? parseInt(process.env.GLOBAL_AI_BUDGET, 10) : 5000;
  if (globalDailyUsage >= GLOBAL_DAILY_LIMIT) {
    return res.status(503).json({
      success: false,
      code: 'GLOBAL_AI_LIMIT_REACHED',
      error: 'Layanan AI sedang mengalami beban tinggi secara global. Silakan coba lagi nanti.'
    });
  }

  // 3. Burst & Rate limits
  let allAllowed = true;
  const statesToUpdate: ClientState[] = [];

  for (const key of keysToCheck) {
    const { allowed, state } = updateAndCheckState(key, isAnonymous, now);
    if (!allowed) allAllowed = false;
    statesToUpdate.push(state);
  }

  if (!allAllowed) {
    return res.status(429).json({
      success: false,
      code: 'RATE_LIMITED',
      error: 'Batas permintaan tercapai. Silakan perlambat jeda obrolan.'
    });
  }

  // Challenge mechanism check
  const maxPerHour = isAnonymous ? 20 : 100;
  const challengeThreshold = isAnonymous ? (maxPerHour * 0.75) : (maxPerHour * 0.90);
  for (const state of statesToUpdate) {
    if (state.hourlyCount >= challengeThreshold) {
      res.setHeader('X-Challenge-Required', 'true');
      break;
    }
  }

  // Deduct token
  for (const state of statesToUpdate) {
    state.burstTokens -= 1;
    state.minuteCount += 1;
    state.hourlyCount += 1;
  }
  globalDailyUsage += 1;

  for (const key of keysToCheck) {
    activeRequests.set(key, (activeRequests.get(key) || 0) + 1);
  }

  let finished = false;
  const cleanup = () => {
    if (finished) return;
    finished = true;
    for (const key of keysToCheck) {
      const active = activeRequests.get(key) || 0;
      if (active > 0) {
        activeRequests.set(key, active - 1);
      }
    }
  };

  res.on('finish', cleanup);
  res.on('close', cleanup);

  next();
}

// Function for tests to reset state
export function resetAbuseState() {
  clientStates.clear();
  activeRequests.clear();
  globalDailyUsage = 0;
}

import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import { serverDb } from '../database.js';
import { getValidatedJwtSecret } from '../config/envValidation.js';

export const getJwtSecret = () => {
  return getValidatedJwtSecret();
};

export const getTokenFromReq = (req: Request) => {
  let token = req.cookies?.ruangtenang_session || req.cookies?.token;
  if (!token && req.headers.authorization?.startsWith('Bearer ')) {
    token = req.headers.authorization.split(' ')[1];
  }
  return token;
};

const verifyAndLoadSession = async (token: string, res: Response) => {
  try {
    const JWT_SECRET = getJwtSecret();
    const decoded = jwt.verify(token, JWT_SECRET, {
      issuer: 'ruangtenang',
      audience: 'ruangtenang-web',
      algorithms: ['HS256']
    }) as any;

    if (!decoded.sessionId || (!decoded.userId && !decoded.sub)) {
      throw new Error('INVALID_SESSION');
    }

    const userId = decoded.userId || decoded.sub;

    const isSessionValid = await serverDb.isSessionActive(userId, decoded.sessionId);
    if (!isSessionValid) {
      throw new Error('SESSION_REVOKED');
    }

    return decoded;
  } catch (err: unknown) {
    res.clearCookie('ruangtenang_session', { path: '/' });
    res.clearCookie('token', { path: '/' });
    if (err.message === 'SESSION_REVOKED') {
      throw err;
    }
    throw new Error('INVALID_SESSION');
  }
};

export const requireAuth = async (req: Request, res: Response, next: NextFunction) => {
  const token = getTokenFromReq(req);
  if (!token) {
    return res.status(401).json({ success: false, code: 'UNAUTHORIZED', message: 'Akses ditolak. Silakan login.' });
  }

  try {
    const decoded = await verifyAndLoadSession(token, res);
    req.user = decoded;
    next();
  } catch (err: unknown) {
    if (err.message === 'SESSION_REVOKED') {
      return res.status(401).json({ success: false, code: 'SESSION_REVOKED', message: 'Sesi perangkat ini telah dicabut atau dikeluarkan. Silakan masuk kembali.' });
    }
    return res.status(401).json({ success: false, code: 'INVALID_SESSION', message: 'Sesi tidak valid. Silakan masuk kembali.' });
  }
};

export const optionalAuth = async (req: Request, res: Response, next: NextFunction) => {
  const token = getTokenFromReq(req);
  if (token) {
    try {
      const decoded = await verifyAndLoadSession(token, res);
      req.user = decoded;
    } catch (err) {
      // Ignored for optional auth, user remains undefined, but cookies are cleared by verifyAndLoadSession
    }
  }
  next();
};

export const requireRole = (allowedRoles: ('mahasiswa' | 'konselor' | 'admin')[]) => {
  return (req: Request, res: Response, next: NextFunction) => {
    if (!req.user) {
      return res.status(401).json({ success: false, code: 'UNAUTHORIZED', message: 'Akses ditolak. Silakan login terlebih dahulu.' });
    }

    if (!allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ success: false, code: 'FORBIDDEN', message: 'Akses ditolak. Anda tidak memiliki izin untuk halaman ini.' });
    }

    next();
  };
};

/**
 * CSRF & Origin Verification Middleware
 * Protects state-changing mutations (POST, PUT, PATCH, DELETE) against Cross-Site Request Forgery.
 */

import { Request, Response, NextFunction } from 'express';

const SAFE_METHODS = new Set(['GET', 'HEAD', 'OPTIONS']);

export function csrfProtection(req: Request, res: Response, next: NextFunction) {
  const isProd = process.env.NODE_ENV === 'production';

  // 1. Safe read-only methods bypass CSRF checks
  if (SAFE_METHODS.has(req.method.toUpperCase())) {
    return next();
  }

  // 2. Exempt public webhook or server-to-server endpoints if any
  if (req.path.startsWith('/api/webhooks') || req.path.startsWith('/webhooks')) {
    return next();
  }

  // Check ambient credentials (cookies) vs non-ambient credentials (Bearer without cookies)
  const hasCookieAuth = Boolean(req.cookies?.ruangtenang_session || req.cookies?.token);
  const hasBearerAuth = Boolean(req.headers.authorization?.startsWith('Bearer '));

  // If NO ambient cookie is present and request uses pure Bearer auth, bypass CSRF
  if (!hasCookieAuth && hasBearerAuth) {
    return next();
  }

  // If NO auth cookie and NO bearer auth (e.g., public POST like /api/v1/auth/login or /api/v1/auth/register),
  // origin validation is still enforced in production to prevent cross-site form submissions against login/register endpoints!

  const origin = req.headers['origin'] as string;
  const referer = req.headers['referer'] as string;
  const host = req.headers['host'] as string;
  const csrfHeaderToken = req.headers['x-csrf-token'] as string;

  const sourceUrl = origin || referer;

  if (!sourceUrl) {
    // In production, state-changing mutations (especially with cookie auth) require Origin/Referer header or valid CSRF token
    if (isProd && (hasCookieAuth || !hasBearerAuth)) {
      if (!csrfHeaderToken) {
        return res.status(403).json({
          success: false,
          code: 'CSRF_ORIGIN_MISSING',
          error: 'Akses ditolak: Header Origin atau Referer wajib disertakan untuk mutasi data sensitif.'
        });
      }
    }
    return next();
  }

  // Validate origin/referer against host or configured allowlist
  try {
    const parsedSource = new URL(sourceUrl);
    const sourceHost = parsedSource.host.toLowerCase();
    const sourceOrigin = parsedSource.origin.toLowerCase();
    const sourceHostname = parsedSource.hostname.toLowerCase();

    // Resolve configured allowed origins
    const allowedOrigins = new Set<string>();
    if (process.env.APP_ORIGIN) {
      process.env.APP_ORIGIN.split(',').forEach(o => {
        if (o.trim()) allowedOrigins.add(o.trim().toLowerCase());
      });
    }
    if (process.env.CORS_ALLOWED_ORIGINS) {
      process.env.CORS_ALLOWED_ORIGINS.split(',').forEach(o => {
        if (o.trim()) allowedOrigins.add(o.trim().toLowerCase());
      });
    }
    if (!isProd) {
      allowedOrigins.add('https://ruangtenang.ai.studio');
      allowedOrigins.add('https://ruangtenang.ui.ac.id');
    }

    // Exact host match
    const isSameHost = host && (sourceHost === host.toLowerCase() || sourceHost.split(':')[0] === host.toLowerCase().split(':')[0]);
    const isExplicitlyAllowed = allowedOrigins.has(sourceOrigin);
    const isLocalhost = sourceHostname === 'localhost' || sourceHostname === '127.0.0.1' || sourceHostname === '0.0.0.0';
    const isPlatformDomain = sourceHostname.endsWith('.run.app') ||
                             sourceHostname.endsWith('.studio') ||
                             sourceHostname.endsWith('.ai.studio') ||
                             sourceOrigin === 'https://ai.studio' ||
                             sourceHostname.endsWith('.google.com') ||
                             sourceHostname.endsWith('.google.dev');

    // In production, strictly enforce same host or explicit allowlist. Wildcard platform domains only allowed in dev/staging.
    const isMatch = isProd
      ? (isSameHost || isExplicitlyAllowed)
      : (isSameHost || isExplicitlyAllowed || isPlatformDomain || isLocalhost);

    if (isMatch) {
      return next();
    }

    // Origin mismatch
    console.warn(`[CSRF WARNING] Blocked mutation request from untrusted origin: ${sourceUrl} (Host: ${host})`);
    return res.status(403).json({
      success: false,
      code: 'CSRF_FORBIDDEN',
      error: 'Akses ditolak: Permintaan mutasi dari origin tidak dikenal diblokir demi keamanan privasi akun.'
    });
  } catch (err) {
    return res.status(403).json({
      success: false,
      code: 'CSRF_INVALID_ORIGIN',
      error: 'Akses ditolak: Format origin tidak valid.'
    });
  }
}

