import { prisma } from "../database";
import { AppointmentRecord } from "../database";
import { auditRepository } from "./auditRepository";
import { encryptionService } from "../services/encryptionService";
import { redisService } from "../services/redisService";

const HARD_MAX_PAGE_SIZE = 100;

function mapDbAppointmentToRecord(a: any): AppointmentRecord {
  return {
    ...a,
    timezone: a.timezone as any,
    status: a.status as any,
    approvalStatus: a.approvalStatus as any,
    attendanceStatus: a.attendanceStatus as any,
    mode: a.mode as any,
    createdAt: a.createdAt.toISOString(),
    notes: a.notes ? (encryptionService.decryptSensitive(a.notes) || a.notes) : undefined,
    meetingLink: a.meetingLink || undefined,
    userId: a.userId || undefined,
    studentName: a.studentName || undefined,
    studentNIM: a.studentNIM ? (encryptionService.decryptSensitive(a.studentNIM) || a.studentNIM) : undefined,
    studentEmail: a.studentEmail ? (encryptionService.decryptSensitive(a.studentEmail) || a.studentEmail) : undefined,
  };
}

export const appointmentRepository = {
  async cleanOldAppointments(cutoffDate: Date): Promise<number> {
    const { count } = await prisma.appointments.deleteMany({
      where: {
        createdAt: {
          lt: cutoffDate
        }
      }
    });
    return count;
  },

  async getAppointments(limit = 100, offset = 0, userId?: string): Promise<AppointmentRecord[]> {
    const take = Math.min(limit, HARD_MAX_PAGE_SIZE);
    const where = userId ? { userId } : {};

    const list = await prisma.appointments.findMany({
      where,
      orderBy: { createdAt: "desc" },
      take,
      skip: offset,
    });

    return list.map(mapDbAppointmentToRecord);
  },

  async findAppointmentById(id: string): Promise<AppointmentRecord | null> {
    const a = await prisma.appointments.findUnique({
      where: { id },
    });
    if (!a) return null;

    return mapDbAppointmentToRecord(a);
  },

  async getAppointmentAvailability(counselorId: string, date: string) {
    const cacheKey = `availability:${counselorId}:${date}`;
    const cached = await redisService.get<any>(cacheKey);
    if (cached) {
      return cached;
    }

    const standardSlots = ["09:00", "10:30", "14:00", "16:00"];

    // Find slots currently reserved in the database
    const activeSlots = await prisma.appointmentSlot.findMany({
      where: {
        counselorId,
        date,
      },
    });

    const bookedSlots = activeSlots.map((s) => s.time);
    const availableSlots = standardSlots.filter(
      (slot) => !bookedSlots.includes(slot),
    );

    const result = {
      counselorId,
      date,
      allSlots: standardSlots,
      bookedSlots,
      availableSlots,
      fullyBooked: availableSlots.length === 0,
    };

    // Cache availability for 60 seconds
    await redisService.set(cacheKey, result, 60);

    return result;
  },

  async addAppointment(
    appt: Omit<AppointmentRecord, "id" | "createdAt">,
  ): Promise<AppointmentRecord> {
    const id = "appt-" + Date.now() + "-" + Math.floor(Math.random() * 1000);
    const initialStatus = appt.status || "PENDING";
    const initialApproval =
      appt.approvalStatus ||
      (initialStatus === "CONFIRMED" ? "APPROVED" : "PENDING_APPROVAL");

    // Application-Level AES-256-GCM encryption with key versioning
    const encryptedNotes = appt.notes ? encryptionService.encryptSensitive(appt.notes) : null;
    const encryptedNIM = appt.studentNIM ? encryptionService.encryptSensitive(appt.studentNIM) : null;
    const encryptedEmail = appt.studentEmail ? encryptionService.encryptSensitive(appt.studentEmail) : null;

    return await prisma.$transaction(async (tx) => {
      const isCancelledOrRejected = ["CANCELLED", "REJECTED"].includes(initialStatus);

      let resolvedCounselorId = appt.counselorId;
      if (!resolvedCounselorId && appt.counselorName) {
        const found = await tx.counselors.findFirst({
          where: { name: appt.counselorName }
        });
        if (found) {
          resolvedCounselorId = found.id;
        } else {
          const newCns = await tx.counselors.create({
            data: {
              id: "cns-" + Date.now() + "-" + Math.floor(Math.random() * 1000),
              name: appt.counselorName,
              role: "Konselor Mahasiswa",
              specialties: JSON.stringify(["Konseling Umum"]),
              imageUrl: "https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?w=150",
              availability: JSON.stringify(["Senin", "Selasa", "Rabu", "Kamis", "Jumat"]),
              isVerified: true
            }
          });
          resolvedCounselorId = newCns.id;
        }
      }

      if (!resolvedCounselorId) {
        const fallbackCns = await tx.counselors.findFirst();
        if (fallbackCns) {
          resolvedCounselorId = fallbackCns.id;
        } else {
          const defaultCns = await tx.counselors.create({
            data: {
              id: "cons-1",
              name: appt.counselorName || "Dr. Anita Rahmawati, M.Psi.",
              role: "Konselor Mahasiswa",
              specialties: JSON.stringify(["Konseling Umum"]),
              imageUrl: "https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?w=150",
              availability: JSON.stringify(["Senin", "Selasa", "Rabu", "Kamis", "Jumat"]),
              isVerified: true
            }
          });
          resolvedCounselorId = defaultCns.id;
        }
      }

      // Check for slot availability if it's not cancelled/rejected
      if (!isCancelledOrRejected) {
        const conflict = await tx.appointments.findFirst({
          where: {
            counselorId: resolvedCounselorId,
            date: appt.date,
            time: appt.time,
            status: { notIn: ['CANCELLED', 'REJECTED'] }
          }
        });

        if (conflict) {
          throw new Error('SLOT_ALREADY_BOOKED');
        }
      }

      const created = await tx.appointments.create({
        data: {
          id,
          counselorId: resolvedCounselorId,
          counselorName: appt.counselorName,
          date: appt.date,
          time: appt.time,
          timezone: appt.timezone || "WIB",
          notes: encryptedNotes,
          status: initialStatus,
          approvalStatus: initialApproval,
          attendanceStatus: appt.attendanceStatus || "SCHEDULED",
          meetingLink: appt.meetingLink || "",
          mode: appt.mode || "Virtual Video Call",
          userId: appt.userId || null,
          studentName: appt.studentName || null,
          studentNIM: encryptedNIM,
          studentEmail: encryptedEmail,
        },
      });

      if (!isCancelledOrRejected) {
        // Enforce slot constraint at database level
        const slotId = `slot-${resolvedCounselorId}-${appt.date}-${appt.time}`;
        try {
          await tx.appointmentSlot.create({
            data: {
              id: slotId,
              counselorId: resolvedCounselorId,
              date: appt.date,
              time: appt.time,
              appointmentId: id,
            },
          });
        } catch (error: unknown) {
          // P2002 is Prisma unique constraint violation code
          if (error.code === "P2002") {
            throw new Error("SLOT_ALREADY_BOOKED");
          }
          throw error;
        }
      }

      try {
        await tx.auditLogs.create({
          data: {
            id: "log-" + Date.now() + "-" + Math.floor(Math.random() * 1000),
            action: "CREATE_APPOINTMENT",
            details: `Jadwal konseling (Status: ${initialStatus}) dibuat untuk ID sesi ${id} tanggal ${appt.date} (${created.timezone})`,
            timestamp: new Date(),
            userRole: appt.userId || "mahasiswa",
          }
        });
      } catch (logErr) {
        console.warn('Non-fatal audit log failure in transaction:', logErr);
      }

      // Invalidate slot availability cache
      await redisService.del(`availability:${resolvedCounselorId}:${appt.date}`);

      return mapDbAppointmentToRecord(created);
    });
  },

  async updateAppointment(
    id: string,
    updates: Partial<AppointmentRecord>,
  ): Promise<AppointmentRecord | null> {
    return await prisma.$transaction(async (tx) => {
      const current = await tx.appointments.findUnique({ where: { id } });
      if (!current) return null;

      const targetCounselorId = updates.counselorId || current.counselorId;
      const targetDate = updates.date || current.date;
      const targetTime = updates.time || current.time;
      const targetStatus = updates.status || current.status;

      const isCancelledOrRejected = ["CANCELLED", "REJECTED"].includes(targetStatus);
      const isChangingSlot =
        (updates.date && updates.date !== current.date) ||
        (updates.time && updates.time !== current.time) ||
        (updates.counselorId && updates.counselorId !== current.counselorId);

      const wasCancelledOrRejected = ["CANCELLED", "REJECTED"].includes(current.status);

      if (isCancelledOrRejected) {
        // Free up slot immediately
        await tx.appointmentSlot.deleteMany({
          where: { appointmentId: id },
        });
      } else if (isChangingSlot || wasCancelledOrRejected) {
        // Clear previous slot
        await tx.appointmentSlot.deleteMany({
          where: { appointmentId: id },
        });

        // Reserve new slot under transaction
        const slotId = `slot-${targetCounselorId}-${targetDate}-${targetTime}`;
        try {
          await tx.appointmentSlot.create({
            data: {
              id: slotId,
              counselorId: targetCounselorId,
              date: targetDate,
              time: targetTime,
              appointmentId: id,
            },
          });
        } catch (error: unknown) {
          if (error.code === "P2002") {
            throw new Error("SLOT_ALREADY_BOOKED");
          }
          throw error;
        }
      }

      const encryptedNotes = updates.notes !== undefined 
        ? (updates.notes ? encryptionService.encryptSensitive(updates.notes) : null) 
        : current.notes;
      const encryptedNIM = updates.studentNIM !== undefined 
        ? (updates.studentNIM ? encryptionService.encryptSensitive(updates.studentNIM) : null) 
        : current.studentNIM;
      const encryptedEmail = updates.studentEmail !== undefined 
        ? (updates.studentEmail ? encryptionService.encryptSensitive(updates.studentEmail) : null) 
        : current.studentEmail;

      const updated = await tx.appointments.update({
        where: { id },
        data: {
          counselorId: updates.counselorId,
          counselorName: updates.counselorName,
          date: updates.date,
          time: updates.time,
          timezone: updates.timezone,
          notes: encryptedNotes,
          status: updates.status,
          approvalStatus: updates.approvalStatus,
          attendanceStatus: updates.attendanceStatus,
          meetingLink: updates.meetingLink,
          mode: updates.mode,
          userId: updates.userId,
          studentName: updates.studentName,
          studentNIM: encryptedNIM,
          studentEmail: encryptedEmail,
        },
      });

      try {
        await tx.auditLogs.create({
          data: {
            id: "log-" + Date.now() + "-" + Math.floor(Math.random() * 1000),
            action: "UPDATE_APPOINTMENT",
            details: `Jadwal konseling ID ${id} diperbarui. Status: ${updated.status}`,
            timestamp: new Date(),
            userRole: "konselor",
          }
        });
      } catch (logErr) {
        console.warn('Non-fatal audit log failure in transaction:', logErr);
      }

      // Invalidate slot availability cache
      await redisService.del(`availability:${current.counselorId}:${current.date}`);
      if (targetCounselorId !== current.counselorId || targetDate !== current.date) {
        await redisService.del(`availability:${targetCounselorId}:${targetDate}`);
      }

      return mapDbAppointmentToRecord(updated);
    });
  },

  async deleteAppointment(id: string): Promise<boolean> {
    try {
      await prisma.$transaction(async (tx) => {
        const appt = await tx.appointments.findUnique({ where: { id } });

        await tx.appointmentSlot.deleteMany({
          where: { appointmentId: id },
        });

        await tx.appointments.delete({
          where: { id },
        });

        await tx.auditLogs.create({
          data: {
            id: "log-" + Date.now() + "-" + Math.floor(Math.random() * 1000),
            action: "DELETE_APPOINTMENT",
            details: `Jadwal konseling ID ${id} dihapus.`,
            timestamp: new Date(),
            userRole: "admin",
          }
        });

        if (appt) {
          await redisService.del(`availability:${appt.counselorId}:${appt.date}`);
        }
      });

      return true;
    } catch {
      return false;
    }
  },
};

import { prisma } from "../database";
import { ActiveSession, LoginHistoryEntry, SecurityNotification, UserRecord } from "../database";
import { mapUserToRecord, migrateLegacyUserDataIfNeeded } from "./userRepository";
import { auditRepository } from "./auditRepository";
import crypto from "crypto";

export const authRepository = {
  // Active Sessions & Revocation
  async addActiveSession(userId: string, session: ActiveSession): Promise<void> {
    const hashedSessionId = crypto.createHash('sha256').update(session.sessionId).digest('hex');

    await prisma.userSession.upsert({
      where: { id: hashedSessionId },
      update: {
        device: session.device,
        ip: session.ip,
        userAgent: session.userAgent,
        lastActive: new Date(),
      },
      create: {
        id: hashedSessionId,
        userId,
        device: session.device,
        ip: session.ip,
        userAgent: session.userAgent,
        createdAt: session.createdAt ? new Date(session.createdAt) : new Date(),
        lastActive: new Date(),
      },
    });

    // Enforce max 10 sessions per user
    const userSessions = await prisma.userSession.findMany({
      where: { userId },
      orderBy: { lastActive: "desc" },
    });

    if (userSessions.length > 10) {
      const obsolete = userSessions.slice(10);
      await prisma.userSession.deleteMany({
        where: { id: { in: obsolete.map(s => s.id) } },
      });
    }
  },

  async getActiveSessions(userId: string): Promise<ActiveSession[]> {
    let sessions = await prisma.userSession.findMany({
      where: { userId },
      orderBy: { lastActive: "desc" },
    });

    if (sessions.length === 0) {
      const user = await prisma.users.findUnique({ where: { id: userId } });
      if (user && user.activeSessions && user.activeSessions !== "[]") {
        await migrateLegacyUserDataIfNeeded(user);
        sessions = await prisma.userSession.findMany({
          where: { userId },
          orderBy: { lastActive: "desc" },
        });
      }
    }

    return sessions.map(s => ({
      sessionId: s.id,
      device: s.device,
      ip: s.ip,
      userAgent: s.userAgent,
      createdAt: s.createdAt.toISOString(),
      lastActive: s.lastActive.toISOString(),
    }));
  },

  async removeActiveSession(userId: string, sessionId: string): Promise<void> {
    const hashedId = crypto.createHash('sha256').update(sessionId).digest('hex');
    const user = await prisma.users.findUnique({ where: { id: userId } });
    if (user && user.activeSessions && user.activeSessions !== "[]") {
      await migrateLegacyUserDataIfNeeded(user);
    }

    await prisma.userSession.deleteMany({
      where: {
        userId,
        OR: [
          { id: sessionId },
          { id: hashedId },
        ],
      },
    });
  },

  async removeAllActiveSessions(userId: string): Promise<void> {
    await prisma.$transaction(async (tx) => {
      await tx.userSession.deleteMany({
        where: { userId },
      });
      await tx.users.update({
        where: { id: userId },
        data: { activeSessions: "[]" }
      });
    });
  },

  async isSessionActive(userId: string, sessionId: string): Promise<boolean> {
    const hashedId = crypto.createHash('sha256').update(sessionId).digest('hex');
    const count = await prisma.userSession.count({
      where: {
        userId,
        OR: [
          { id: sessionId },
          { id: hashedId },
        ],
      },
    });
    if (count > 0) return true;

    const user = await prisma.users.findUnique({ where: { id: userId } });
    if (user && user.activeSessions && user.activeSessions !== "[]") {
      try {
        const parsed = JSON.parse(user.activeSessions);
        if (Array.isArray(parsed)) {
          const match = parsed.find(s => s.sessionId === sessionId || s.sessionId === hashedId);
          if (match) {
            await migrateLegacyUserDataIfNeeded(user);
            return true;
          }
        }
      } catch (e) {
        console.error("isSessionActive fallback migration failed:", e);
      }
    }
    return false;
  },

  // Login History & Security Logs
  async recordLoginHistory(
    userId: string,
    entry: Omit<LoginHistoryEntry, "id" | "timestamp">,
  ): Promise<LoginHistoryEntry> {
    const id = "log-" + Date.now() + "-" + Math.floor(Math.random() * 1000);
    const timestamp = new Date();

    const created = await prisma.loginEvent.create({
      data: {
        id,
        userId,
        timestamp,
        ip: entry.ip,
        userAgent: entry.userAgent,
        status: entry.status,
        location: entry.location || null,
      },
    });

    // Prune history to keep only latest 50 events per user
    const historyCount = await prisma.loginEvent.count({ where: { userId } });
    if (historyCount > 50) {
      const excess = historyCount - 50;
      const oldest = await prisma.loginEvent.findMany({
        where: { userId },
        orderBy: { timestamp: "asc" },
        take: excess,
      });
      await prisma.loginEvent.deleteMany({
        where: { id: { in: oldest.map(e => e.id) } },
      });
    }

    return {
      id: created.id,
      timestamp: created.timestamp.toISOString(),
      ip: created.ip,
      userAgent: created.userAgent,
      status: created.status as any,
      location: created.location || undefined,
    };
  },

  async getLoginHistory(userId: string): Promise<LoginHistoryEntry[]> {
    let list = await prisma.loginEvent.findMany({
      where: { userId },
      orderBy: { timestamp: "desc" },
      take: 50,
    });

    if (list.length === 0) {
      const user = await prisma.users.findUnique({ where: { id: userId } });
      if (user && user.loginHistory && user.loginHistory !== "[]") {
        await migrateLegacyUserDataIfNeeded(user);
        list = await prisma.loginEvent.findMany({
          where: { userId },
          orderBy: { timestamp: "desc" },
          take: 50,
        });
      }
    }

    return list.map(e => ({
      id: e.id,
      timestamp: e.timestamp.toISOString(),
      ip: e.ip,
      userAgent: e.userAgent,
      status: e.status as any,
      location: e.location || undefined,
    }));
  },

  // Account Lockout & Failed Attempt Rate Limiting
  async recordFailedAttempt(
    userIdOrEmail: string,
  ): Promise<{
    failedAttempts: number;
    isLocked: boolean;
    lockUntil?: string;
  }> {
    const user = await prisma.users.findFirst({
      where: {
        OR: [
          { email: userIdOrEmail.toLowerCase().trim() },
          { id: userIdOrEmail },
        ],
      },
    });

    if (!user) return { failedAttempts: 0, isLocked: false };

    const failedAttempts = user.failedLoginAttempts + 1;
    let isLocked = false;
    let lockUntil: string | undefined = undefined;
    let lockUntilDate: Date | null = null;

    if (failedAttempts >= 5) {
      const lockMs = 15 * 60 * 1000;
      lockUntilDate = new Date(Date.now() + lockMs);
      isLocked = true;
      lockUntil = lockUntilDate.toISOString();
      await auditRepository.logAudit(
        "ACCOUNT_LOCKED",
        `Akun ${user.email} dikunci sementara selama 15 menit akibat 5x kesalahan kata sandi.`,
        user.id,
      );
    }

    await prisma.users.update({
      where: { id: user.id },
      data: {
        failedLoginAttempts: failedAttempts,
        lockUntil: lockUntilDate,
      },
    });

    return { failedAttempts, isLocked, lockUntil };
  },

  async resetFailedAttempts(userId: string): Promise<void> {
    await prisma.users.update({
      where: { id: userId },
      data: {
        failedLoginAttempts: 0,
        lockUntil: null,
      },
    });
  },

  isAccountLocked(user: any): { locked: boolean; lockUntil?: string } {
    if (user.lockUntil) {
      const lockTime = new Date(user.lockUntil).getTime();
      if (Date.now() < lockTime) {
        return {
          locked: true,
          lockUntil:
            typeof user.lockUntil === "string"
              ? user.lockUntil
              : user.lockUntil.toISOString(),
        };
      }
    }
    return { locked: false };
  },

  // Email Verification
  async setEmailVerificationCode(userId: string, code: string): Promise<void> {
    const hashedCode = crypto.createHash('sha256').update(code).digest('hex');
    await prisma.users.update({
      where: { id: userId },
      data: {
        emailVerificationCode: hashedCode,
        emailVerificationExpires: new Date(Date.now() + 24 * 60 * 60 * 1000),
      },
    });
  },

  async verifyEmail(userId: string, code: string): Promise<boolean> {
    const user = await prisma.users.findUnique({ where: { id: userId } });
    if (!user) return false;

    if (user.emailVerificationExpires && new Date(user.emailVerificationExpires).getTime() < Date.now()) {
      return false;
    }

    const hashedInput = crypto.createHash('sha256').update(code.trim()).digest('hex');
    if (user.emailVerificationCode === hashedInput) {
      await prisma.users.update({
        where: { id: userId },
        data: {
          emailVerified: true,
          emailVerificationCode: null,
          emailVerificationExpires: null,
        },
      });
      await auditRepository.logAudit(
        "EMAIL_VERIFIED",
        `Email ${user.email} berhasil diverifikasi.`,
        user.id,
      );
      return true;
    }
    return false;
  },

  // Password Reset Token (Single Use)
  async setPasswordResetToken(email: string, token: string): Promise<boolean> {
    const user = await prisma.users.findUnique({
      where: { email: email.toLowerCase().trim() },
    });
    if (!user) return false;

    const hashedToken = crypto.createHash('sha256').update(token.trim()).digest('hex');
    await prisma.users.update({
      where: { id: user.id },
      data: {
        passwordResetToken: hashedToken,
        passwordResetExpires: new Date(Date.now() + 30 * 60 * 1000),
      },
    });
    await auditRepository.logAudit(
      "PASSWORD_RESET_REQUESTED",
      `Token reset kata sandi dibuat untuk ${user.email}`,
      user.id,
    );
    return true;
  },

  async resetPasswordWithToken(
    token: string,
    newPasswordHash: string,
  ): Promise<{ success: boolean; message: string; userId?: string }> {
    const hashedToken = crypto.createHash('sha256').update(token.trim()).digest('hex');
    const user = await prisma.users.findFirst({
      where: { passwordResetToken: hashedToken },
    });

    if (!user) {
      return {
        success: false,
        message: "Token reset kata sandi tidak ditemukan atau sudah tidak berlaku.",
      };
    }

    if (
      user.passwordResetExpires &&
      new Date(user.passwordResetExpires).getTime() < Date.now()
    ) {
      return {
        success: false,
        message: "Token reset kata sandi sudah kadaluwarsa. Silakan minta token baru.",
      };
    }

    await prisma.users.update({
      where: { id: user.id },
      data: {
        passwordHash: newPasswordHash,
        passwordResetToken: null,
        passwordResetExpires: null,
      },
    });

    await prisma.userSession.deleteMany({
      where: { userId: user.id },
    });

    await auditRepository.logAudit(
      "PASSWORD_RESET_SUCCESS",
      `Kata sandi diperbarui melalui token reset untuk ${user.email}. Seluruh sesi dicabut.`,
      user.id,
    );
    return {
      success: true,
      message: "Kata sandi berhasil diperbarui. Silakan masuk kembali.",
      userId: user.id,
    };
  },

  // MFA (Multi-Factor Authentication) with Hashed Storage & Replay Prevention
  async setMfaCode(
    userId: string,
    code: string,
    mfaToken: string,
  ): Promise<void> {
    const hashedCode = crypto.createHash('sha256').update(code.trim()).digest('hex');
    const hashedToken = crypto.createHash('sha256').update(mfaToken.trim()).digest('hex');

    await prisma.users.update({
      where: { id: userId },
      data: {
        mfaCode: hashedCode,
        mfaToken: hashedToken,
        mfaExpires: new Date(Date.now() + 10 * 60 * 1000), // 10 minute expiry
      },
    });
  },

  async verifyMfaCode(
    mfaToken: string,
    code: string,
  ): Promise<UserRecord | null> {
    const trimmedToken = mfaToken.trim();
    const trimmedCode = code.trim();
    const hashedToken = crypto.createHash('sha256').update(trimmedToken).digest('hex');

    const user = await prisma.users.findFirst({
      where: { mfaToken: hashedToken },
    });
    if (!user) return null;

    // Check expiration
    if (user.mfaExpires && new Date(user.mfaExpires).getTime() < Date.now()) {
      // Invalidate expired challenge
      await prisma.users.update({
        where: { id: user.id },
        data: { mfaCode: null, mfaToken: null, mfaExpires: null },
      });
      return null;
    }

    if (!user.mfaCode) return null;

    // Constant-time timing-safe comparison on hash
    const hashedInput = crypto.createHash('sha256').update(trimmedCode).digest('hex');
    let isMatch = false;

    if (user.mfaCode.length === 64) {
      const inputBuf = Buffer.from(hashedInput, 'utf-8');
      const storedBuf = Buffer.from(user.mfaCode, 'utf-8');
      isMatch = inputBuf.length === storedBuf.length && crypto.timingSafeEqual(inputBuf, storedBuf);
    }

    if (isMatch) {
      // One-time consumption: immediately destroy MFA secrets
      const updated = await prisma.users.update({
        where: { id: user.id },
        data: {
          mfaCode: null,
          mfaToken: null,
          mfaExpires: null,
          failedLoginAttempts: 0,
        },
      });

      await auditRepository.logAudit(
        "MFA_VERIFIED",
        `Autentikasi Multi-Faktor (MFA) berhasil untuk user ID ${user.id}`,
        user.id,
      );
      return mapUserToRecord(updated);
    } else {
      // Failed attempt on MFA: track and limit to max 3 attempts
      const newFailed = (user.failedLoginAttempts || 0) + 1;
      if (newFailed >= 3) {
        // Invalidate MFA challenge to prevent brute force
        await prisma.users.update({
          where: { id: user.id },
          data: {
            mfaCode: null,
            mfaToken: null,
            mfaExpires: null,
            failedLoginAttempts: newFailed,
          },
        });
      } else {
        await prisma.users.update({
          where: { id: user.id },
          data: { failedLoginAttempts: newFailed },
        });
      }
      return null;
    }
  },

  // Security Notifications
  async addSecurityNotification(
    userId: string,
    title: string,
    message: string,
  ): Promise<SecurityNotification> {
    const id = "secnotif-" + Date.now() + "-" + Math.floor(Math.random() * 1000);
    const timestamp = new Date();

    const created = await prisma.securityNotification.create({
      data: {
        id,
        userId,
        title,
        message,
        timestamp,
        read: false,
      },
    });

    // Prune security notifications to keep only latest 20 per user
    const notificationsCount = await prisma.securityNotification.count({ where: { userId } });
    if (notificationsCount > 20) {
      const excess = notificationsCount - 20;
      const oldest = await prisma.securityNotification.findMany({
        where: { userId },
        orderBy: { timestamp: "asc" },
        take: excess,
      });
      await prisma.securityNotification.deleteMany({
        where: { id: { in: oldest.map(n => n.id) } },
      });
    }

    return {
      id: created.id,
      title: created.title,
      message: created.message,
      timestamp: created.timestamp.toISOString(),
      read: created.read,
    };
  },

  async getSecurityNotifications(userId: string): Promise<SecurityNotification[]> {
    let list = await prisma.securityNotification.findMany({
      where: { userId },
      orderBy: { timestamp: "desc" },
      take: 20,
    });

    if (list.length === 0) {
      const user = await prisma.users.findUnique({ where: { id: userId } });
      if (user && user.securityNotifications && user.securityNotifications !== "[]") {
        await migrateLegacyUserDataIfNeeded(user);
        list = await prisma.securityNotification.findMany({
          where: { userId },
          orderBy: { timestamp: "desc" },
          take: 20,
        });
      }
    }

    return list.map(n => ({
      id: n.id,
      title: n.title,
      message: n.message,
      timestamp: n.timestamp.toISOString(),
      read: n.read,
    }));
  },

  // Profile Security Updates
  async updateUserPassword(
    userId: string,
    newPasswordHash: string,
  ): Promise<boolean> {
    try {
      await prisma.$transaction(async (tx) => {
        await tx.users.update({
          where: { id: userId },
          data: {
            passwordHash: newPasswordHash,
            activeSessions: "[]",
          },
        });

        await tx.userSession.deleteMany({
          where: { userId },
        });
      });

      await this.addSecurityNotification(
        userId,
        "🔑 Kata Sandi Diperbarui",
        "Kata sandi akun Anda baru saja diperbarui. Seluruh sesi aktif telah dicabut.",
      );
      await auditRepository.logAudit(
        "UPDATE_PASSWORD",
        `Pengguna ID ${userId} memperbarui kata sandi akun.`,
        userId,
      );
      return true;
    } catch {
      return false;
    }
  },

  async updateUserEmail(userId: string, newEmail: string): Promise<boolean> {
    try {
      const user = await prisma.users.findUnique({ where: { id: userId } });
      if (!user) return false;

      const oldEmail = user.email;
      await prisma.users.update({
        where: { id: userId },
        data: {
          email: newEmail,
          emailVerified: false,
        },
      });

      await this.addSecurityNotification(
        userId,
        "📧 Email Diubah",
        `Email akun Anda telah diubah dari ${oldEmail} menjadi ${newEmail}. Silakan verifikasi email baru Anda.`,
      );
      await auditRepository.logAudit(
        "UPDATE_EMAIL",
        `Pengguna ID ${userId} mengubah email dari ${oldEmail} ke ${newEmail}`,
        userId,
      );
      return true;
    } catch {
      return false;
    }
  },
};

