import { prisma } from "../database";
import { ScreeningRecord } from "../database";
import { auditRepository } from "./auditRepository";
import { encryptionService } from "../services/encryptionService";

const HARD_MAX_PAGE_SIZE = 100;

function parseRiskIndicators(raw: string | null | undefined): string[] | undefined {
  if (!raw) return undefined;
  try {
    const decrypted = encryptionService.decryptSensitive(raw) || raw;
    return JSON.parse(decrypted);
  } catch {
    return undefined;
  }
}

function mapDbScreeningToRecord(s: any): ScreeningRecord {
  return {
    ...s,
    timestamp: s.timestamp.toISOString(),
    item9Score: s.item9Score ?? undefined,
    hasSelfHarmRisk: s.hasSelfHarmRisk ?? undefined,
    riskLevel: s.riskLevel || undefined,
    riskIndicators: parseRiskIndicators(s.riskIndicators),
    status: s.status as any,
    userId: s.userId || undefined,
  };
}

export const screeningRepository = {
  async getScreenings(limit = 20, offset = 0, userId?: string): Promise<ScreeningRecord[]> {
    const take = Math.min(limit, HARD_MAX_PAGE_SIZE);
    const where = userId ? { userId } : {};

    const list = await prisma.screenings.findMany({
      where,
      orderBy: { timestamp: "desc" },
      take,
      skip: offset,
    });

    return list.map(mapDbScreeningToRecord);
  },

  async countScreenings(userId?: string): Promise<number> {
    const where = userId ? { userId } : {};
    return await prisma.screenings.count({ where });
  },

  async findScreeningById(id: string): Promise<ScreeningRecord | null> {
    const s = await prisma.screenings.findUnique({
      where: { id },
    });
    if (!s) return null;

    return mapDbScreeningToRecord(s);
  },

  async addScreening(
    screening: Omit<ScreeningRecord, "id" | "timestamp">,
  ): Promise<ScreeningRecord> {
    const id = "scr-" + Date.now() + "-" + Math.floor(Math.random() * 1000);
    const timestamp = new Date();

    // Application-level encryption of clinical textual indicators
    let encryptedIndicators: string | null = null;
    if (screening.riskIndicators) {
      const jsonStr = JSON.stringify(screening.riskIndicators);
      encryptedIndicators = encryptionService.encryptSensitive(jsonStr);
    }

    const created = await prisma.screenings.create({
      data: {
        id,
        phq9Score: screening.phq9Score,
        gad7Score: screening.gad7Score,
        phq9Severity: screening.phq9Severity,
        gad7Severity: screening.gad7Severity,
        item9Score: screening.item9Score ?? null,
        hasSelfHarmRisk: screening.hasSelfHarmRisk ?? null,
        riskLevel: screening.riskLevel || null,
        riskIndicators: encryptedIndicators,
        status: screening.status || "Menunggu Penanganan",
        timestamp,
        userId: screening.userId || null,
      },
    });

    await auditRepository.logAudit(
      "SCREENING_SUBMITTED",
      `Hasil screening kesehatan mental tersimpan untuk subject ID ${screening.userId || "guest"}. Status: ${created.status}`,
      screening.userId || "guest",
    );

    return mapDbScreeningToRecord(created);
  },

  async updateScreeningStatus(
    id: string,
    status: "Menunggu Penanganan" | "Sedang Ditangani" | "Selesai Penanganan",
  ): Promise<ScreeningRecord | null> {
    const current = await prisma.screenings.findUnique({ where: { id } });
    if (!current) return null;

    const updated = await prisma.screenings.update({
      where: { id },
      data: { status },
    });

    return mapDbScreeningToRecord(updated);
  },
};

import { prisma } from "../database";
import { UserRecord, ActiveSession, LoginHistoryEntry, SecurityNotification } from "../database";
import { auditRepository } from "./auditRepository";
import crypto from "crypto";

const HARD_MAX_PAGE_SIZE = 100;

export async function migrateLegacyUserDataIfNeeded(user: any): Promise<void> {
  // 1. Sessions migration
  if (user.activeSessions && user.activeSessions !== "[]") {
    try {
      const parsedSessions = JSON.parse(user.activeSessions);
      if (Array.isArray(parsedSessions) && parsedSessions.length > 0) {
        for (const session of parsedSessions) {
          if (!session.sessionId) continue;
          const exists = await prisma.userSession.findUnique({
            where: { id: session.sessionId },
          });
          if (!exists) {
            await prisma.userSession.create({
              data: {
                id: session.sessionId,
                userId: user.id,
                device: session.device || "Unknown",
                ip: session.ip || session.ipAddress || "127.0.0.1",
                userAgent: session.userAgent || "Unknown",
                createdAt: session.createdAt ? new Date(session.createdAt) : new Date(),
                lastActive: session.lastActive ? new Date(session.lastActive) : new Date(),
              },
            });
          }
        }
      }
    } catch (e) {
      console.error("[MIGRATION_ERROR] activeSessions migration failed:", e);
    }
  }

  // 2. Login history migration
  if (user.loginHistory && user.loginHistory !== "[]") {
    try {
      const parsedHistory = JSON.parse(user.loginHistory);
      if (Array.isArray(parsedHistory) && parsedHistory.length > 0) {
        for (const event of parsedHistory) {
          if (!event.id) continue;
          const exists = await prisma.loginEvent.findUnique({
            where: { id: event.id },
          });
          if (!exists) {
            await prisma.loginEvent.create({
              data: {
                id: event.id,
                userId: user.id,
                timestamp: event.timestamp ? new Date(event.timestamp) : new Date(),
                ip: event.ip || "127.0.0.1",
                userAgent: event.userAgent || "Unknown",
                status: event.status || "SUCCESS",
                location: event.location || null,
              },
            });
          }
        }
      }
    } catch (e) {
      console.error("[MIGRATION_ERROR] loginHistory migration failed:", e);
    }
  }

  // 3. Security notifications migration
  if (user.securityNotifications && user.securityNotifications !== "[]") {
    try {
      const parsedNotifs = JSON.parse(user.securityNotifications);
      if (Array.isArray(parsedNotifs) && parsedNotifs.length > 0) {
        for (const notif of parsedNotifs) {
          if (!notif.id) continue;
          const exists = await prisma.securityNotification.findUnique({
            where: { id: notif.id },
          });
          if (!exists) {
            await prisma.securityNotification.create({
              data: {
                id: notif.id,
                userId: user.id,
                title: notif.title || "Security Notification",
                message: notif.message || "",
                timestamp: notif.timestamp ? new Date(notif.timestamp) : new Date(),
                read: notif.read || false,
              },
            });
          }
        }
      }
    } catch (e) {
      console.error("[MIGRATION_ERROR] securityNotifications migration failed:", e);
    }
  }

  // Clear legacy fields to complete migration
  if (
    (user.activeSessions && user.activeSessions !== "[]") ||
    (user.loginHistory && user.loginHistory !== "[]") ||
    (user.securityNotifications && user.securityNotifications !== "[]")
  ) {
    try {
      await prisma.users.update({
        where: { id: user.id },
        data: {
          activeSessions: "[]",
          loginHistory: "[]",
          securityNotifications: "[]",
        },
      });
    } catch (e) {
      console.error("[MIGRATION_ERROR] Clearing legacy fields failed:", e);
    }
  }
}

export async function mapUserToRecord(u: any): Promise<UserRecord> {
  // Live migration if legacy data is present
  if (
    (u.activeSessions && u.activeSessions !== "[]") ||
    (u.loginHistory && u.loginHistory !== "[]") ||
    (u.securityNotifications && u.securityNotifications !== "[]")
  ) {
    await migrateLegacyUserDataIfNeeded(u);
  }

  const sessions = await prisma.userSession.findMany({
    where: { userId: u.id },
    orderBy: { lastActive: "desc" },
  });

  const loginEvents = await prisma.loginEvent.findMany({
    where: { userId: u.id },
    orderBy: { timestamp: "desc" },
    take: 50,
  });

  const notifications = await prisma.securityNotification.findMany({
    where: { userId: u.id },
    orderBy: { timestamp: "desc" },
    take: 20,
  });

  return {
    id: u.id,
    name: u.name,
    email: u.email,
    passwordHash: u.passwordHash,
    role: u.role as any,
    tier: u.tier as any,
    university: u.university,
    createdAt: u.createdAt.toISOString(),
    emailVerified: u.emailVerified,
    emailVerificationCode: u.emailVerificationCode || undefined,
    emailVerificationExpires: u.emailVerificationExpires?.toISOString() || undefined,
    passwordResetToken: u.passwordResetToken || undefined,
    passwordResetExpires: u.passwordResetExpires?.toISOString() || undefined,
    failedLoginAttempts: u.failedLoginAttempts,
    lockUntil: u.lockUntil?.toISOString() || undefined,
    mfaEnabled: u.mfaEnabled,
    mfaCode: u.mfaCode || undefined,
    mfaExpires: u.mfaExpires?.toISOString() || undefined,
    mfaToken: u.mfaToken || undefined,
    activeSessions: sessions.map(s => ({
      sessionId: s.id,
      device: s.device,
      ip: s.ip,
      userAgent: s.userAgent,
      createdAt: s.createdAt.toISOString(),
      lastActive: s.lastActive.toISOString(),
    })),
    loginHistory: loginEvents.map(e => ({
      id: e.id,
      timestamp: e.timestamp.toISOString(),
      ip: e.ip,
      userAgent: e.userAgent,
      status: e.status as any,
      location: e.location || undefined,
    })),
    securityNotifications: notifications.map(n => ({
      id: n.id,
      title: n.title,
      message: n.message,
      timestamp: n.timestamp.toISOString(),
      read: n.read,
    })),
  };
}

export const userRepository = {
  async getUsers(limit = 100, offset = 0): Promise<UserRecord[]> {
    const take = Math.min(limit, HARD_MAX_PAGE_SIZE);
    const list = await prisma.users.findMany({
      orderBy: { createdAt: "desc" },
      take,
      skip: offset,
    });

    if (list.length === 0) return [];

    const userIds = list.map(u => u.id);

    const [allSessions, allLoginEvents, allNotifications] = await Promise.all([
      prisma.userSession.findMany({
        where: { userId: { in: userIds } },
        orderBy: { lastActive: "desc" },
      }),
      prisma.loginEvent.findMany({
        where: { userId: { in: userIds } },
        orderBy: { timestamp: "desc" },
      }),
      prisma.securityNotification.findMany({
        where: { userId: { in: userIds } },
        orderBy: { timestamp: "desc" },
      }),
    ]);

    const sessionsByUserId = new Map<string, typeof allSessions>();
    for (const s of allSessions) {
      const arr = sessionsByUserId.get(s.userId) || [];
      arr.push(s);
      sessionsByUserId.set(s.userId, arr);
    }

    const loginEventsByUserId = new Map<string, typeof allLoginEvents>();
    for (const e of allLoginEvents) {
      const arr = loginEventsByUserId.get(e.userId) || [];
      if (arr.length < 50) arr.push(e);
      loginEventsByUserId.set(e.userId, arr);
    }

    const notifsByUserId = new Map<string, typeof allNotifications>();
    for (const n of allNotifications) {
      const arr = notifsByUserId.get(n.userId) || [];
      if (arr.length < 20) arr.push(n);
      notifsByUserId.set(n.userId, arr);
    }

    return list.map(u => {
      const sessions = sessionsByUserId.get(u.id) || [];
      const loginEvents = loginEventsByUserId.get(u.id) || [];
      const notifications = notifsByUserId.get(u.id) || [];

      return {
        id: u.id,
        name: u.name,
        email: u.email,
        passwordHash: u.passwordHash,
        role: u.role as any,
        tier: u.tier as any,
        university: u.university,
        createdAt: u.createdAt.toISOString(),
        emailVerified: u.emailVerified,
        emailVerificationCode: u.emailVerificationCode || undefined,
        emailVerificationExpires: u.emailVerificationExpires?.toISOString() || undefined,
        passwordResetToken: u.passwordResetToken || undefined,
        passwordResetExpires: u.passwordResetExpires?.toISOString() || undefined,
        failedLoginAttempts: u.failedLoginAttempts,
        lockUntil: u.lockUntil?.toISOString() || undefined,
        mfaEnabled: u.mfaEnabled,
        mfaCode: u.mfaCode || undefined,
        mfaExpires: u.mfaExpires?.toISOString() || undefined,
        mfaToken: u.mfaToken || undefined,
        activeSessions: sessions.map(s => ({
          sessionId: s.id,
          device: s.device,
          ip: s.ip,
          userAgent: s.userAgent,
          createdAt: s.createdAt.toISOString(),
          lastActive: s.lastActive.toISOString(),
        })),
        loginHistory: loginEvents.map(e => ({
          id: e.id,
          timestamp: e.timestamp.toISOString(),
          ip: e.ip,
          userAgent: e.userAgent,
          status: e.status as any,
          location: e.location || undefined,
        })),
        securityNotifications: notifications.map(n => ({
          id: n.id,
          title: n.title,
          message: n.message,
          timestamp: n.timestamp.toISOString(),
          read: n.read,
        })),
      };
    });
  },

  async getUserByEmail(email: string): Promise<UserRecord | null> {
    const u = await prisma.users.findUnique({
      where: { email: email.toLowerCase().trim() },
    });
    return u ? mapUserToRecord(u) : null;
  },

  async getUserById(id: string): Promise<UserRecord | null> {
    const u = await prisma.users.findUnique({ where: { id } });
    return u ? mapUserToRecord(u) : null;
  },

  async addUser(user: Omit<UserRecord, "id" | "createdAt">): Promise<UserRecord> {
    const id = "usr-" + Date.now() + "-" + Math.floor(Math.random() * 1000);
    const created = await prisma.users.create({
      data: {
        id,
        name: user.name,
        email: user.email.toLowerCase().trim(),
        passwordHash: user.passwordHash,
        role: user.role,
        tier: user.tier || "Free",
        university: user.university || "Universitas Indonesia",
        emailVerified: user.emailVerified ?? false,
        mfaEnabled: user.mfaEnabled ?? false,
      },
    });

    await auditRepository.logAudit(
      "USER_REGISTERED",
      `Pengguna baru terdaftar: ${user.name} (${user.email}) dengan peran ${user.role}`,
      id,
    );
    return mapUserToRecord(created);
  },

  async updateUserTier(id: string, tier: "Free" | "Pro" | "Developer"): Promise<UserRecord | null> {
    const updated = await prisma.users.update({
      where: { id },
      data: { tier },
    });
    await auditRepository.logAudit(
      "UPGRADE_TIER",
      `Pengguna ID ${id} meningkatkan tier menjadi ${tier}`,
    );
    return mapUserToRecord(updated);
  },

  async updateUserProfileDetails(
    userId: string,
    updates: { name?: string; university?: string; email?: string },
  ): Promise<UserRecord | null> {
    const current = await prisma.users.findUnique({ where: { id: userId } });
    if (!current) return null;

    const updated = await prisma.users.update({
      where: { id: userId },
      data: {
        name: updates.name,
        university: updates.university,
        email: updates.email,
      },
    });

    await auditRepository.logAudit(
      "KOREKSI_DATA_PRIBADI",
      `Koreksi data pribadi diperbarui untuk user ID ${userId}`,
      userId,
    );
    return mapUserToRecord(updated);
  },

  async getUserCount(): Promise<number> {
    return await prisma.users.count();
  },
};

import { Router, Request, Response } from 'express';
import { z } from 'zod';
import { serverDb, prisma } from '../database';
import { requireAuth } from '../middleware/auth';
import { sanitizeInput } from '../security';
import { validatePagination, idempotencyMiddleware } from '../apiV1Helpers';
import { EventEmitter } from 'events';
import {
  CreateAppointmentSchema as createAppointmentSchema,
  UpdateAppointmentSchema as updateAppointmentSchema,
  RescheduleAppointmentSchema as rescheduleAppointmentSchema
} from '../../shared/contracts/appointments.js';

export { createAppointmentSchema, updateAppointmentSchema, rescheduleAppointmentSchema };

const router = Router();

// EventEmitter for real-time appointment updates
export const appointmentEvents = new EventEmitter();

// --- SSE Endpoint for Real-time Status Transitions ---
router.get('/stream', requireAuth, (req: Request, res: Response) => {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.flushHeaders(); // flush the headers to establish SSE

  // Function to send event
  const sendEvent = (data: any) => {
    // Only send if the update belongs to the user or if user is admin, etc.
    // Basic filter: Check if user is involved (as counselor or student)
    const isStudentMatch = req.user?.role === 'mahasiswa' && data.userId === req.user.userId;
    const isCounselorMatch = req.user?.role === 'konselor' && data.counselorUserId === req.user.userId; 
    const isAdmin = req.user?.role === 'admin';

    if (isStudentMatch || isCounselorMatch || isAdmin) {
      res.write(`data: ${JSON.stringify(data)}\n\n`);
    }
  };

  appointmentEvents.on('update', sendEvent);

  req.on('close', () => {
    appointmentEvents.off('update', sendEvent);
  });
});

export interface AppointmentResponseDTO {
  id: string;
  counselorId: string;
  counselorName: string;
  date: string;
  time: string;
  timezone: 'WIB' | 'WITA' | 'WIT';
  notes?: string;
  status: 'PENDING' | 'CONFIRMED' | 'CANCELLED' | 'Selesai';
  approvalStatus: 'PENDING_APPROVAL' | 'APPROVED' | 'REJECTED';
  attendanceStatus: 'SCHEDULED' | 'ATTENDED' | 'NO_SHOW' | 'CANCELLED' | 'RESCHEDULED';
  meetingLink?: string;
  mode: 'video_call' | 'in_person';
  createdAt: string;
  userId: string;
  studentName: string;
  studentNIM?: string;
  studentEmail?: string;
}

export function mapAppointmentToResponse(appt: any): AppointmentResponseDTO {
  return {
    id: appt.id,
    counselorId: appt.counselorId,
    counselorName: appt.counselorName,
    date: appt.date,
    time: appt.time,
    timezone: appt.timezone || 'WIB',
    notes: appt.notes || '',
    status: appt.status,
    approvalStatus: appt.approvalStatus,
    attendanceStatus: appt.attendanceStatus,
    meetingLink: appt.meetingLink || '',
    mode: appt.mode || 'video_call',
    createdAt: appt.createdAt,
    userId: appt.userId || '',
    studentName: appt.studentName || '',
    studentNIM: appt.studentNIM || '',
    studentEmail: appt.studentEmail || '',
  };
}

const AvailabilityQuerySchema = z.object({
  counselorId: z.string({
    required_error: 'counselorId wajib diisi'
  }).min(1, 'counselorId tidak boleh kosong'),
  date: z.string({
    required_error: 'date wajib diisi'
  }).regex(/^\d{4}-\d{2}-\d{2}$/, 'Format tanggal harus YYYY-MM-DD')
});

// Availability Check
router.get(['/availability', '/appointments/availability'], async (req: Request, res: Response) => {
  try {
    const parsed = AvailabilityQuerySchema.safeParse(req.query);
    if (!parsed.success) {
      return res.status(400).json({
        success: false,
        code: 'VALIDATION_ERROR',
        error: 'Parameter tidak valid.',
        details: parsed.error.issues.map(e => ({ path: e.path.join('.'), message: e.message }))
      });
    }

    const { counselorId, date } = parsed.data;
    const availability = await serverDb.getAppointmentAvailability(counselorId, date);
    res.json(availability);
  } catch (err: unknown) {
    console.error('Error checking availability:', err);
    res.status(500).json({ success: false, code: 'INTERNAL_SERVER_ERROR', error: 'Gagal memeriksa ketersediaan slot.' });
  }
});

// List Appointments
router.get(['/', '/db/appointments'], requireAuth, async (req: Request, res: Response) => {
  try {
    await serverDb.logAudit(
      'READ_APPOINTMENTS',
      `User ${req.user!.name} (${req.user!.email}) dengan role ${req.user!.role} membaca daftar janji temu.`,
      req.user!.role
    );

    const { page, limit, offset } = validatePagination(req, 20);

    const andConditions: any[] = [];

    // Role-based data isolation with canonical mapping
    if (req.user!.role === 'mahasiswa') {
      andConditions.push({ userId: req.user!.userId });
    } else if (req.user!.role === 'konselor') {
      const counselor = await prisma.counselors.findFirst({
        where: { userId: req.user!.userId }
      });
      if (!counselor) {
        return res.status(403).json({
          error: 'ACCESS_DENIED',
          message: 'Profil konselor tidak terdaftar atau belum terhubung dengan akun ini.'
        });
      }

      const requestedCounselorId = req.query.counselorId as string;
      if (requestedCounselorId && requestedCounselorId !== counselor.id) {
        return res.status(403).json({
          error: 'ACCESS_DENIED',
          message: 'Konselor tidak memiliki izin untuk mengakses data janji temu konselor lain.'
        });
      }

      andConditions.push({ counselorId: counselor.id });
    } else if (req.user!.role === 'admin') {
      const counselorFilter = req.query.counselorId as string;
      if (counselorFilter && counselorFilter !== 'Semua') {
        andConditions.push({ counselorId: counselorFilter });
      }
      const userFilter = req.query.userId as string;
      if (userFilter) {
        andConditions.push({ userId: userFilter });
      }
    }

    // Filter by status (strictly scoped inside AND)
    const statusFilter = req.query.status as string;
    if (statusFilter && statusFilter !== 'Semua') {
      andConditions.push({
        OR: [
          { status: statusFilter },
          { approvalStatus: statusFilter }
        ]
      });
    }

    // Filter by approvalStatus if explicitly specified
    const approvalStatusFilter = req.query.approvalStatus as string;
    if (approvalStatusFilter && approvalStatusFilter !== 'Semua') {
      andConditions.push({ approvalStatus: approvalStatusFilter });
    }

    // Filter by date
    const dateFilter = req.query.date as string;
    if (dateFilter) {
      andConditions.push({ date: dateFilter });
    }

    // Search query
    const searchQuery = (req.query.search as string || '').toLowerCase().trim();
    if (searchQuery) {
      andConditions.push({
        OR: [
          { studentName: { contains: searchQuery } },
          { studentNIM: { contains: searchQuery } },
          { counselorName: { contains: searchQuery } }
        ]
      });
    }

    const where = andConditions.length > 0 ? { AND: andConditions } : {};

    const total = await prisma.appointments.count({ where });

    const appointmentsData = await prisma.appointments.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      take: limit,
      skip: offset
    });

    res.setHeader('X-Total-Count', total);
    res.setHeader('X-Page', page);
    res.setHeader('X-Limit', limit.toString());
    res.setHeader('X-Total-Pages', Math.ceil(total / Math.max(limit, 1)));

    const responseData = appointmentsData.map(mapAppointmentToResponse);

    if (req.query.format === 'object') {
      return res.json({
        data: responseData,
        total,
        page,
        limit,
        totalPages: Math.ceil(total / Math.max(limit, 1)),
        requestId: (req as any).requestId
      });
    }
    res.json(responseData);
  } catch (err: unknown) {
    console.error('Error fetching appointments:', err);
    res.status(500).json({ error: 'Gagal mengambil data jadwal dari database.' });
  }
});

// Create Appointment
router.post(['/', '/db/appointments'], requireAuth, idempotencyMiddleware, async (req: Request, res: Response) => {
  try {
    const parsed = createAppointmentSchema.safeParse(req.body);
    if (!parsed.success) {
      return res.status(400).json({
        error: 'Validasi gagal.',
        details: parsed.error.issues.map(e => ({ path: e.path.join('.'), message: e.message }))
      });
    }

    const validated = parsed.data;
    const isMahasiswa = req.user!.role === 'mahasiswa';
    const finalUserId = isMahasiswa ? req.user!.userId : (validated.userId || req.user!.userId);
    const finalStudentName = isMahasiswa ? req.user!.name : (validated.studentName || 'Mahasiswa');
    const finalStudentEmail = isMahasiswa ? req.user!.email : (validated.studentEmail || '');
    const finalStudentNIM = isMahasiswa ? (req.body.studentNIM || '') : (validated.studentNIM || '');

    const record = await serverDb.addAppointment({
      counselorId: validated.counselorId,
      counselorName: validated.counselorName,
      date: validated.date,
      time: validated.time,
      timezone: validated.timezone || 'WIB',
      mode: validated.mode || 'video_call',
      notes: sanitizeInput(validated.notes || '', 300),
      status: 'PENDING',
      approvalStatus: 'PENDING_APPROVAL',
      attendanceStatus: 'SCHEDULED',
      meetingLink: validated.meetingLink || '',
      userId: finalUserId,
      studentName: sanitizeInput(finalStudentName, 100),
      studentNIM: sanitizeInput(finalStudentNIM, 30),
      studentEmail: sanitizeInput(finalStudentEmail, 100)
    });

    res.json({ success: true, record: mapAppointmentToResponse(record) });
  } catch (err: unknown) {
    if (err.message === 'SLOT_ALREADY_BOOKED') {
      return res.status(409).json({
        error: 'Jadwal bentrok! Slot pada tanggal dan jam tersebut sudah dipesan oleh mahasiswa lain. Silakan pilih waktu yang berbeda.'
      });
    }
    console.error('Error creating appointment:', err);
    res.status(500).json({ error: 'Gagal menyimpan jadwal ke database.' });
  }
});

// Update Appointment
router.put(['/:id', '/db/appointments/:id'], requireAuth, async (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const appt = await serverDb.findAppointmentById(id);
    if (!appt) {
      return res.status(404).json({ error: 'Jadwal tidak ditemukan.' });
    }

    if (req.user!.role === 'mahasiswa') {
      if (appt.userId !== req.user!.userId) {
        return res.status(403).json({
          error: 'ACCESS_DENIED',
          message: 'Akses ditolak. Anda hanya diperbolehkan mengubah jadwal milik Anda sendiri.'
        });
      }
    } else if (req.user!.role === 'konselor') {
      const counselor = await prisma.counselors.findFirst({
        where: { userId: req.user!.userId }
      });
      if (!counselor || appt.counselorId !== counselor.id) {
        return res.status(403).json({
          error: 'ACCESS_DENIED',
          message: 'Akses ditolak. Konselor hanya diizinkan mengelola janji temu yang ditugaskan kepada dirinya.'
        });
      }
    }

    const parsed = updateAppointmentSchema.safeParse(req.body);
    if (!parsed.success) {
      return res.status(400).json({
        error: 'Validasi gagal.',
        details: parsed.error.issues.map(e => ({ path: e.path.join('.'), message: e.message }))
      });
    }

    const validated = parsed.data;
    const updates: any = {};

    // FIELD-LEVEL AUTHORIZATION ENFORCEMENT
    if (req.user!.role === 'mahasiswa') {
      // Mahasiswa can cancel or update notes/mode while still pending
      if (validated.status !== undefined) {
        const s = validated.status.toUpperCase();
        if (s === 'CANCELLED') {
          updates.status = 'CANCELLED';
          updates.attendanceStatus = 'CANCELLED';
        }
      }
      if (appt.status === 'PENDING') {
        if (validated.notes !== undefined) updates.notes = sanitizeInput(validated.notes, 300);
        if (validated.mode !== undefined) updates.mode = validated.mode;
      }
    } else if (req.user!.role === 'konselor') {
      // Counselor can update status, approvalStatus, attendanceStatus, meetingLink, notes
      // REASSIGNMENT (counselorId/counselorName), changing student details, or rescheduling date/time is FORBIDDEN for counselor
      if (validated.status !== undefined) {
        updates.status = validated.status;
        if (validated.status === 'CONFIRMED') {
          updates.approvalStatus = 'APPROVED';
        } else if (validated.status === 'REJECTED') {
          updates.approvalStatus = 'REJECTED';
        } else if (validated.status === 'CANCELLED') {
          updates.attendanceStatus = 'CANCELLED';
        }
      }
      if (validated.approvalStatus !== undefined) updates.approvalStatus = validated.approvalStatus;
      if (validated.attendanceStatus !== undefined) updates.attendanceStatus = validated.attendanceStatus;
      if (validated.meetingLink !== undefined) updates.meetingLink = validated.meetingLink;
      if (validated.notes !== undefined) updates.notes = sanitizeInput(validated.notes, 300);
      if (validated.mode !== undefined) updates.mode = validated.mode;
    } else if (req.user!.role === 'admin') {
      // Admin has unrestricted update authority including reassignment and rescheduling
      if (validated.counselorId !== undefined) updates.counselorId = validated.counselorId;
      if (validated.counselorName !== undefined) updates.counselorName = validated.counselorName;
      if (validated.date !== undefined) updates.date = validated.date;
      if (validated.time !== undefined) updates.time = validated.time;
      if (validated.timezone !== undefined) updates.timezone = validated.timezone;
      if (validated.mode !== undefined) updates.mode = validated.mode;
      if (validated.notes !== undefined) updates.notes = sanitizeInput(validated.notes, 300);
      if (validated.status !== undefined) {
        updates.status = validated.status;
        if (validated.status === 'CONFIRMED') {
          updates.approvalStatus = 'APPROVED';
        } else if (validated.status === 'REJECTED') {
          updates.approvalStatus = 'REJECTED';
        } else if (validated.status === 'CANCELLED') {
          updates.attendanceStatus = 'CANCELLED';
        }
      }
      if (validated.approvalStatus !== undefined) updates.approvalStatus = validated.approvalStatus;
      if (validated.attendanceStatus !== undefined) updates.attendanceStatus = validated.attendanceStatus;
      if (validated.meetingLink !== undefined) updates.meetingLink = validated.meetingLink;
      if (validated.studentName !== undefined) updates.studentName = sanitizeInput(validated.studentName, 100);
      if (validated.studentNIM !== undefined) updates.studentNIM = sanitizeInput(validated.studentNIM, 30);
      if (validated.studentEmail !== undefined) updates.studentEmail = sanitizeInput(validated.studentEmail, 100);
    }

    const record = await serverDb.updateAppointment(id, updates);
    if (!record) {
      return res.status(404).json({ error: 'Jadwal gagal diperbarui.' });
    }

    // Emit event for SSE
    // Need to get counselor user ID to filter SSE properly
    let counselorUserId = '';
    const counselorProfile = await prisma.counselors.findUnique({ where: { id: record.counselorId } });
    if (counselorProfile && counselorProfile.userId) {
      counselorUserId = counselorProfile.userId;
    }
    appointmentEvents.emit('update', { ...mapAppointmentToResponse(record), counselorUserId });

    res.json({ success: true, record: mapAppointmentToResponse(record) });
  } catch (err: unknown) {
    if (err.message === 'SLOT_ALREADY_BOOKED') {
      return res.status(409).json({
        error: 'Jadwal bentrok! Slot pada tanggal dan jam tersebut sudah terisi oleh jadwal lain.'
      });
    }
    console.error('Error updating appointment:', err);
    res.status(500).json({ error: 'Gagal memperbarui jadwal.' });
  }
});

