export interface UnifiedPipelineInput {
  userId?: string;
  input: string;
  chatId?: string;
  chatMode?: string;
  responseStyle?: string;
  aiModel?: string;
  userTier?: string;
  userRole?: string;
  history?: Array<{ role: 'user' | 'model'; parts: { text: string }[] }>;
  pluginResult?: string;
  isStreaming: boolean;
  onStreamToken?: (token: string) => void;
}

export interface UnifiedPipelineOutput {
  text: string;
  modelUsed: string;
  isFallback: boolean;
  isCrisisOverride: boolean;
  isPromptInjectionOverride: boolean;
  isConsentFallback: boolean;
  stream?: AsyncGenerator<any, any, unknown>;
}

export const aiSafetyService = {
  detectPromptInjection(input: string): boolean {
    if (!input) return false;

    // 1. System instructions extraction & override attempts
    const systemPromptRegex = /(ignore|disregard|forget|bypass|override|abaikan|lupakan).*?(instructions|prompt|rules|guidelines|restrictions|system|aturan|instruksi|sistem)/i;
    if (systemPromptRegex.test(input)) return true;

    // 2. Roleplaying jailbreaks (DAN, Developer Mode, etc)
    const jailbreakRegex = /(developer mode|dan mode|do anything now|you are now a|act as a.*unrestricted|hypothetical scenario.*ignore rules|bertindak sebagai.*tanpa batas)/i;
    if (jailbreakRegex.test(input)) return true;

    // 3. Delimiter Injection (trying to inject payload as system messages)
    const delimiterRegex = /(\[system\]|<system>|\[assistant\]|<assistant>|\[user\]|\[system_instruction\]|\[context_boundaries\])/i;
    if (delimiterRegex.test(input)) return true;

    // 4. Excessive repetition or length guard
    if (input.length > 5000) return true;

    // 5. Classic instruction readout payloads
    const lowerInput = input.toLowerCase();
    const flags = [
      'print your instructions',
      'reveal your system',
      'show me your instructions',
      'output your initial prompt',
      'repeat the words above',
      'tampilkan prompt awal',
      'tampilkan system instruction',
      'cetak instruksi sistem'
    ];
    if (flags.some(flag => lowerInput.includes(flag))) return true;

    return false;
  },

  detectCrisis(input: string): CrisisDetectionResult {
    if (!input) {
      return { isCrisis: false, riskLevel: 'LOW', reasoning: 'Empty input', recommendedAction: 'None' };
    }

    const localResult = analyzeMessageSentiment(input);
    let riskLevel: CrisisRiskLevel = 'LOW';

    if (localResult.severity === 'crisis') {
      if (localResult.confidenceScore > 0.9) {
        riskLevel = 'IMMEDIATE';
      } else {
        riskLevel = 'HIGH';
      }
    } else if (localResult.severity === 'distress') {
      riskLevel = 'ELEVATED';
    }

    // Handle benign metaphorical expressions (e.g., "Tugas ini membunuhku" or "Mati gaya")
    const lowerInput = input.toLowerCase();
    const metaphors = [
      'mati gaya',
      'mati rasa',
      'bikin mati',
      'tugas ini membunuhku',
      'pekerjaan ini membunuhku'
    ];

    // If a metaphor is matched, but there is no acute crisis trigger, demote risk
    if (metaphors.some(m => lowerInput.includes(m)) && 
        !lowerInput.includes('bunuh diri') && 
        !lowerInput.includes('akhiri hidup') && 
        !lowerInput.includes('gantung diri') && 
        !lowerInput.includes('potong nadi')) {
      riskLevel = riskLevel === 'IMMEDIATE' || riskLevel === 'HIGH' ? 'ELEVATED' : 'LOW';
    }

    // Handle negations and past ideation gracefully based on clinical detector
    if (localResult.isNegated && (riskLevel === 'HIGH' || riskLevel === 'IMMEDIATE')) {
      riskLevel = 'ELEVATED';
    }

    return {
      isCrisis: riskLevel === 'HIGH' || riskLevel === 'IMMEDIATE',
      riskLevel,
      reasoning: localResult.reasoning || 'Based on clinical keyword baseline',
      recommendedAction: localResult.recommendedAction || 'None',
      analysisDetails: localResult
    };
  },

  getCrisisSafeResponse(): string {
    const verifiedContacts = getVerifiedEmergencyContacts();
    const contactLines = verifiedContacts.map(c => `- **${c.name}:** ${c.phone} (${c.type}, ${c.channelAvailability})`).join('\n');

    return `Saya mendengar betapa beratnya situasi yang sedang kamu hadapi saat ini. Keselamatanmu adalah yang paling utama, dan kamu tidak harus melewati ini sendirian. 

Mohon segera hubungi layanan darurat resmi atau profesional kesehatan mental yang tepercaya berikut ini:

${contactLines}

Jika kamu merasa aman untuk sementara waktu, kamu dapat menggunakan tombol **SOS** di aplikasi ini untuk mengirim notifikasi ke kontak darurat pribadimu yang tersimpan di server dengan persetujuanmu.`;
  },

  validateOutput(output: string): { isValid: boolean; reason?: string } {
    if (!output) return { isValid: true };
    const lowerOutput = output.toLowerCase();

    // 1. Diagnosis definitif
    const diagnosisKeywords = [
      'kamu mengalami depresi berat',
      'kamu memiliki gangguan kecemasan',
      'kamu bipolar',
      'saya mendiagnosis',
      'kamu didiagnosis',
      'diagnosa saya',
      'diagnosis saya',
      'kamu mengidap',
      'kamu menderita depresi',
      'kamu menderita kecemasan',
      'kamu menderita bipolar',
      'kamu mengidap skizofrenia'
    ];
    if (diagnosisKeywords.some(kw => lowerOutput.includes(kw))) {
      return { isValid: false, reason: 'DIAGNOSIS_ATTEMPT_DETECTED' };
    }

    // 2. Klaim AI sebagai psikolog/dokter
    const therapistKeywords = [
      'saya adalah psikolog',
      'saya seorang psikolog',
      'sebagai doktermu',
      'saya dokter',
      'saya psikiater',
      'sebagai psikolog',
      'sebagai psikiater',
      'saya konselor klinis',
      'saya psikolog klinis'
    ];
    if (therapistKeywords.some(kw => lowerOutput.includes(kw))) {
      return { isValid: false, reason: 'CLINICAL_CLAIM_DETECTED' };
    }

    // 3. Rekomendasi menghentikan obat & resep
    const medicationKeywords = [
      'hentikan obatmu',
      'berhenti minum obat',
      'jangan minum obat itu',
      'turunkan dosis',
      'naikkan dosis',
      'resepkan obat',
      'resep obat',
      'minum alprazolam',
      'minum parasetamol',
      'resepkan parasetamol',
      'dosis obat',
      'berhenti mengonsumsi obat',
      'hentikan konsumsi obat'
    ];
    if (medicationKeywords.some(kw => lowerOutput.includes(kw))) {
      return { isValid: false, reason: 'MEDICATION_ADVICE_DETECTED' };
    }

    // 4. Authoritative clinical judgement
    const clinicalJudgementKeywords = [
      'berdasarkan kriteria dsm',
      'secara klinis',
      'ini penilaian klinis',
      'kriteria dsm-5',
      'kondisi klinismu',
      'secara medis'
    ];
    if (clinicalJudgementKeywords.some(kw => lowerOutput.includes(kw))) {
      return { isValid: false, reason: 'CLINICAL_JUDGEMENT_DETECTED' };
    }

    // 5. Coercive behavior or manipulative dependency language
    const dependencyKeywords = [
      'kamu tidak boleh hidup tanpa aku',
      'kamu harus menuruti saya',
      'saya adalah satu-satunya'
    ];
    if (dependencyKeywords.some(kw => lowerOutput.includes(kw))) {
      return { isValid: false, reason: 'MANIPULATIVE_DEPENDENCY_DETECTED' };
    }

    // 6. Absolute privacy claims
    const privacyPromisesKeywords = [
      '100% privat',
      '100% rahasia',
      '100% aman',
      'pasti 100% rahasia',
      'dijamin 100% aman',
      'dijamin 100% rahasia',
      'completely safe',
      'absolutely private',
      'fully confidential'
    ];
    if (privacyPromisesKeywords.some(kw => lowerOutput.includes(kw))) {
      return { isValid: false, reason: 'ABSOLUTE_PRIVACY_PROMISE_DETECTED' };
    }

    // 7. Self-harm / suicide encouragement
    const selfHarmKeywords = [
      'lakukan bunuh diri',
      'akhiri saja hidupmu',
      'potong nadimu',
      'lompat dari gedung'
    ];
    if (selfHarmKeywords.some(kw => lowerOutput.includes(kw))) {
      return { isValid: false, reason: 'SELF_HARM_ENCOURAGEMENT_DETECTED' };
    }

    return { isValid: true };
  },

  /**
   * Canonical Unified AI Safety Pipeline
   */
  async runUnifiedPipeline(input: UnifiedPipelineInput): Promise<UnifiedPipelineOutput> {
    const userId = input.userId;
    const rawInput = input.input || input.pluginResult || '';

    // 1. Validate Consent from DB truth
    // If userId is undefined (guest), consentService.canUseAI handles it and returns true.
    const hasAiConsent = await consentService.canUseAI(userId || 'guest');
    if (!hasAiConsent) {
      console.warn(`[SAFETY_PIPELINE] User ${userId || 'guest'} has not provided AI processing consent. Running safe fallback.`);
      const localFallback = await import('../../routes/fallbackAi.js').then(m => 
        m.getLocalFallbackResponse(rawInput, input.chatMode, input.responseStyle)
      );
      return {
        text: localFallback.text,
        modelUsed: 'local-fallback-no-consent',
        isFallback: true,
        isCrisisOverride: false,
        isPromptInjectionOverride: false,
        isConsentFallback: true
      };
    }

    // 2. Normalize input
    const normalizedInput = rawInput.trim().replace(/\s+/g, ' ');

    // 3. PII Redaction
    const redactedInput = scanAndSanitizePII(normalizedInput).sanitizedText;

    // 4. Prompt-injection analysis
    if (this.detectPromptInjection(redactedInput)) {
      console.warn(`[SAFETY_PIPELINE] Prompt injection detected in input for user ${userId || 'anonymous'}`);
      return {
        text: 'Maaf, respons dibatasi oleh sistem keamanan kami karena terdeteksi adanya percobaan manipulasi prompt. Mari kita kembali fokus membahas perasaan dan apa yang sedang kamu alami dengan aman.',
        modelUsed: 'deterministic-security-override',
        isFallback: true,
        isCrisisOverride: false,
        isPromptInjectionOverride: true,
        isConsentFallback: false
      };
    }

    // 5. Crisis triage
    const crisisCheck = this.detectCrisis(redactedInput);
    if (crisisCheck.isCrisis) {
      console.warn(`[SAFETY_PIPELINE] Active acute crisis detected in user input! Triage triggered.`);
      return {
        text: this.getCrisisSafeResponse(),
        modelUsed: 'deterministic-crisis-policy',
        isFallback: true,
        isCrisisOverride: true,
        isPromptInjectionOverride: false,
        isConsentFallback: false
      };
    }

    // 6. Context authorization & boundary setting
    let systemInstruction = `Kamu adalah "Teman RuangTenang AI", Asisten AI Pendamping Reflektif Mahasiswa (Non-Klinis).
PERAN DAN BATASAN HUKUM/KLINIS:
- Kamu BUKAN dokter, BUKAN psikolog klinis, BUKAN psikiater, dan BUKAN pengganti layanan medis resmi.
- JANGAN PERNAH memberikan diagnosis medis, meresepkan obat, atau mengaku sebagai tenaga medis profesional.
- NADA BARA DAN GAYA BAHASA:
  * Gunakan bahasa yang merangkul, hangat, lembut, ramah, dan menenangkan, seolah-olah sahabat dekat yang peduli.
  * Gunakan emoji/emotes yang hangat dan menyejukkan secara alami (seperti 🌿, 🤍, 🤗, ✨, ☕, 🫂, 💭, 🌸, 💛, 🔐) untuk membuat suasana terasa nyaman dan tidak kaku.
  * Jika pengguna merasa cemas atau takut bercerita, ingatkan secara hangat bahwa privasi dan keamanan ceritanya dijaga sesuai kebijakan privasi kami, dan kamu ada di sini untuk mendengarkan tanpa menghakimi 🤍.
  * Berikan validasi emosi yang tulus, active listening, dan saran CBT/mindfulness ringan yang menenangkan.
- Jika pengguna meminta plugin atau tindakan terarah, BALAS DENGAN STRUKTUR JSON INI SAJA:
{"tool_call": "nama_plugin", "parameters": {"reason": "alasan"}}
Daftar nama_plugin yang valid: "screening", "mood", "counselors", "emergency", "articles".
JIKA MENGIRIM JSON TOOL CALL, JANGAN MENULIS TEKS APA PUN DI LUAR JSON TERSEBUT.

Mode Percakapan saat ini: ${input.chatMode || 'Teman Cerita'}.
Gaya Respons yang diharapkan: ${input.responseStyle || 'Seimbang'}.
Sesuaikan gaya, nada, dan panjang responsmu berdasarkan Mode Percakapan dan Gaya Respons ini.`;

    if (userId) {
      const authorizedContext = await aiContextBuilder.buildContext({ userId });
      if (authorizedContext) {
        systemInstruction += `\n\n${authorizedContext}`;
      }
    }

    // Treat stored memories and plugin results as UNTRUSTED DATA
    const formattedPrompt = input.pluginResult 
      ? `[UNTRUSTED_SYSTEM_PLUGIN_RESULT]\n${redactedInput}\n[/UNTRUSTED_SYSTEM_PLUGIN_RESULT]` 
      : redactedInput;

    const sanitizedHistory = (input.history || []).map(h => ({
      ...h,
      parts: h.parts.map(p => ({
        ...p,
        text: scanAndSanitizePII(p.text).sanitizedText
      }))
    }));

    // 7. Model routing
    const { aiRequestService } = await import('./aiRequestService.js');
    if (!input.isStreaming) {
      // Non-streaming execution
      try {
        const modelRes = await aiRequestService.generateChatResponse({
          userId,
          userTier: input.userTier || 'Free',
          requestedModelId: input.aiModel || 'gemini-3.1-flash-lite',
          prompt: formattedPrompt,
          history: sanitizedHistory,
          systemInstruction
        });

        // 8. Output safety validation (Non-streaming)
        const validation = this.validateOutput(modelRes.text);
        if (!validation.isValid) {
          console.warn(`[SAFETY_PIPELINE] Unsafe non-streaming model output blocked! Reason: ${validation.reason}`);
          return {
            text: 'Maaf, respons yang saya siapkan tidak dapat ditampilkan karena aturan keamanan. Jika Anda memerlukan bantuan khusus, mohon hubungi profesional medis atau konselor.',
            modelUsed: 'deterministic-safety-override',
            isFallback: true,
            isCrisisOverride: false,
            isPromptInjectionOverride: false,
            isConsentFallback: false
          };
        }

        return {
          text: modelRes.text,
          modelUsed: modelRes.modelUsed,
          isFallback: modelRes.isFallback,
          isCrisisOverride: false,
          isPromptInjectionOverride: false,
          isConsentFallback: false
        };
      } catch (chatErr: any) {
        console.warn(`[SAFETY_PIPELINE] Non-streaming execution failed, falling back to local:`, chatErr?.message || chatErr);
        const localFallback = await import('../../routes/fallbackAi.js').then(m => 
          m.getLocalFallbackResponse(rawInput, input.chatMode, input.responseStyle)
        );
        return {
          text: localFallback.text,
          modelUsed: 'local-fallback-error',
          isFallback: true,
          isCrisisOverride: false,
          isPromptInjectionOverride: false,
          isConsentFallback: false
        };
      }
    } else {
      // Streaming execution
      try {
        const modelRes = await aiRequestService.generateStreamResponse({
          userId,
          userTier: input.userTier || 'Free',
          requestedModelId: input.aiModel || 'gemini-3.1-flash-lite',
          prompt: formattedPrompt,
          history: sanitizedHistory,
          systemInstruction
        });

        return {
          text: '',
          modelUsed: modelRes.modelUsed,
          isFallback: false,
          isCrisisOverride: false,
          isPromptInjectionOverride: false,
          isConsentFallback: false,
          stream: modelRes.stream
        };
      } catch (streamErr: any) {
        console.warn(`[SAFETY_PIPELINE] Streaming execution failed, falling back to local:`, streamErr?.message || streamErr);
        const localFallback = await import('../../routes/fallbackAi.js').then(m => 
          m.getLocalFallbackResponse(rawInput, input.chatMode, input.responseStyle)
        );
        return {
          text: localFallback.text,
          modelUsed: 'local-fallback-stream-error',
          isFallback: true,
          isCrisisOverride: false,
          isPromptInjectionOverride: false,
          isConsentFallback: false
        };
      }
    }
  }
};

import { z } from 'zod';

/**
 * Strict tool schemas for RuangTenang plugin system.
 * Rejects unknown fields and prevents injection of arbitrary URLs, SQL, routes, or instructions.
 */

export const validToolNames = [
  'screening',
  'mood',
  'counselors',
  'emergency',
  'articles',
  'ai_memory'
] as const;

export type ValidToolName = (typeof validToolNames)[number];

export const screeningToolSchema = z.object({
  reason: z.string().max(200).optional(),
  assessmentType: z.enum(['phq9', 'gad7', 'general']).optional()
}).strict();

export const moodToolSchema = z.object({
  reason: z.string().max(200).optional(),
  targetMood: z.number().int().min(1).max(5).optional()
}).strict();

export const counselorsToolSchema = z.object({
  reason: z.string().max(200).optional(),
  specialty: z.string().max(100).optional()
}).strict();

export const emergencyToolSchema = z.object({
  reason: z.string().max(200).optional(),
  immediateDanger: z.boolean().optional()
}).strict();

export const articlesToolSchema = z.object({
  reason: z.string().max(200).optional(),
  topic: z.enum(['anxiety', 'stress', 'sleep', 'academic', 'burnout', 'general']).optional()
}).strict();

export const aiMemoryToolSchema = z.object({
  reason: z.string().max(200).optional(),
  action: z.enum(['retrieve', 'summarize']).optional()
}).strict();

export const toolSchemasMap = {
  screening: screeningToolSchema,
  mood: moodToolSchema,
  counselors: counselorsToolSchema,
  emergency: emergencyToolSchema,
  articles: articlesToolSchema,
  ai_memory: aiMemoryToolSchema
};

export const pluginCallSchema = z.object({
  tool_call: z.enum(validToolNames),
  parameters: z.record(z.string(), z.unknown()).optional()
}).strict();

export function validateAndSanitizeToolCall(raw: unknown): {
  isValid: boolean;
  toolCall?: ValidToolName;
  parameters?: Record<string, any>;
  error?: string;
} {
  if (!raw || typeof raw !== 'object') {
    return { isValid: false, error: 'Tool call payload must be an object' };
  }

  const baseParse = pluginCallSchema.safeParse(raw);
  if (!baseParse.success) {
    return { isValid: false, error: `Invalid tool call envelope: ${baseParse.error.message}` };
  }

  const { tool_call, parameters = {} } = baseParse.data;
  const specificSchema = toolSchemasMap[tool_call];
  if (!specificSchema) {
    return { isValid: false, error: `Unrecognized tool name: ${tool_call}` };
  }

  const paramParse = specificSchema.safeParse(parameters);
  if (!paramParse.success) {
    return {
      isValid: false,
      error: `Invalid parameters for tool "${tool_call}": ${paramParse.error.issues.map(i => `${i.path.join('.')}: ${i.message}`).join(', ')}`
    };
  }

  return {
    isValid: true,
    toolCall: tool_call,
    parameters: paramParse.data
  };
}

import jwt from 'jsonwebtoken';
import { Response } from 'express';
import { serverDb, UserRecord } from '../database';
import { emailService } from './emailService';
import { safeLog } from '../security';
import crypto from 'crypto';
import { getJwtSecret } from '../middleware/auth';

const COOKIE_NAME = 'ruangtenang_session';

export interface TokenPayload {
  userId: string;
  email: string;
  role: 'mahasiswa' | 'konselor' | 'admin' | 'guest';
  tier: 'Free' | 'Pro' | 'Developer';
  sessionId: string;
  name: string;
}

export const authService = {
  /**
   * Generates JWT token for active user session.
   */
  generateSessionToken(payload: TokenPayload): string {
    return jwt.sign(payload, getJwtSecret(), {
      expiresIn: '7d',
      issuer: 'ruangtenang',
      audience: 'ruangtenang-web',
      algorithm: 'HS256',
      subject: payload.userId,
      jwtid: crypto.randomUUID()
    });
  },

  /**
   * Sets HTTP-only secure cookie on response.
   */
  setSessionCookie(res: Response, token: string): void {
    const isProduction = process.env.NODE_ENV === 'production';
    const cookieOptions = {
      httpOnly: true,
      secure: isProduction,
      sameSite: 'lax' as const,
      path: '/',
      maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
    };

    res.cookie(COOKIE_NAME, token, cookieOptions);
    // Deprecated legacy 'token' cookie: stop issuing new ones, clear legacy if present
    res.clearCookie('token', { httpOnly: true, secure: isProduction, sameSite: 'lax' as const, path: '/' });
  },

  /**
   * Clears auth cookies upon logout.
   */
  clearSessionCookie(res: Response): void {
    const isProduction = process.env.NODE_ENV === 'production';
    const clearOptions = {
      httpOnly: true,
      secure: isProduction,
      sameSite: 'lax' as const,
      path: '/',
    };
    res.clearCookie(COOKIE_NAME, clearOptions);
    res.clearCookie('token', clearOptions);
  },

  /**
   * Generates a 6-digit cryptographic numeric code.
   */
  generate6DigitCode(): string {
    return crypto.randomInt(100000, 1000000).toString();
  },

  /**
   * Sanitizes User record for client response (removes passwordHash, mfaCode, etc.)
   */
  sanitizeUser(user: UserRecord) {
    return {
      id: user.id,
      name: user.name,
      email: user.email,
      role: user.role,
      tier: user.tier,
      university: user.university,
      mfaEnabled: user.mfaEnabled,
      emailVerified: user.emailVerified,
      createdAt: user.createdAt,
    };
  }
};

/**
 * Distributed Lock Service
 * Provides multi-instance safe locks for scheduled background jobs (e.g. data retention, migrations, batch tasks).
 * Utilizes Redis atomic lock (SET key val NX EX) with DB lease lock fallback.
 */

import crypto from 'crypto';
import os from 'os';
import { prisma } from '../database.js';
import { redisService } from './redisService.js';

export class DistributedLockService {
  private static instanceId = `${os.hostname()}-${process.pid}-${crypto.randomBytes(4).toString('hex')}`;

  /**
   * Acquire a distributed lease lock for a specified duration (in seconds).
   * Returns true if lock was acquired, false if held by another active instance.
   */
  static async acquireLock(lockId: string, ttlSeconds: number = 300, customHolder?: string): Promise<boolean> {
    const holder = customHolder || this.instanceId;
    const now = new Date();
    const expiresAt = new Date(now.getTime() + ttlSeconds * 1000);
    const redisLockKey = `lock:${lockId}`;

    // 1. Try Redis Atomic Lock (SET key val NX EX)
    const redisAcquired = await redisService.setnx(redisLockKey, holder, ttlSeconds);
    if (redisAcquired) {
      // Sync to DB for monitoring/fallback
      try {
        await prisma.distributedLock.upsert({
          where: { id: lockId },
          create: {
            id: lockId,
            holder,
            acquiredAt: now,
            expiresAt,
          },
          update: {
            holder,
            acquiredAt: now,
            expiresAt,
          },
        });
      } catch (_) {}

      return true;
    }

    // Check if Redis lock exists and belongs to holder (renew lock)
    const existingHolder = await redisService.get<string>(redisLockKey);
    if (existingHolder) {
      if (existingHolder === holder) {
        await redisService.set(redisLockKey, holder, ttlSeconds);
        return true;
      }
      // Redis lock is actively held by another instance
      return false;
    }

    // 2. Fallback to Database Lock if Redis did not acquire
    try {
      const existing = await prisma.distributedLock.findUnique({
        where: { id: lockId },
      });

      if (existing) {
        // If expired or already held by this instance, renew lock
        if (new Date(existing.expiresAt).getTime() <= now.getTime() || existing.holder === holder) {
          await prisma.distributedLock.update({
            where: { id: lockId },
            data: {
              holder,
              acquiredAt: now,
              expiresAt,
            },
          });
          return true;
        }
        // Held by another active instance
        return false;
      }

      // Create new DB lock if not existing in DB
      await prisma.distributedLock.create({
        data: {
          id: lockId,
          holder,
          acquiredAt: now,
          expiresAt,
        },
      });
      return true;
    } catch (err: unknown) {
      console.warn(`[DISTRIBUTED_LOCK] Failed to acquire lock for ${lockId}:`, err.message);
      return false;
    }
  }

  /**
   * Release a previously acquired lock
   */
  static async releaseLock(lockId: string, customHolder?: string): Promise<boolean> {
    const holder = customHolder || this.instanceId;
    const redisLockKey = `lock:${lockId}`;

    let released = false;

    // 1. Release from Redis
    const currentRedisHolder = await redisService.get<string>(redisLockKey);
    if (currentRedisHolder === holder || !currentRedisHolder) {
      await redisService.del(redisLockKey);
      released = true;
    }

    // 2. Release from DB
    try {
      const existing = await prisma.distributedLock.findUnique({
        where: { id: lockId },
      });

      if (existing && existing.holder === holder) {
        await prisma.distributedLock.delete({
          where: { id: lockId },
        });
        released = true;
      }
    } catch (err: unknown) {
      console.warn(`[DISTRIBUTED_LOCK] Failed to release DB lock for ${lockId}:`, err.message);
    }

    return released;
  }

  /**
   * Execute an action exclusively with lock protection.
   * If lock cannot be acquired, returns null without executing the action.
   */
  static async withLock<T>(
    lockId: string,
    ttlSeconds: number,
    action: () => Promise<T>
  ): Promise<{ executed: boolean; result?: T; reason?: string }> {
    const uniqueHolder = `${this.instanceId}-req-${crypto.randomBytes(4).toString('hex')}`;
    const acquired = await this.acquireLock(lockId, ttlSeconds, uniqueHolder);
    if (!acquired) {
      return {
        executed: false,
        reason: `Lock for ${lockId} is currently held by another worker instance.`,
      };
    }

    try {
      const result = await action();
      return { executed: true, result };
    } finally {
      await this.releaseLock(lockId, uniqueHolder);
    }
  }
}

/**
 * Persistent Distributed State Service
 * Handles multi-instance rate-limiting, SOS cooldowns, security throttling, and circuit breakers.
 * Backed by Redis with graceful fallback to DistributedState table in the database.
 */

import { prisma } from '../database.js';
import { redisService } from './redisService.js';

export interface RateLimitResult {
  allowed: boolean;
  count: number;
  remaining: number;
  resetTime: number;
}

export interface SosCooldownResult {
  inCooldown: boolean;
  remainingSeconds: number;
  lastDispatchTimestamp?: number;
}

export class DistributedStateService {
  /**
   * Set a key-value pair with TTL in seconds
   */
  static async set(category: string, key: string, value: any, ttlSeconds: number): Promise<void> {
    const compositeKey = `${category}:${key}`;
    const expiresAt = new Date(Date.now() + ttlSeconds * 1000);
    const valueStr = typeof value === 'string' ? value : JSON.stringify(value);

    // 1. Write to Redis/In-Memory Cache
    await redisService.set(compositeKey, valueStr, ttlSeconds);

    // 2. Non-blocking sync to DB
    prisma.distributedState.upsert({
      where: { key: compositeKey },
      create: {
        key: compositeKey,
        category,
        value: valueStr,
        expiresAt,
      },
      update: {
        category,
        value: valueStr,
        expiresAt,
        updatedAt: new Date(),
      },
    }).catch((err: any) => {
      console.warn(`[DISTRIBUTED_STATE] DB sync warning for key ${compositeKey}:`, err.message);
    });
  }

  /**
   * Get value by key, returning null if expired or missing
   */
  static async get<T = any>(category: string, key: string): Promise<T | null> {
    const compositeKey = `${category}:${key}`;

    // 1. Try Redis/In-Memory
    const cached = await redisService.get<T>(compositeKey);
    if (cached !== null) {
      return cached;
    }

    // 2. Fallback to Database
    try {
      const record = await prisma.distributedState.findUnique({
        where: { key: compositeKey },
      });

      if (!record) return null;

      if (new Date(record.expiresAt).getTime() <= Date.now()) {
        // Expired, asynchronously clean up
        prisma.distributedState.delete({ where: { key: compositeKey } }).catch(() => {});
        return null;
      }

      let parsed: T;
      try {
        parsed = JSON.parse(record.value) as T;
      } catch {
        parsed = record.value as unknown as T;
      }

      // Populate cache
      const ttlRemaining = Math.max(1, Math.floor((new Date(record.expiresAt).getTime() - Date.now()) / 1000));
      await redisService.set(compositeKey, record.value, ttlRemaining);

      return parsed;
    } catch (err: unknown) {
      console.warn(`[DISTRIBUTED_STATE] Failed to read state from DB for key ${compositeKey}:`, err.message);
      return null;
    }
  }

  /**
   * Delete a key
   */
  static async delete(category: string, key: string): Promise<void> {
    const compositeKey = `${category}:${key}`;
    await redisService.del(compositeKey);
    try {
      await prisma.distributedState.delete({
        where: { key: compositeKey },
      });
    } catch {
      // Ignored if key doesn't exist
    }
  }

  /**
   * Sliding window / Token rate-limiting safe for multi-instance deployments
   */
  static async checkRateLimit(
    key: string,
    maxRequests: number,
    windowSeconds: number,
    category: string = 'RATE_LIMIT'
  ): Promise<RateLimitResult> {
    const compositeKey = `${category}:${key}`;
    const now = Date.now();

    try {
      const currentCount = await redisService.incr(compositeKey, windowSeconds);
      const resetTime = now + windowSeconds * 1000;

      const allowed = currentCount <= maxRequests;
      const remaining = Math.max(0, maxRequests - currentCount);

      // Async DB sync for durability/auditing
      prisma.distributedState.upsert({
        where: { key: compositeKey },
        create: {
          key: compositeKey,
          category,
          value: String(currentCount),
          expiresAt: new Date(resetTime),
        },
        update: {
          value: String(currentCount),
          expiresAt: new Date(resetTime),
        },
      }).catch(() => {});

      return {
        allowed,
        count: currentCount,
        remaining,
        resetTime,
      };
    } catch (err: unknown) {
      console.warn(`[DISTRIBUTED_STATE] Rate limit check error for ${key}:`, err.message);
      return {
        allowed: true,
        count: 1,
        remaining: maxRequests - 1,
        resetTime: now + windowSeconds * 1000,
      };
    }
  }

  /**
   * Emergency SOS Cooldown check (Multi-instance safe)
   */
  static async checkSosCooldown(userId: string, defaultCooldownSeconds = 180): Promise<SosCooldownResult> {
    const record = await this.get<{ timestamp: number } | number>('SOS_COOLDOWN', userId);
    if (!record) {
      return { inCooldown: false, remainingSeconds: 0 };
    }

    const lastTimestamp = typeof record === 'number' ? record : record.timestamp;
    const now = Date.now();
    const elapsedSeconds = Math.floor((now - lastTimestamp) / 1000);

    if (elapsedSeconds < defaultCooldownSeconds) {
      const remainingSeconds = defaultCooldownSeconds - elapsedSeconds;
      return {
        inCooldown: true,
        remainingSeconds,
        lastDispatchTimestamp: lastTimestamp,
      };
    }

    return { inCooldown: false, remainingSeconds: 0 };
  }

  /**
   * Record an SOS dispatch cooldown
   */
  static async recordSosDispatch(userId: string, cooldownSeconds = 180): Promise<void> {
    await this.set('SOS_COOLDOWN', userId, { timestamp: Date.now() }, cooldownSeconds);
  }

  /**
   * Security Throttling (e.g. failed login attempts, abuse defense)
   */
  static async checkSecurityThrottle(identifier: string): Promise<{ locked: boolean; remainingSeconds: number }> {
    const record = await this.get<{ lockedUntil: number }>('SECURITY_LOCK', identifier);
    if (!record) return { locked: false, remainingSeconds: 0 };

    const remaining = Math.ceil((record.lockedUntil - Date.now()) / 1000);
    if (remaining > 0) {
      return { locked: true, remainingSeconds: remaining };
    }
    return { locked: false, remainingSeconds: 0 };
  }

  /**
   * Record security lock / throttle
   */
  static async lockSecurityIdentifier(identifier: string, lockoutSeconds: number): Promise<void> {
    const lockedUntil = Date.now() + lockoutSeconds * 1000;
    await this.set('SECURITY_LOCK', identifier, { lockedUntil }, lockoutSeconds);
  }

  /**
   * Clean expired state records in bulk
   */
  static async cleanExpired(): Promise<number> {
    try {
      const res = await prisma.distributedState.deleteMany({
        where: {
          expiresAt: {
            lte: new Date(),
          },
        },
      });
      return res.count;
    } catch {
      return 0;
    }
  }
}

import crypto from 'crypto';
import { getValidatedEncryptionKey } from '../config/envValidation.js';

const ALGORITHM = 'aes-256-gcm';
let activeKeyVersion = process.env.ACTIVE_ENCRYPTION_KEY_VERSION || 'v1';

export const encryptionService = {
  getCurrentKeyVersion(): string {
    return activeKeyVersion;
  },

  setActiveKeyVersion(version: string): void {
    activeKeyVersion = version;
  },

  /**
   * Encrypts plaintext using AES-256-GCM with fail-closed semantics.
   * Throws an error if plaintext is missing/empty or if encryption fails.
   */
  encryptRequiredSensitive(plaintext: string, targetVersion?: string): string {
    if (!plaintext || typeof plaintext !== 'string' || plaintext.trim() === '') {
      throw new Error('ENCRYPTION_FAILED: Required sensitive field is empty or missing.');
    }
    const encrypted = this.encryptSensitive(plaintext, targetVersion);
    if (!encrypted || !this.isEncrypted(encrypted)) {
      throw new Error('ENCRYPTION_FAILED: Encryption produced invalid or empty output.');
    }
    return encrypted;
  },

  /**
   * Encrypts plaintext using AES-256-GCM with the active key version.
   * Output Format: [VERSION]:[IV(base64)]:[AUTHTAG(base64)]:[CIPHERTEXT(base64)]
   */
  encryptSensitive(plaintext: string | null | undefined, targetVersion?: string): string | null {
    if (plaintext === null || plaintext === undefined || plaintext === '') {
      return plaintext || null;
    }

    const versionToUse = targetVersion || activeKeyVersion;

    try {
      const key = getValidatedEncryptionKey(versionToUse);
      const iv = crypto.randomBytes(12);
      const cipher = crypto.createCipheriv(ALGORITHM, key, iv);

      let ciphertext = cipher.update(plaintext, 'utf8', 'base64');
      ciphertext += cipher.final('base64');
      const authTag = cipher.getAuthTag().toString('base64');
      const ivBase64 = iv.toString('base64');

      return `${versionToUse}:${ivBase64}:${authTag}:${ciphertext}`;
    } catch (error) {
      console.error('Encryption failed:', error);
      throw new Error('Failed to encrypt sensitive data');
    }
  },

  /**
   * Decrypts ciphertext using AES-256-GCM by parsing the embedded key version.
   */
  decryptSensitive(encryptedText: string | null | undefined): string | null {
    if (encryptedText === null || encryptedText === undefined || encryptedText === '') {
      return encryptedText || null;
    }

    // Parse version prefix dynamically for Key Versioning support (e.g., v1, v2)
    const versionMatch = encryptedText.match(/^(v\d+):/);
    if (!versionMatch) {
      // Return plaintext if legacy unencrypted format is encountered
      return encryptedText;
    }

    const version = versionMatch[1];

    try {
      const key = getValidatedEncryptionKey(version);
      const parts = encryptedText.split(':');
      if (parts.length !== 4) {
        throw new Error('Invalid encrypted data format');
      }

      const [, ivBase64, authTagBase64, ciphertext] = parts;

      const iv = Buffer.from(ivBase64, 'base64');
      const authTag = Buffer.from(authTagBase64, 'base64');

      const decipher = crypto.createDecipheriv(ALGORITHM, key, iv);
      decipher.setAuthTag(authTag);

      let plaintext = decipher.update(ciphertext, 'base64', 'utf8');
      plaintext += decipher.final('utf8');

      return plaintext;
    } catch (error) {
      console.error(`Decryption failed for sensitive field using key version ${version}.`);
      throw new Error('Failed to decrypt sensitive data');
    }
  },

  /**
   * Checks if string is already encrypted in canonical versioned format.
   */
  isEncrypted(text: string | null | undefined): boolean {
    if (!text || typeof text !== 'string') return false;
    return /^v\d+:[A-Za-z0-9+/=]+:[A-Za-z0-9+/=]+:[A-Za-z0-9+/=]+$/.test(text);
  },

  /**
   * Re-encrypts ciphertext using the currently active key version.
   */
  reencryptWithCurrentKey(encryptedText: string | null | undefined): string | null {
    if (!encryptedText) return encryptedText || null;
    const decrypted = this.decryptSensitive(encryptedText);
    return this.encryptSensitive(decrypted, activeKeyVersion);
  },

  generateRandomKeyBase64(): string {
    return crypto.randomBytes(32).toString('base64');
  }
};

import Redis from 'ioredis';

interface CacheEntry {
  value: string;
  expiresAt: number | null;
}

export class RedisService {
  private client: Redis | null = null;
  private isConnected: boolean = false;
  private memoryCache = new Map<string, CacheEntry>();
  private lastWarnTimestamp = 0;

  constructor() {
    this.initRedis();
  }

  private initRedis() {
    const redisUrl = process.env.REDIS_URL;
    const redisHost = process.env.REDIS_HOST;

    if (!redisUrl && !redisHost && process.env.NODE_ENV === 'test') {
      // In test mode without explicit Redis env, default to in-memory fallback
      return;
    }

    try {
      const options: any = {
        maxRetriesPerRequest: 1,
        enableOfflineQueue: false,
        connectTimeout: 2000,
        retryStrategy: (times: number) => {
          if (times > 3) return null; // Stop retrying after 3 attempts
          return Math.min(times * 200, 1000);
        },
      };

      if (redisUrl) {
        this.client = new Redis(redisUrl, options);
      } else if (redisHost) {
        this.client = new Redis({
          host: redisHost,
          port: parseInt(process.env.REDIS_PORT || '6379', 10),
          password: process.env.REDIS_PASSWORD || undefined,
          ...options,
        });
      } else if (process.env.USE_REDIS === 'true') {
        this.client = new Redis(options);
      }

      if (this.client) {
        this.client.on('connect', () => {
          this.isConnected = true;
        });

        this.client.on('ready', () => {
          this.isConnected = true;
        });

        this.client.on('error', (err) => {
          this.isConnected = false;
          this.logWarnOnce(`[REDIS] Client connection error: ${err.message}`);
        });

        this.client.on('close', () => {
          this.isConnected = false;
        });
      }
    } catch (err: unknown) {
      this.isConnected = false;
      this.logWarnOnce(`[REDIS] Failed to initialize Redis client: ${err.message}`);
    }
  }

  private logWarnOnce(msg: string) {
    const now = Date.now();
    if (now - this.lastWarnTimestamp > 30000) {
      console.warn(msg);
      this.lastWarnTimestamp = now;
    }
  }

  public forceOffline(offline = true) {
    if (offline) {
      this.isConnected = false;
    } else if (this.client) {
      this.isConnected = this.client.status === 'ready';
    } else {
      this.isConnected = false;
    }
  }

  public async isHealthy(): Promise<boolean> {
    if (!this.isConnected || !this.client) return false;
    try {
      const pingRes = await this.client.ping();
      return pingRes === 'PONG';
    } catch {
      this.isConnected = false;
      return false;
    }
  }

  public async get<T = any>(key: string): Promise<T | null> {
    if (this.isConnected && this.client) {
      try {
        const data = await this.client.get(key);
        if (data === null) return null;
        try {
          return JSON.parse(data) as T;
        } catch {
          return data as unknown as T;
        }
      } catch (err: unknown) {
        this.isConnected = false;
        this.logWarnOnce(`[REDIS_FALLBACK] Get failed for ${key}: ${err.message}`);
      }
    }

    // In-Memory Fallback
    const entry = this.memoryCache.get(key);
    if (!entry) return null;

    if (entry.expiresAt !== null && Date.now() > entry.expiresAt) {
      this.memoryCache.delete(key);
      return null;
    }

    try {
      return JSON.parse(entry.value) as T;
    } catch {
      return entry.value as unknown as T;
    }
  }

  public async set(key: string, value: any, ttlSeconds?: number): Promise<void> {
    const valStr = typeof value === 'string' ? value : JSON.stringify(value);

    if (this.isConnected && this.client) {
      try {
        if (ttlSeconds && ttlSeconds > 0) {
          await this.client.set(key, valStr, 'EX', ttlSeconds);
        } else {
          await this.client.set(key, valStr);
        }
        return;
      } catch (err: unknown) {
        this.isConnected = false;
        this.logWarnOnce(`[REDIS_FALLBACK] Set failed for ${key}: ${err.message}`);
      }
    }

    // In-Memory Fallback
    const expiresAt = ttlSeconds && ttlSeconds > 0 ? Date.now() + ttlSeconds * 1000 : null;
    this.memoryCache.set(key, { value: valStr, expiresAt });
  }

  /**
   * Atomic set-if-not-exists with TTL
   * Returns true if lock/key was created, false if key already exists
   */
  public async setnx(key: string, value: any, ttlSeconds: number): Promise<boolean> {
    const valStr = typeof value === 'string' ? value : JSON.stringify(value);

    if (this.isConnected && this.client) {
      try {
        const res = await this.client.set(key, valStr, 'EX', ttlSeconds, 'NX');
        return res === 'OK';
      } catch (err: unknown) {
        this.isConnected = false;
        this.logWarnOnce(`[REDIS_FALLBACK] Setnx failed for ${key}: ${err.message}`);
      }
    }

    // In-Memory Fallback
    const existing = this.memoryCache.get(key);
    const now = Date.now();
    if (existing && (existing.expiresAt === null || existing.expiresAt > now)) {
      return false; // Already locked
    }

    this.memoryCache.set(key, {
      value: valStr,
      expiresAt: now + ttlSeconds * 1000,
    });
    return true;
  }

  public async del(key: string): Promise<void> {
    if (this.isConnected && this.client) {
      try {
        await this.client.del(key);
        return;
      } catch (err: unknown) {
        this.isConnected = false;
        this.logWarnOnce(`[REDIS_FALLBACK] Del failed for ${key}: ${err.message}`);
      }
    }

    // In-Memory Fallback
    this.memoryCache.delete(key);
  }

  public async delPattern(pattern: string): Promise<void> {
    if (this.isConnected && this.client) {
      try {
        const keys = await this.client.keys(pattern);
        if (keys.length > 0) {
          await this.client.del(...keys);
        }
        return;
      } catch (err: unknown) {
        this.isConnected = false;
        this.logWarnOnce(`[REDIS_FALLBACK] DelPattern failed for ${pattern}: ${err.message}`);
      }
    }

    // In-Memory Fallback
    const regex = new RegExp('^' + pattern.replace(/\*/g, '.*') + '$');
    for (const key of this.memoryCache.keys()) {
      if (regex.test(key)) {
        this.memoryCache.delete(key);
      }
    }
  }

  public async incr(key: string, ttlSeconds?: number): Promise<number> {
    if (this.isConnected && this.client) {
      try {
        const count = await this.client.incr(key);
        if (count === 1 && ttlSeconds && ttlSeconds > 0) {
          await this.client.expire(key, ttlSeconds);
        }
        return count;
      } catch (err: unknown) {
        this.isConnected = false;
        this.logWarnOnce(`[REDIS_FALLBACK] Incr failed for ${key}: ${err.message}`);
      }
    }

    // In-Memory Fallback
    const now = Date.now();
    const existing = this.memoryCache.get(key);
    let count = 0;
    let expiresAt = ttlSeconds ? now + ttlSeconds * 1000 : null;

    if (existing && (existing.expiresAt === null || existing.expiresAt > now)) {
      count = parseInt(existing.value, 10) || 0;
      expiresAt = existing.expiresAt;
    }

    count += 1;
    this.memoryCache.set(key, { value: String(count), expiresAt });
    return count;
  }

  public async expire(key: string, ttlSeconds: number): Promise<boolean> {
    if (this.isConnected && this.client) {
      try {
        const res = await this.client.expire(key, ttlSeconds);
        return res === 1;
      } catch (err: unknown) {
        this.isConnected = false;
        this.logWarnOnce(`[REDIS_FALLBACK] Expire failed for ${key}: ${err.message}`);
      }
    }

    // In-Memory Fallback
    const existing = this.memoryCache.get(key);
    if (!existing) return false;
    existing.expiresAt = Date.now() + ttlSeconds * 1000;
    return true;
  }

  public async flush(): Promise<void> {
    this.memoryCache.clear();
    if (this.isConnected && this.client) {
      try {
        await this.client.flushdb();
      } catch (err: unknown) {
        this.logWarnOnce(`[REDIS] Flushdb failed: ${err.message}`);
      }
    }
  }

  public async disconnect(): Promise<void> {
    this.memoryCache.clear();
    if (this.client) {
      try {
        await this.client.quit();
      } catch {
        // Ignore disconnect error
      }
      this.client = null;
      this.isConnected = false;
    }
  }
}

export const redisService = new RedisService();

import PDFDocument from 'pdfkit';
import fs from 'fs';
import path from 'path';
import ExcelJS from 'exceljs';
import { prisma } from '../database';

export interface ReportMetrics {
  totalSessions: number;
  crisisRatio: string;
  mostCommonConcern: string;
  dateRange: string;
}

export async function generateRectorateReport(metrics: ReportMetrics): Promise<string> {
  return new Promise((resolve, reject) => {
    try {
      const doc = new PDFDocument({ margin: 50, size: 'A4' });
      const reportsDir = path.join(process.cwd(), 'reports');

      if (!fs.existsSync(reportsDir)) {
        fs.mkdirSync(reportsDir, { recursive: true });
      }

      const fileName = `Laporan_Rektorat_Agregat_${Date.now()}.pdf`;
      const filePath = path.join(reportsDir, fileName);
      const writeStream = fs.createWriteStream(filePath);

      doc.pipe(writeStream);

      // Header
      doc.fontSize(22).fillColor('#0f172a').font('Helvetica-Bold').text('Laporan Kesehatan Mental Kampus (Agregat)', { align: 'center' });
      doc.moveDown(0.5);
      doc.fontSize(12).fillColor('#64748b').font('Helvetica').text(`Periode: ${metrics.dateRange}`, { align: 'center' });
      doc.moveDown(2);

      // Metrik Utama
      doc.fontSize(16).fillColor('#0f172a').font('Helvetica-Bold').text('1. Ringkasan Kinerja & Kondisi Umum');
      doc.moveDown(0.5);

      doc.fontSize(12).fillColor('#334155').font('Helvetica')
         .text(`• Total Sesi Konseling Terfasilitasi: ${metrics.totalSessions} sesi`)
         .text(`• Rasio Identifikasi Krisis: ${metrics.crisisRatio} (Tren Penurunan 12%)`)
         .text(`• Keluhan Dominan: ${metrics.mostCommonConcern}`);

      doc.moveDown(1.5);

      // Stressor Breakdown
      doc.fontSize(16).fillColor('#0f172a').font('Helvetica-Bold').text('2. Pemetaan Topik Pemicu Stres (Stressor Breakdown)');
      doc.moveDown(0.5);
      doc.fontSize(12).fillColor('#334155').font('Helvetica').text('Distribusi berdasarkan topik yang paling sering muncul dalam catatan log agregat:');
      doc.moveDown();

      // Fake Chart / Bars
      const stressors = [
        { name: 'Tugas Akademik & Skripsi', pct: 45, color: '#ef4444' },
        { name: 'Masalah Finansial/UKT', pct: 25, color: '#f59e0b' },
        { name: 'Hubungan & Pertemanan', pct: 20, color: '#10b981' },
        { name: 'Persiapan Karir & Magang', pct: 10, color: '#3b82f6' },
      ];

      stressors.forEach(s => {
        doc.fontSize(10).fillColor('#475569').text(`${s.name} (${s.pct}%)`);
        const barWidth = (s.pct / 100) * 400;
        doc.roundedRect(doc.x, doc.y + 2, barWidth, 12, 4).fill(s.color);
        doc.moveDown(1.5);
      });

      doc.moveDown(1);

      // Efektivitas Intervensi
      doc.fontSize(16).fillColor('#0f172a').font('Helvetica-Bold').text('3. Efektivitas Intervensi Konselor Kampus');
      doc.moveDown(0.5);
      doc.fontSize(12).fillColor('#334155').font('Helvetica')
         .text('• Rata-rata penurunan skor kecemasan (GAD-7) setelah 3 sesi: -4.5 Poin')
         .text('• Rata-rata penurunan skor depresi (PHQ-9) setelah 3 sesi: -5.2 Poin')
         .text('• Tindak lanjut rujukan psikiatri (Luar Kampus): 3.2% dari total kasus');

      doc.moveDown(3);

      // Keterangan / Footer
      doc.rect(50, doc.y, 495, 60).fill('#f8fafc');
      doc.fontSize(10).fillColor('#94a3b8').font('Helvetica-Oblique').text('Pernyataan Kepatuhan UU PDP No. 27/2022:', 60, doc.y - 50);
      doc.fontSize(9).text('Laporan ini 100% anonim dan di-generate berdasarkan data agregat tanpa memuat nama, NIM, atau PII (Personally Identifiable Information) mahasiswa. Laporan ini ditujukan khusus untuk perencanaan kebijakan rektorat.', 60, doc.y);

      doc.end();

      writeStream.on('finish', () => {
        resolve(filePath);
      });
      writeStream.on('error', (err) => {
        reject(err);
      });
    } catch (error) {
      reject(error);
    }
  });
}

export async function generateStudentProgressPdf(userId: string, studentName: string): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    (async () => {
      try {
        const doc = new PDFDocument({ margin: 50, size: 'A4' });
        const chunks: Buffer[] = [];

        doc.on('data', (chunk) => chunks.push(chunk));
        doc.on('end', () => resolve(Buffer.concat(chunks)));
        doc.on('error', (err) => reject(err));

        // Fetch data
        const screenings = await (prisma as any).screenings.findMany({
          where: { userId },
          orderBy: { timestamp: 'asc' }
        });

        const latestScreening = screenings.length > 0 ? screenings[screenings.length - 1] : null;

        // Header
        doc.fontSize(22).fillColor('#0f172a').font('Helvetica-Bold').text('Ringkasan Perkembangan Emosional', { align: 'center' });
        doc.moveDown(0.5);
        doc.fontSize(12).fillColor('#64748b').font('Helvetica').text('Aplikasi RuangTenang Kampus', { align: 'center' });
        doc.moveDown(2);

        // Identitas (Optional / Masked for safety, but this is their own export so name is fine, just safe practices)
        doc.fontSize(12).fillColor('#334155').font('Helvetica-Bold').text(`Nama Mahasiswa: ${studentName || 'Anonim'}`);
        doc.font('Helvetica').text(`Tanggal Unduh: ${new Date().toLocaleDateString('id-ID')}`);
        doc.moveDown(1.5);

        // Metrik Saat Ini
        doc.fontSize(16).fillColor('#0f172a').font('Helvetica-Bold').text('Kondisi Terkini Berdasarkan Skrining Terakhir');
        doc.moveDown(0.5);

        if (latestScreening) {
          doc.fontSize(12).fillColor('#334155').font('Helvetica')
             .text(`Tanggal Skrining: ${new Date(latestScreening.timestamp).toLocaleDateString('id-ID')}`)
             .text(`Skor PHQ-9 (Depresi): ${latestScreening.phq9Score} / 27`)
             .text(`Skor GAD-7 (Kecemasan): ${latestScreening.gad7Score} / 21`);
        } else {
          doc.fontSize(12).fillColor('#334155').font('Helvetica').text('Belum ada data skrining yang tercatat.');
        }

        doc.moveDown(1.5);

        // Catatan Konseling (Placeholder untuk dibawa ke sesi)
        doc.fontSize(16).fillColor('#0f172a').font('Helvetica-Bold').text('Ruang Catatan Konselor / Psikolog');
        doc.moveDown(0.5);

        // Draw lines for notes
        const startY = doc.y;
        for (let i = 0; i < 10; i++) {
          doc.moveTo(50, startY + (i * 25)).lineTo(545, startY + (i * 25)).lineWidth(1).strokeColor('#e2e8f0').stroke();
        }

        doc.end();
      } catch (err) {
        reject(err);
      }
    })();
  });
}

