      case 'security':
        return <ShieldCheck className="w-3.5 h-3.5" />;
      case 'fix':
        return <Wrench className="w-3.5 h-3.5" />;
      case 'ai':
        return <Brain className="w-3.5 h-3.5" />;
    }
  };

  return (
