            })}
          </div>
        </div>

        {/* Scrollable Changelog List */}
        <div className="flex-1 overflow-y-auto p-4 sm:p-6 space-y-6 custom-scrollbar bg-slate-50/50 dark:bg-slate-950/40">
          {filteredReleases.length === 0 ? (
            <div className="text-center py-12 px-4 space-y-3">
              <div className="w-12 h-12 rounded-2xl bg-slate-100 dark:bg-slate-800 text-slate-400 flex items-center justify-center mx-auto">
                <Info className="w-6 h-6" />
              </div>
              <h3 className="font-bold text-sm text-primary">
                Tidak ada catatan pembaruan yang cocok
              </h3>
              <p className="text-xs text-secondary max-w-sm mx-auto">
                Coba sesuaikan kata kunci pencarian atau pilih filter kategori "Semua" untuk melihat riwayat rilis lainnya.
              </p>
              <button
                onClick={() => { setSearchQuery(''); setSelectedCategory('all'); setSelectedPeriod('all'); }}
                className="px-3 py-1.5 text-xs font-semibold text-teal-600 hover:text-teal-700 bg-teal-50 dark:bg-teal-950/60 rounded-xl cursor-pointer"
              >
                Reset Filter
              </button>
            </div>
          ) : (
            filteredReleases.map((release) => {
              const isExpanded = expandedVersions[release.version] ?? true;
              const filteredChanges = selectedCategory === 'all' 
                ? release.changes 
                : release.changes.filter(c => c.category === selectedCategory);

              if (filteredChanges.length === 0 && selectedCategory !== 'all') {
                return null;
              }

              return (
                <div 
                  key={release.version}
                  className={`surface-card rounded-2xl border transition-all shadow-3xs overflow-hidden ${
                    release.isLatest 
                      ? 'border-teal-500/70 dark:border-teal-500/50 ring-2 ring-teal-500/10' 
                      : 'border-default'
                  }`}
                >
                  {/* Release Card Header */}
                  <div 
                    onClick={() => toggleExpand(release.version)}
                    className="p-4 sm:p-5 flex flex-col sm:flex-row sm:items-center justify-between gap-3 cursor-pointer hover:bg-slate-50/70 dark:hover:bg-slate-800/40 transition-colors"
                  >
                    <div className="space-y-1.5 min-w-0 flex-1">
                      <div className="flex items-center gap-2 flex-wrap">
                        <span className="font-mono text-sm sm:text-base font-extrabold text-slate-900 dark:text-white">
                          {release.version}
                        </span>

                        {release.badge && (
                          <span className={`px-2 py-0.5 text-[10.5px] font-bold rounded-full border ${
                            release.isLatest 
                              ? 'bg-teal-500 text-white border-teal-600'
                              : 'bg-slate-100 dark:bg-slate-800 text-secondary border-slate-200 dark:border-slate-700'
                          }`}>
                            {release.badge}
                          </span>
                        )}

                        <span className="px-2 py-0.5 text-[10px] font-medium bg-stone-100 dark:bg-slate-800 text-secondary rounded-full">
                          {release.periodLabel}
                        </span>

                        <span className="text-xs text-slate-400 flex items-center gap-1">
                          <Calendar className="w-3 h-3" /> {release.releaseTime || release.date}
                        </span>
                      </div>

                      <h3 className="text-sm font-bold text-primary">
                        {release.title}
                      </h3>
                      <p className="text-xs text-secondary line-clamp-2">
                        {release.tagline}
                      </p>
                    </div>

                    <div className="flex items-center gap-2 shrink-0 self-end sm:self-center">
                      <button
                        type="button"
                        onClick={(e) => {
                          e.stopPropagation();
                          handleCopyNotes(release);
                        }}
                        className="p-2 text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition-colors text-xs flex items-center gap-1 cursor-pointer"
                        title="Salin Catatan Rilis"
                      >
                        {copiedVersion === release.version ? (
                          <>
                            <Check className="w-3.5 h-3.5 text-teal-600" />
                            <span className="text-[11px] text-teal-600 font-semibold hidden xs:inline">Tersalin</span>
                          </>
                        ) : (
                          <>
                            <Copy className="w-3.5 h-3.5" />
                            <span className="text-[11px] hidden xs:inline">Salin</span>
                          </>
                        )}
                      </button>

                      <div className="p-1.5 text-slate-400 hover:text-slate-700 dark:hover:text-slate-200">
                        {isExpanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
                      </div>
                    </div>
                  </div>

                  {/* Expanded Content */}
                  {isExpanded && (
                    <div className="px-4 pb-5 sm:px-5 sm:pb-5 space-y-4 border-t border-slate-100 dark:border-slate-800/80 pt-4">

                      {/* Key Highlights */}
                      {release.highlights.length > 0 && selectedCategory === 'all' && (
                        <div className="p-3 bg-teal-50/50 dark:bg-teal-950/30 border border-teal-100 dark:border-teal-900/60 rounded-xl space-y-1.5">
                          <span className="text-[11px] font-bold text-teal-900 dark:text-teal-300 uppercase tracking-wider flex items-center gap-1.5">
                            <Sparkles className="w-3.5 h-3.5 text-teal-600" /> Ringkasan Utama
                          </span>
                          <ul className="text-xs text-teal-950 dark:text-teal-200 space-y-1 pl-1">
                            {release.highlights.map((hl, idx) => (
                              <li key={idx} className="flex items-start gap-2">
                                <CheckCircle2 className="w-3.5 h-3.5 text-teal-600 dark:text-teal-400 shrink-0 mt-0.5" />
                                <span>{hl}</span>
                              </li>
                            ))}
                          </ul>
                        </div>
                      )}

                      {/* Detailed Changes List */}
                      <div className="space-y-2.5">
                        <span className="text-[11px] font-bold text-muted uppercase tracking-wider">
                          Daftar Perubahan ({filteredChanges.length})
                        </span>

                        <div className="space-y-2">
                          {filteredChanges.map(change => {
                            const cat = CATEGORY_METADATA[change.category];
                            return (
                              <div 
                                key={change.id}
                                className="p-3 bg-stone-50/60 dark:bg-slate-800/50 border border-slate-200/70 dark:border-slate-700/60 rounded-xl space-y-1.5 hover:border-slate-300 dark:hover:border-slate-600 transition-colors"
                              >
                                <div className="flex items-start justify-between gap-2">
                                  <div className="flex items-center gap-2 flex-wrap">
                                    <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded text-[10px] font-bold border ${cat.bgClass} ${cat.colorClass} ${cat.borderClass}`}>
                                      {renderCategoryIcon(change.category)}
                                      {cat.label}
                                    </span>
                                    <h4 className="text-xs font-bold text-primary">
                                      {change.title}
                                    </h4>
                                  </div>
                                </div>

                                <p className="text-xs text-secondary leading-relaxed pl-0.5">
                                  {change.description}
                                </p>

                                {change.impact && (
                                  <div className="text-[11px] text-teal-800 dark:text-teal-300 bg-teal-50/60 dark:bg-teal-950/40 px-2.5 py-1 rounded-lg border border-teal-100 dark:border-teal-900/50 flex items-start gap-1.5 mt-1">
                                    <span className="font-bold shrink-0">Dampak:</span>
                                    <span>{change.impact}</span>
                                  </div>
                                )}
                              </div>
                            );
                          })}
                        </div>
                      </div>

                      {/* Build tag footer */}
                      {release.buildNumber && (
                        <div className="flex items-center justify-between text-[10px] text-slate-400 font-mono pt-1">
                          <span>Build ID: {release.buildNumber}</span>
                          <span>Verified Deployment</span>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              );
            })
          )}
        </div>

        {/* Footer Actions */}
        <div className="p-4 sm:px-6 border-t border-default surface-card flex flex-col sm:flex-row items-center justify-between gap-3 shrink-0">
          <div className="flex items-center gap-2 text-xs text-secondary">
            <CheckCircle2 className="w-4 h-4 text-teal-600" />
            <span>Pembaruan otomatis diterapkan secara transparan tanpa perlu reload manual.</span>
          </div>

          <div className="flex items-center gap-2 w-full sm:w-auto">
            <button
              type="button"
              onClick={handleMarkAsRead}
              className="w-full sm:w-auto px-4 py-2 bg-teal-600 hover:bg-teal-700 active:scale-[0.98] text-white rounded-xl text-xs font-bold transition-all shadow-3xs cursor-pointer flex items-center justify-center gap-2 min-h-[38px]"
            >
              <Check className="w-4 h-4" />
              {hasMarkedRead ? 'Telah Ditandai Selesai' : 'Saya Mengerti (Tandai Selesai)'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Plus, Settings, Search, MessageSquare, MoreHorizontal, Edit2, Trash2, Pin, Archive, X, Heart, Stethoscope, Users, AlertCircle, LogOut, LogIn, Sun, Moon, Bell } from 'lucide-react';
import { isToday, isYesterday } from 'date-fns';
import { Chat } from '../../features/chat/types';
import { motion, AnimatePresence } from 'motion/react';
import { apiClient } from '../../lib/apiClient';
import { useTheme } from '../../contexts/ThemeContext';
import { getNotifications } from '../../lib/notificationStore';

interface SidebarProps {
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
  onNewChat: () => void;
  chats: Chat[];
  currentChatId?: string;
  onSelectChat: (id: string) => void;
  onDeleteChat: (id: string) => void;
  onUpdateTitle: (id: string, title: string) => void;
  onTogglePin: (id: string) => void;
  onToggleArchive: (id: string) => void;
  onLogout?: () => void;
  onOpenSettings?: () => void;
  onOpenAuth?: () => void;
  onOpenChangelog?: () => void;
  onOpenNotifications?: () => void;
  user?: any;
  isLoading?: boolean;
}

export default function Sidebar({ isOpen, setIsOpen, onNewChat, chats, currentChatId, onSelectChat, onDeleteChat, onUpdateTitle, onTogglePin, onToggleArchive, onLogout, onOpenSettings, onOpenAuth, onOpenNotifications, user, isLoading }: SidebarProps) {
  const navigate = useNavigate();
  const { actualTheme, toggleTheme } = useTheme();
  const [search, setSearch] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState('');
  const [menuOpenId, setMenuOpenId] = useState<string | null>(null);
  const [showArchived, setShowArchived] = useState(false);
  const [searchResults, setSearchResults] = useState<Chat[]>([]);
  const [unreadNotificationsCount, setUnreadNotificationsCount] = useState(0);

  useEffect(() => {
    const updateUnread = () => {
      try {
        const list = getNotifications();
        setUnreadNotificationsCount(list.filter(n => !n.read).length);
      } catch (err) {
        console.warn(err);
      }
    };
    updateUnread();
    window.addEventListener('ruangtenang_notifications_updated', updateUnread);
    return () => window.removeEventListener('ruangtenang_notifications_updated', updateUnread);
  }, []);

  useEffect(() => {
    if (!search.trim()) {
      setSearchResults([]);
      return;
    }

    let isCancelled = false;
    const delay = setTimeout(() => {
      apiClient.get(`/api/v1/chat/search?q=${encodeURIComponent(search.trim())}`)
        .then(res => {
          if (!isCancelled) {
            if (res.success && Array.isArray(res.data)) {
              setSearchResults(res.data);
            } else {
              setSearchResults([]);
            }
          }
        })
        .catch(err => {
          if (!isCancelled) {
            console.error('Failed to search chats:', err);
            setSearchResults([]);
          }
        });
    }, 300);
    return () => {
      isCancelled = true;
      clearTimeout(delay);
    };
  }, [search]);

  const displayChats = search.trim() ? searchResults : chats;
  const filteredChats = displayChats.filter(c => (showArchived ? c.isArchived : !c.isArchived) && !c.isTemporary);

  const pinnedChats = filteredChats.filter(c => c.isPinned);
  const unpinnedChats = filteredChats.filter(c => !c.isPinned);

  const safeParseDate = (d: any): Date | null => {
    if (!d) return null;
    const date = new Date(d);
    return isNaN(date.getTime()) ? null : date;
  };

  const isTodaySafe = (d: any) => {
    const parsed = safeParseDate(d);
    return parsed ? isToday(parsed) : false;
  };

  const isYesterdaySafe = (d: any) => {
    const parsed = safeParseDate(d);
    return parsed ? isYesterday(parsed) : false;
  };

  const isWithin7DaysSafe = (d: any) => {
    const parsed = safeParseDate(d);
    if (!parsed) return false;
    const now = new Date();
    const diffDays = (now.getTime() - parsed.getTime()) / (1000 * 3600 * 24);
    return diffDays <= 7 && !isToday(parsed) && !isYesterday(parsed);
  };

  const groups = {
    'Hari Ini': unpinnedChats.filter(c => isTodaySafe(c.updatedAt)),
    'Kemarin': unpinnedChats.filter(c => isYesterdaySafe(c.updatedAt)),
    '7 Hari Terakhir': unpinnedChats.filter(c => isWithin7DaysSafe(c.updatedAt)),
    'Lebih Lama': unpinnedChats.filter(c => !isTodaySafe(c.updatedAt) && !isYesterdaySafe(c.updatedAt) && !isWithin7DaysSafe(c.updatedAt))
  };

  const handleEditSubmit = (id: string) => {
    if (editTitle.trim()) onUpdateTitle(id, editTitle);
    setEditingId(null);
  };

  const renderChatItem = (c: Chat) => {
    const isActive = currentChatId === c.id;
    return (
      <div 
        key={c.id} 
        className={`group relative flex items-center gap-2 w-full px-2 py-0.5 min-h-[44px] sm:min-h-[34px] rounded-lg text-[12.5px] transition-colors text-left ${
          isActive 
            ? 'bg-teal-50 dark:bg-teal-950/40 text-teal-700 dark:text-teal-300 font-medium' 
            : 'hover:bg-slate-100/80 dark:hover:bg-slate-800/70 text-secondary'
        }`}
      >
        <MessageSquare className={`w-3.5 h-3.5 shrink-0 ${isActive ? 'text-teal-600 dark:text-teal-400' : 'text-muted'}`} />

        {editingId === c.id ? (
          <input 
            autoFocus
            value={editTitle}
            onChange={e => setEditTitle(e.target.value)}
            onBlur={() => handleEditSubmit(c.id)}
            onKeyDown={e => e.key === 'Enter' && handleEditSubmit(c.id)}
            className="flex-1 bg-white dark:bg-slate-800 border border-teal-500 rounded px-2 py-1 text-[12px] text-primary outline-none ring-2 ring-teal-500/20 min-h-[36px]"
          />
        ) : (
          <button 
            onClick={() => { onSelectChat(c.id); setIsOpen(false); }} 
            className="flex-1 truncate text-left min-h-[44px] sm:min-h-[34px] flex items-center"
          >
            {c.title}
          </button>
        )}

        <div className="relative shrink-0">
          <button 
            aria-label="Menu Percakapan" 
            onClick={(e) => { e.stopPropagation(); setMenuOpenId(menuOpenId === c.id ? null : c.id); }} 
            className={`p-1 min-h-[44px] min-w-[44px] sm:min-h-[28px] sm:min-w-[28px] flex items-center justify-center rounded-md hover:bg-slate-200/80 dark:hover:bg-slate-700/80 text-slate-500 transition-opacity cursor-pointer ${
              menuOpenId === c.id ? 'opacity-100' : 'md:opacity-0 md:group-hover:opacity-100 opacity-100 focus-within:opacity-100'
            }`}
          >
            <MoreHorizontal className="w-4 h-4" />
          </button>

          <AnimatePresence>
            {menuOpenId === c.id && (
              <motion.div 
                initial={{ opacity: 0, scale: 0.95 }} 
                animate={{ opacity: 1, scale: 1 }} 
                exit={{ opacity: 0, scale: 0.95 }}
                transition={{ duration: 0.15 }}
                className="absolute right-0 top-full mt-1 w-36 bg-white dark:bg-slate-800 border border-slate-200/70 dark:border-slate-700 shadow-sm rounded-xl py-1 z-50 text-[13px] text-slate-700 dark:text-slate-200"
              >
                <button onClick={(e) => { e.stopPropagation(); setEditingId(c.id); setEditTitle(c.title); setMenuOpenId(null); }} className="w-full text-left px-3 py-2 min-h-[44px] sm:min-h-[32px] hover:bg-slate-50 dark:hover:bg-slate-700 flex items-center gap-2 cursor-pointer">
                  <Edit2 className="w-3.5 h-3.5 text-slate-400" /> Ubah Nama
                </button>
                <button onClick={(e) => { e.stopPropagation(); onTogglePin(c.id); setMenuOpenId(null); }} className="w-full text-left px-3 py-2 min-h-[44px] sm:min-h-[32px] hover:bg-slate-50 dark:hover:bg-slate-700 flex items-center gap-2 cursor-pointer">
                  <Pin className="w-3.5 h-3.5 text-slate-400" /> {c.isPinned ? 'Lepas Pin' : 'Sematkan Pin'}
                </button>
                <button onClick={(e) => { e.stopPropagation(); onToggleArchive(c.id); setMenuOpenId(null); }} className="w-full text-left px-3 py-2 min-h-[44px] sm:min-h-[32px] hover:bg-slate-50 dark:hover:bg-slate-700 flex items-center gap-2 cursor-pointer">
                  <Archive className="w-3.5 h-3.5 text-slate-400" /> {c.isArchived ? 'Buka Arsip' : 'Arsipkan'}
                </button>
                <button onClick={(e) => { e.stopPropagation(); onDeleteChat(c.id); setMenuOpenId(null); }} className="w-full text-left px-3 py-2 min-h-[44px] sm:min-h-[32px] hover:bg-rose-50 dark:hover:bg-rose-950/40 text-rose-600 dark:text-rose-400 flex items-center gap-2 cursor-pointer">
                  <Trash2 className="w-3.5 h-3.5" /> Hapus
                </button>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>
    );
  };

  const searchInputRef = React.useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleKeydown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
        e.preventDefault();
        setIsOpen(true);
        searchInputRef.current?.focus();
      } else if (e.key === 'Escape' && isOpen) {
        setIsOpen(false);
      }
    };
    window.addEventListener('keydown', handleKeydown);
    return () => window.removeEventListener('keydown', handleKeydown);
  }, [isOpen, setIsOpen]);

  // Lock body scroll on mobile when sidebar drawer is open
  useEffect(() => {
    if (isOpen && window.innerWidth < 1024) {
      const originalOverflow = document.body.style.overflow;
      document.body.style.overflow = 'hidden';
      return () => {
        document.body.style.overflow = originalOverflow;
      };
    }
  }, [isOpen]);

  return (
    <>
      {isOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/40 z-40 lg:hidden backdrop-blur-sm transition-opacity duration-200" 
          onClick={() => setIsOpen(false)} 
        />
      )}
      <aside className={`fixed lg:sticky lg:top-0 lg:h-[100dvh] inset-y-0 left-0 z-50 w-[min(82vw,260px)] lg:w-60 shrink-0 bg-stone-50 dark:bg-slate-900 border-r border-slate-200/70 dark:border-slate-800 flex flex-col transform transition-transform duration-200 ease-out ${isOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>

        {/* Top Header */}
        <div className="px-3.5 flex items-center justify-between border-b border-slate-200/70 dark:border-slate-800 h-[48px] shrink-0">
          <div className="flex items-center gap-2 min-w-0">
            <div className="w-[26px] h-[26px] rounded-md bg-white dark:bg-slate-800 border border-slate-200/70 dark:border-slate-700 shadow-xs flex items-center justify-center shrink-0 p-0.5">
              <img src="/favicon.svg" alt="RuangTenang Logo" className="w-full h-full object-contain" />
            </div>
            <span className="font-bold text-[14px] tracking-tight text-primary leading-none truncate">RuangTenang</span>
          </div>
          <button 
            onClick={() => setIsOpen(false)} 
            className="lg:hidden p-1 text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 rounded-lg cursor-pointer min-h-[44px] min-w-[44px] flex items-center justify-center" 
            aria-label="Tutup Sidebar"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* New Chat Primary CTA */}
        <div className="p-2.5 pb-1">
          <button 
            onClick={() => { onNewChat(); setIsOpen(false); }} 
            className="w-full flex items-center justify-center gap-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg py-2 sm:py-1.5 px-3 text-[12.5px] font-semibold transition-colors cursor-pointer min-h-[44px] sm:min-h-[38px] shadow-xs active:scale-[0.98]" 
            title="Chat Baru"
          >
            <Plus className="w-4 h-4" /> Chat Baru
          </button>
        </div>

        {/* Search */}
        <div className="px-2.5 pb-1.5">
          <div className="relative flex items-center">
            <Search className="w-3.5 h-3.5 absolute left-2.5 text-slate-400" />
            <input 
              ref={searchInputRef}
              value={search} onChange={e => setSearch(e.target.value)}
              placeholder="Cari percakapan" 
              className="w-full bg-white dark:bg-slate-800 border border-slate-200/70 dark:border-slate-700 rounded-lg pl-7.5 pr-7 py-1.5 sm:py-1 min-h-[44px] sm:min-h-[36px] text-[13px] sm:text-[12.5px] text-slate-800 dark:text-slate-100 placeholder:text-slate-400 focus:outline-none focus:border-teal-500/80 transition-colors"
            />
            <div className="absolute right-2 flex items-center pointer-events-none">
              <span className="hidden lg:inline text-[9px] font-medium text-slate-400 border border-slate-200 dark:border-slate-700 rounded px-1 py-0.2">Ctrl K</span>
            </div>
          </div>
        </div>

        {/* Toggle Archive */}
        <div className="px-3 py-1 flex items-center justify-between text-[11px] sm:text-[10.5px] text-secondary">
          <span className="font-medium uppercase tracking-wider">{showArchived ? 'Arsip Percakapan' : 'Riwayat'}</span>
          <button 
            onClick={() => setShowArchived(!showArchived)} 
            className="hover:text-teal-600 dark:hover:text-teal-400 font-semibold cursor-pointer min-h-[44px] sm:min-h-[24px] flex items-center"
          >
            {showArchived ? 'Lihat Aktif' : 'Arsip'}
          </button>
        </div>

        {/* History List */}
        <div className="flex-1 overflow-y-auto px-1.5 space-y-1 py-0.5 custom-scrollbar" onClick={() => setMenuOpenId(null)}>
          {isLoading ? (
            <div className="space-y-1.5 px-2 pt-1.5">
              {[1, 2, 3].map(i => (
                <div key={i} className="animate-pulse space-y-1">
                  <div className="h-2 w-10 bg-slate-200 dark:bg-slate-800 rounded"></div>
                  <div className="h-8 bg-slate-200/70 dark:bg-slate-800/70 rounded-lg"></div>
                </div>
              ))}
            </div>
          ) : pinnedChats.length === 0 && Object.values(groups).every(g => g.length === 0) ? (
            <div className="text-center text-muted mt-4 text-[11.5px] px-3">
              {search ? 'Tidak ada percakapan.' : (showArchived ? 'Belum ada arsip.' : 'Belum ada percakapan.')}
            </div>
          ) : (
            <>
              {pinnedChats.length > 0 && (
                <div>
                  <div className="px-2 mb-0.5 mt-0.5 text-[9.5px] font-bold text-muted uppercase tracking-wider flex items-center gap-1">Pinned</div>
                  <div className="space-y-0.5">{pinnedChats.map(renderChatItem)}</div>
