                  {/* Virtual Meeting Link */}
                  {apt.mode === 'video_call' && apt.status !== 'Selesai' && (
                    <div className="flex items-center justify-between pt-2.5 border-t border-slate-200 dark:border-slate-700">
                      <span className="text-secondary font-medium">Link Pertemuan:</span>
                      {apt.meetingLink ? (
                        <a
                          href={apt.meetingLink}
                          target="_blank"
                          rel="noreferrer"
                          className="text-teal-600 dark:text-teal-400 hover:underline font-mono font-medium flex items-center gap-1.5"
                        >
                          <Video className="w-3.5 h-3.5" />
                          <span>Buka Link Sesi</span>
                        </a>
                      ) : (
                        <span className="text-xs text-secondary italic">
                          Belum tersedia (menunggu konfirmasi konselor)
                        </span>
                      )}
                    </div>
                  )}

                  <div className="flex items-center justify-between text-primary">
                    <span className="flex items-center gap-2 text-secondary">
                      <Bell className="w-4 h-4 text-secondary" /> Pengingat:
                    </span>
                    <span className="text-secondary">{apt.reminderMinutesBefore} Menit Sebelum Sesi</span>
                  </div>
                </div>

                {/* Calendar Export & Action Buttons */}
                <div className="flex flex-wrap items-center gap-2.5 pt-2">
                  {apt.status !== 'Selesai' && (
                    <>
                      <button
                        onClick={() => setSelectedCalendarApt(apt)}
                        className="flex-1 py-2.5 min-h-[44px] bg-slate-800 dark:bg-white hover:bg-slate-900 dark:hover:bg-slate-100 text-white dark:text-slate-900 rounded-xl text-xs sm:text-sm font-medium transition-all flex items-center justify-center gap-2 shadow-xs cursor-pointer"
                      >
                        <Bell className="w-4 h-4 text-amber-400 dark:text-amber-600" />
                        <span>Pengingat & Kalender</span>
                      </button>

                      <a
                        href={generateGoogleCalendarUrl(apt)}
                        target="_blank"
                        rel="noreferrer"
                        className="py-2.5 px-3 min-h-[44px] surface-card hover:bg-slate-100 dark:hover:bg-slate-800 text-primary border border-default rounded-xl text-xs sm:text-sm font-medium transition-all flex items-center justify-center gap-1.5"
                        title="Buka di Google Calendar"
                      >
                        <ExternalLink className="w-4 h-4" />
                        <span className="hidden sm:inline">Google Cal</span>
                      </a>

                      {/* Reschedule Button */}
                      {apt.status !== 'Dibatalkan' && (
                        <button
                          onClick={() => setRescheduleApt(apt)}
                          className="px-3.5 py-2.5 min-h-[44px] bg-amber-50 dark:bg-amber-950/40 hover:bg-[#FEF5D9] text-amber-700 dark:text-amber-400 border border-amber-200 dark:border-amber-900/50 rounded-xl text-xs sm:text-sm font-medium transition-all cursor-pointer"
                        >
                          Reschedule
                        </button>
                      )}

                      <button
                        onClick={() => downloadIcsFile(apt)}
                        className="p-2.5 min-h-[44px] min-w-[44px] flex items-center justify-center bg-transparent hover:bg-slate-100 dark:hover:bg-slate-800 text-secondary border border-default rounded-xl transition-all cursor-pointer"
                        title="Unduh File Kalender (.ics)"
                      >
                        <Download className="w-4 h-4" />
                      </button>

                      {apt.status !== 'Dibatalkan' && (
                        <button
                          onClick={() => handleCancelAppointment(apt.id)}
                          className="p-2.5 min-h-[44px] min-w-[44px] flex items-center justify-center bg-transparent hover:bg-rose-50 dark:hover:bg-rose-950/40 text-secondary hover:text-rose-500 border border-default hover:border-rose-200 dark:hover:border-rose-900/50 rounded-xl transition-all cursor-pointer"
                          title="Batalkan Sesi Konseling"
                        >
                          <XCircle className="w-4 h-4" />
                        </button>
                      )}
                    </>
                  )}
                </div>

                {/* Chat Simulation Actions */}
                {apt.status !== 'Dibatalkan' && (
                  <div className="pt-2.5 border-t border-slate-100 w-full flex flex-col gap-2">
                    {apt.status === 'Selesai' ? (
                      <button
                        onClick={() => setActiveSummaryApt(apt)}
                        className="w-full py-2.5 bg-slate-800 hover:bg-slate-900 text-white rounded-lg text-sm font-medium flex items-center justify-center gap-2 transition-all shadow-sm cursor-pointer"
                      >
                        <FileText className="w-4 h-4" />
                        <span>Lihat Ringkasan Hasil Konseling</span>
                      </button>
                    ) : (
                      <>
                        <button
                          onClick={() => setActiveChatApt(apt)}
                          className="w-full py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-sm font-medium flex items-center justify-center gap-2 transition-all shadow-sm cursor-pointer"
                        >
                          <MessageSquare className="w-4 h-4" />
                          <span>Mulai Sesi Chat Teks (Simulasi)</span>
                        </button>

                        {apt.mode === 'video_call' && (
                          <button
                            onClick={() => setActiveVideoApt(apt)}
                            className="w-full py-2.5 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-medium flex items-center justify-center gap-2 transition-all shadow-sm cursor-pointer"
                          >
                            <Video className="w-4 h-4" />
                            <span>Mulai Tele-Konseling Video</span>
                          </button>
                        )}
                      </>
                    )}
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      {/* BOOKING FORM MODAL */}
      <BookingForm
        isOpen={isBookingOpen}
        onClose={() => setIsBookingOpen(false)}
        selectedCounselorFromDir={selectedCounselorFromDir}
        userSession={userSession}
        setUserSession={setUserSession}
        appointments={appointments}
        onAddAppointment={handleAddAppointment}
        showToast={showToast}
        onShowLimitModal={() => setShowLimitModal(true)}
      />

      {/* RESCHEDULE MODAL */}
      <RescheduleModal
        appointment={rescheduleApt}
        onClose={() => setRescheduleApt(null)}
        onReschedule={handleReschedule}
      />

      {/* SIMULATED COUNSELOR CHAT MODAL */}
      <CounselorChatSimulation
        appointment={activeChatApt}
        onClose={() => setActiveChatApt(null)}
        onCompleteSession={handleCompleteSession}
        showToast={showToast}
      />

      {/* VIDEO CONSULTATION ROOM MODAL */}
      <VideoConsultationRoom
        appointment={activeVideoApt}
        onClose={() => setActiveVideoApt(null)}
        onEndCall={handleCompleteSession}
        userRole={userSession.role as any}
      />

      {/* SUMMARY / DETAIL APPOINTMENT MODAL (PROGRESSIVE DISCLOSURE) */}
      <AppointmentDetailsModal
        appointment={activeSummaryApt}
        onClose={() => setActiveSummaryApt(null)}
      />

      {/* CALENDAR & REMINDER INTEGRATION MODAL */}
      <CalendarReminderModal
        isOpen={!!selectedCalendarApt}
        onClose={() => setSelectedCalendarApt(null)}
        appointment={selectedCalendarApt}
        onShowToast={showToast}
      />

      {/* CONFIRMATION CANCEL MODAL */}
      {cancelModalAptId && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
          <div className="bg-white rounded-xl shadow-xl border border-slate-200 w-full max-w-md p-6 space-y-4">
            <div className="flex items-start gap-3">
              <div className="p-3 bg-rose-50 text-rose-600 rounded-lg shrink-0">
                <AlertTriangle className="w-6 h-6" />
              </div>
              <div>
                <h3 className="font-sans font-semibold tracking-tight text-lg text-slate-900">Batalkan Sesi Konseling?</h3>
                <p className="text-sm text-slate-600 mt-1 leading-relaxed">
                  Apakah Anda yakin ingin membatalkan jadwal konseling ini? Status ketersediaan konselor akan otomatis diperbarui dan tindakan ini tidak dapat dibatalkan.
                </p>
              </div>
            </div>
            <div className="flex gap-3 justify-end pt-2">
              <button
                onClick={() => setCancelModalAptId(null)}
                className="px-4 py-2 text-sm font-medium text-slate-700 bg-slate-100 hover:bg-slate-200 rounded-lg transition-colors cursor-pointer"
              >
                Kembali
              </button>
              <button
                onClick={() => confirmCancelAppointment(cancelModalAptId)}
                className="px-4 py-2 text-sm font-medium text-white bg-rose-600 hover:bg-rose-700 rounded-lg transition-colors shadow-sm cursor-pointer"
              >
                Ya, Batalkan Sesi
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Limit Modal */}
      {showLimitModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
          <div className="bg-slate-50 rounded-xl shadow-lg border border-slate-200 w-full max-w-sm overflow-hidden p-6 text-center space-y-4">
            <div className="w-12 h-12 bg-amber-100 text-amber-600 rounded-lg flex items-center justify-center mx-auto">
              <User className="w-6 h-6" />
            </div>
            <div>
              <h3 className="font-sans font-semibold tracking-tight text-lg font-medium text-slate-800">Batas Jadwal Tercapai</h3>
              <p className="text-sm text-slate-600 mt-2">
                Anda telah menggunakan seluruh kuota pemesanan jadwal untuk tier Free. Tingkatkan ke tier Plus atau Pro untuk melanjutkan. (Fitur Upgrade Coming Soon)
              </p>
            </div>
            <button
              onClick={() => setShowLimitModal(false)}
              className="w-full py-2.5 bg-slate-800 text-white hover:bg-slate-900 rounded-lg text-sm font-medium transition cursor-pointer"
            >
              Tutup
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

import { useEscapeKey } from "../../hooks/useEscapeKey";
import React, { useState, useEffect } from "react";
import {
  XCircle,
  Clock,
  CheckCircle2,
  ChevronRight,
  ChevronLeft,
  Lock,
  Calendar,
  User,
  BookOpen,
  HeartHandshake,
} from "lucide-react";
import { Counselor, UserSession, Appointment, TIER_LIMITS } from "../../types";
import { useCounselors } from "../../hooks/useCounselors";
import { apiClient } from "../../lib/apiClient";
import { addNotification } from "../../lib/notificationStore";

interface BookingFormProps {
  isOpen: boolean;
  onClose: () => void;
  selectedCounselorFromDir: Counselor | null;
  userSession: UserSession;
  setUserSession: React.Dispatch<React.SetStateAction<UserSession>>;
  appointments: Appointment[];
  onAddAppointment: (newApt: Appointment) => void;
  showToast: (
    message: string,
    type: "success" | "error" | "warning" | "info",
  ) => void;
  onShowLimitModal: () => void;
}

const KEBUTUHAN_OPTIONS = [
  {
    id: "akademik",
    title: "Kendala Akademik & Skripsi",
    desc: "Stres revisi, dosen pembimbing, atau beban perkuliahan.",
  },
  {
    id: "kecemasan",
    title: "Kecemasan & Burnout",
    desc: "Gelisah berlebihan, panik, rasa lelah fisik & emosional.",
  },
  {
    id: "hubungan",
    title: "Hubungan & Sosial Kampus",
    desc: "Masalah pertemanan, organisasi, pasangan, atau keluarga.",
  },
  {
    id: "depresi",
    title: "Suasana Hati & Depresi",
    desc: "Perasaan hampa, kehilangan motivasi, atau sedih berkepanjangan.",
  },
  {
    id: "karir",
    title: "Karir & Masa Depan",
    desc: "Kebingungan arah karir, magang, atau tekanan masa depan.",
  },
];

export const BookingForm: React.FC<BookingFormProps> = ({
  isOpen,
  onClose,
  selectedCounselorFromDir,
  userSession,
  setUserSession,
  appointments,
  onAddAppointment,
  showToast,
  onShowLimitModal,
}) => {
  useEscapeKey(onClose, true);

  const { counselors, loading } = useCounselors();

  const [currentStep, setCurrentStep] = useState<number>(1);
  const [selectedConcern, setSelectedConcern] = useState<string>(
    "Kendala Akademik & Skripsi",
  );
  const [selectedCounselorId, setSelectedCounselorId] = useState<string>(
    selectedCounselorFromDir?.id || ""
  );
  const [studentName, setStudentName] = useState(userSession.name || "");
  const [studentNIM, setStudentNIM] = useState("");
  const [studentEmail, setStudentEmail] = useState(userSession.email || "");
  const [studentPhone, setStudentPhone] = useState("");
  const getLocalTimezone = (): "WIB" | "WITA" | "WIT" => {
    try {
      const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
      if (tz === "Asia/Makassar" || tz === "Asia/Kuala_Lumpur" || tz === "Asia/Singapore" || tz === "Asia/Brunei" || tz === "Asia/Kuching") return "WITA";
      if (tz === "Asia/Jayapura" || tz === "Asia/Dili") return "WIT";
      return "WIB";
    } catch {
      return "WIB";
    }
  };

  const getInitialBookingDate = () => {
    const d = new Date();
    d.setDate(d.getDate() + 1);
    return d.toISOString().split("T")[0];
  };

  const [date, setDate] = useState<string>(getInitialBookingDate);
  const [timeSlot, setTimeSlot] = useState("");
  const [timezone, setTimezone] = useState<"WIB" | "WITA" | "WIT">(getLocalTimezone());
  const [mode, setMode] = useState<"video_call">("video_call");
  const [reminderMinutes, setReminderMinutes] = useState<number>(30);
  const [formError, setFormError] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [availableSlots, setAvailableSlots] = useState<string[]>([]);
  const [isFullyBooked, setIsFullyBooked] = useState(false);
  const [isLoadingSlots, setIsLoadingSlots] = useState(false);

  useEffect(() => {
    if (selectedCounselorFromDir) {
      setSelectedCounselorId(selectedCounselorFromDir.id);
      setCurrentStep(1);
    }
  }, [selectedCounselorFromDir]);

  useEffect(() => {
    if (!selectedCounselorId || !date) return;
    let isMounted = true;
    setIsLoadingSlots(true);
    apiClient.get<{ availableSlots: string[]; fullyBooked?: boolean }>(
      `/api/v1/appointments/availability?counselorId=${selectedCounselorId}&date=${date}`,
    )
      .then((res) => {
        if (!isMounted) return;
        setIsLoadingSlots(false);
        const data = res.data;
        if (data && Array.isArray(data.availableSlots)) {
          setAvailableSlots(data.availableSlots);
          setIsFullyBooked(
            data.fullyBooked || data.availableSlots.length === 0,
          );
          if (data.availableSlots.length > 0) {
            if (!data.availableSlots.includes(timeSlot)) {
              setTimeSlot(data.availableSlots[0]);
            }
          } else {
            setTimeSlot("");
          }
        }
      })
      .catch((err) => {
        if (!isMounted) return;
        setIsLoadingSlots(false);
        setAvailableSlots([]);
        console.warn("Failed to check server availability:", err);
      });

    return () => {
      isMounted = false;
    };
  }, [selectedCounselorId, date]);

  const handleNextStep = () => {
    setFormError(null);
    if (currentStep === 1) {
      if (!selectedCounselorId) return setFormError("Pilih konselor terlebih dahulu untuk melanjutkan.");
    } else if (currentStep === 2) {
      if (!date || !timeSlot) return setFormError("Pilih tanggal dan waktu sesi.");
    } else if (currentStep === 3) {
      if (!studentName.trim() || !studentNIM.trim() || !studentEmail.trim()) {
        return setFormError("Mohon lengkapi Nama, NIM, dan Email Anda.");
      }
    }
    setCurrentStep((prev) => Math.min(prev + 1, 4));
  };

  const handlePrevStep = () => {
    setFormError(null);
    setCurrentStep((prev) => Math.max(prev - 1, 1));
  };

  const handleCreateAppointment = async (e: React.FormEvent) => {
    e.preventDefault();
    setFormError(null);

    const currentLimit = TIER_LIMITS[userSession.tier].appointments;
    if (userSession.usageStats.appointmentsBooked >= currentLimit) {
      onClose();
      onShowLimitModal();
      return;
    }

    if (!studentName.trim() || studentName.trim().length < 2) {
      setFormError("Nama mahasiswa wajib diisi (minimal 2 karakter).");
      return;
    }

    if (studentNIM && !/^\d{6,15}$/.test(studentNIM.trim())) {
      setFormError("NIM harus berupa angka (6 hingga 15 digit).");
      return;
    }

    if (
      studentEmail &&
      !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(studentEmail.trim())
    ) {
      setFormError(
        "Format email kampus tidak valid (contoh: mahasiswa@ui.ac.id).",
      );
      return;
    }

    const counselorObj = counselors.find((c) => c.id === selectedCounselorId);
    if (!counselorObj) {
      setFormError("Pilih konselor yang valid.");
      return;
    }

    setIsSubmitting(true);
    const fullTimeSlot = `${timeSlot} ${timezone}`;

    try {
      const res = await apiClient.post<any>("/api/v1/appointments", {
        counselorId: counselorObj.id,
        counselorName: counselorObj.name,
        date,
        time: timeSlot,
        timezone,
        mode,
        notes: selectedConcern,
        userId: studentNIM || "mahasiswa-anon",
        studentName: studentName.trim(),
        studentNIM: studentNIM.trim(),
        studentEmail: studentEmail.trim(),
      });

      if (!res.success) {
        if (res.status === 409) {
          setFormError(
            res.error ||
              "🚫 Jadwal bentrok! Slot tersebut telah dipesan oleh mahasiswa lain.",
          );
        } else {
          setFormError(
            res.error ||
              "Gagal menyimpan jadwal ke server. Silakan coba lagi.",
          );
        }
        setIsSubmitting(false);
        return;
      }

      const resData = res.data;
      const record = resData?.record || resData;
      const createdAppointment: Appointment = {
        id: record.id,
        counselorId: counselorObj.id,
        counselorName: counselorObj.name,
        counselorTitle: counselorObj.title,
        counselorAvatar: counselorObj.avatar,
        studentName: record.studentName || studentName.trim(),
        studentNIM: record.studentNIM || studentNIM.trim(),
        studentEmail: record.studentEmail || studentEmail.trim(),
        studentPhone: studentPhone.trim() || undefined,
        date: record.date,
        timeSlot: `${record.time} ${record.timezone || timezone}`,
        timezone: record.timezone || timezone,
        mode: record.mode || mode,
        primaryConcern: record.notes || selectedConcern,
        status:
          record.status === "PENDING" ? "Menunggu Konfirmasi" : "Konfirmasi",
        approvalStatus: record.approvalStatus || "PENDING_APPROVAL",
        attendanceStatus: record.attendanceStatus || "SCHEDULED",
        meetingLink: record.meetingLink || undefined,
        reminderEnabled: true,
        reminderMinutesBefore: reminderMinutes,
        createdAt: record.createdAt || new Date().toISOString(),
      };

      onAddAppointment(createdAppointment);
      addNotification(
        "Sesi Konseling Dijadwalkan 🗓️",
        `Pertemuan dengan ${counselorObj.name} telah berhasil dijadwalkan pada ${date} pukul ${fullTimeSlot}.`,
        "warning"
      );
      onClose();
      setFormError(null);
      showToast(
        `Jadwal Konseling Terdaftar untuk ${date} Pukul ${fullTimeSlot}.`,
        "success",
      );
    } catch (e) {
      console.warn("Backend appointment save failed:", e);
      setFormError("Terjadi kesalahan jaringan saat menyimpan jadwal.");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (!isOpen) return null;

  const currentCounselor = counselors.find((c) => c.id === selectedCounselorId);

  return (
    <div className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-xs flex items-center justify-center max-sm:items-end p-3 sm:p-4 max-sm:p-0 font-sans animate-fade-in">
      <div className="surface-card text-primary border border-default rounded-2xl max-sm:rounded-b-none max-sm:rounded-t-2xl max-w-lg w-full p-4 sm:p-6 shadow-xl relative max-h-[92dvh] overflow-y-auto flex flex-col justify-between max-sm:animate-slide-up transition-transform duration-200">
        {/* Drag handle for mobile bottom sheet */}
        <div className="w-10 h-1 bg-slate-300 dark:bg-slate-700 rounded-full mx-auto my-2 sm:hidden shrink-0" />

        {/* Header & Stepper */}
        <div>
          <div className="flex items-center justify-between pb-3.5 border-b border-default mb-4">
            <div>
              <p className="text-[10.5px] font-semibold text-secondary uppercase tracking-wider mb-0.5">
                Langkah {currentStep} dari 4
              </p>
              <h2 className="text-lg sm:text-xl font-bold text-primary">
                {currentStep === 1 && "Pilih Konselor"}
                {currentStep === 2 && "Pilih Jadwal Sesi"}
                {currentStep === 3 && "Informasi Pribadi"}
                {currentStep === 4 && "Konfirmasi"}
              </h2>
            </div>
            <button
              onClick={onClose}
              className="p-1.5 text-secondary hover:text-primary hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors cursor-pointer min-h-[40px] min-w-[40px] flex items-center justify-center"
              aria-label="Tutup Form"
            >
              <XCircle className="w-5 h-5" />
            </button>
          </div>

          {/* Mobile Stepper Indicator: Langkah X dari 4 + Progress Bar */}
          <div className="sm:hidden mb-4 space-y-1.5">
            <div className="flex items-center justify-between text-xs">
              <span className="font-semibold text-teal-700 dark:text-teal-400">
                Langkah {currentStep} dari 4: {
                  currentStep === 1 ? "Pilih Konselor" :
                  currentStep === 2 ? "Pilih Jadwal" :
                  currentStep === 3 ? "Data Diri" : "Konfirmasi"
                }
              </span>
              <span className="text-secondary font-medium">
                {Math.round((currentStep / 4) * 100)}%
              </span>
            </div>
            <div className="h-1.5 w-full surface-muted rounded-full overflow-hidden border border-default">
              <div
                className="h-full bg-teal-600 dark:bg-teal-500 rounded-full transition-all duration-200"
                style={{ width: `${(currentStep / 4) * 100}%` }}
              />
            </div>
          </div>

          {/* Desktop Visual Stepper Indicators */}
          <div className="hidden sm:grid sm:grid-cols-4 gap-2 mb-6 relative">
            {[
              { label: "Konselor", step: 1 },
              { label: "Jadwal", step: 2 },
              { label: "Data Diri", step: 3 },
              { label: "Konfirmasi", step: 4 },
            ].map((s) => {
              const isCompleted = currentStep > s.step;
              const isActive = currentStep === s.step;
              return (
                <div key={s.step} className="flex flex-col items-center text-center relative z-10">
                  <div
                    className={`w-6 h-6 rounded-full flex items-center justify-center font-bold text-xs border transition-all duration-200 ${
                      isCompleted
                        ? "bg-teal-600 border-teal-600 text-white"
                        : isActive
                        ? "surface-card border-teal-600 text-teal-700 dark:text-teal-400 ring-3 ring-teal-500/20 font-bold"
                        : "surface-muted border-default text-secondary"
                    }`}
                  >
                    {isCompleted ? "✓" : s.step}
                  </div>
                  <span
                    className={`text-[10px] mt-1 font-semibold uppercase tracking-wider transition-colors duration-200 select-none ${
                      isActive
                        ? "text-teal-700 dark:text-teal-400 font-bold"
                        : isCompleted
                        ? "text-primary"
                        : "text-secondary"
                    }`}
                  >
                    {s.label}
                  </span>
                </div>
              );
            })}

            {/* Connecting line */}
            <div className="absolute top-3 left-[12.5%] right-[12.5%] h-0.5 bg-slate-200 dark:bg-slate-800 -z-0">
              <div
                className="bg-teal-600 dark:bg-teal-500 h-full transition-all duration-300 ease-out"
                style={{ width: `${((currentStep - 1) / 3) * 100}%` }}
              />
            </div>
          </div>

          {formError && (
            <div className="p-3 bg-rose-50 dark:bg-rose-950/30 border border-rose-200 dark:border-rose-900/50 rounded-xl text-rose-700 dark:text-rose-300 text-xs font-medium flex items-center gap-2.5 mb-4">
              <XCircle className="w-4 h-4 shrink-0" />
              <span>{formError}</span>
            </div>
          )}

          {/* STEP 1: PILIH KONSELOR */}
          {currentStep === 1 && (
            <div className="space-y-3 animate-in fade-in duration-200">
              <p className="text-xs text-secondary">
                Pilih psikolog atau konselor kampus yang ingin Anda temui:
              </p>
              <div className="space-y-2.5 max-h-[360px] overflow-y-auto pr-1">
                {loading ? (
                  <div className="text-center text-secondary py-8 text-xs">Memuat daftar konselor...</div>
                ) : (
                  counselors.map((c) => {
                    const isSelected = selectedCounselorId === c.id;
                    return (
                      <button
                        key={c.id}
                        type="button"
                        onClick={() => setSelectedCounselorId(c.id)}
                        className={`w-full text-left p-3 sm:p-3.5 rounded-xl border transition-all cursor-pointer flex items-center gap-3 ${
                          isSelected
                            ? "surface-muted border-teal-600/50 ring-1 ring-teal-600/50"
                            : "surface-card border-default hover:bg-slate-50 dark:hover:bg-slate-800/60"
                        }`}
                      >
                        <img
                          src={c.avatar}
                          alt={c.name}
                          className="w-10 h-10 sm:w-11 sm:h-11 rounded-xl object-cover border border-default shrink-0"
                        />
                        <div className="flex-1 min-w-0">
                          <p
                            className={`text-sm font-semibold truncate ${isSelected ? "text-teal-700 dark:text-teal-400" : "text-primary"}`}
                          >
                            {c.name}
                          </p>
                          <p className="text-xs text-secondary truncate mt-0.5">
                            {c.title} &bull; {c.university}
                          </p>
                        </div>
                        <div
                          className={`w-4.5 h-4.5 rounded-full border flex items-center justify-center shrink-0 transition-colors ${
                            isSelected
                              ? "bg-teal-600 border-teal-600 text-white"
                              : "border-default"
                          }`}
                        >
                          {isSelected && <CheckCircle2 className="w-3 h-3" />}
                        </div>
                      </button>
                    );
                  })
                )}
              </div>
            </div>
          )}

          {/* STEP 2: PILIH JADWAL & METODE */}
          {currentStep === 2 && (
            <div className="space-y-4 animate-in fade-in duration-200">
              {currentCounselor ? (
                <div className="p-3.5 surface-muted border border-default rounded-xl flex items-center gap-3">
                  <img
                    src={currentCounselor.avatar}
                    alt={currentCounselor.name}
                    className="w-10 h-10 rounded-xl object-cover shrink-0 border border-default"
                  />
                  <div>
                    <p className="text-xs sm:text-sm font-semibold text-primary">
                      Sesi dengan {currentCounselor.name}
                    </p>
                    <p className="text-[11px] text-secondary mt-0.5">
                      {selectedConcern}
                    </p>
                  </div>
                </div>
              ) : (
                <div className="p-3 bg-amber-50 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-900/50 rounded-xl text-amber-800 dark:text-amber-300 text-xs">
                  Pilih konselor terlebih dahulu di Langkah 1.
                </div>
              )}

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div className="space-y-1">
                  <label
                    htmlFor="session-date-input"
                    className="block text-xs font-semibold text-secondary"
                  >
                    Tanggal Sesi
                  </label>
                  <input
                    id="session-date-input"
                    type="date"
                    required
                    min={new Date().toISOString().split("T")[0]}
                    value={date}
                    onChange={(e) => setDate(e.target.value)}
                    className="w-full surface-muted border border-default rounded-xl px-3.5 py-2 text-base sm:text-sm text-primary focus:outline-none focus:border-teal-600 focus:ring-1 focus:ring-teal-600 transition-all min-h-[44px]"
                  />
                </div>

                <div className="space-y-1">
                  <label
                    htmlFor="session-time-input"
                    className="block text-xs font-semibold text-secondary"
                  >
                    Waktu Sesi
                  </label>
                  <select
                    id="session-time-input"
                    value={timeSlot}
                    onChange={(e) => setTimeSlot(e.target.value)}
                    disabled={isFullyBooked || availableSlots.length === 0}
                    className="w-full surface-muted border border-default rounded-xl px-3.5 py-2 text-base sm:text-sm text-primary focus:outline-none focus:border-teal-600 focus:ring-1 focus:ring-teal-600 transition-all disabled:opacity-50 min-h-[44px]"
                  >
                    {availableSlots.length > 0 ? (
                      availableSlots.map((slot) => (
                        <option key={slot} value={slot}>
                          {slot}
                        </option>
                      ))
                    ) : (
                      <option value="">Penuh / Tidak Tersedia</option>
                    )}
                  </select>
                </div>
              </div>

              <div className="space-y-1">
                <label
                  htmlFor="session-timezone"
                  className="block text-xs font-semibold text-secondary"
                >
                  Zona Waktu
                </label>
                <select
                  id="session-timezone"
                  value={timezone}
                  onChange={(e) => setTimezone(e.target.value as any)}
                  className="w-full surface-muted border border-default rounded-xl px-3.5 py-2 text-base sm:text-sm text-primary focus:outline-none focus:border-teal-600 focus:ring-1 focus:ring-teal-600 transition-all min-h-[44px]"
                >
                  <option value="WIB">WIB (Jakarta / Jawa / Sumatra)</option>
                  <option value="WITA">WITA (Bali / Sulawesi / Kaltim)</option>
                  <option value="WIT">WIT (Maluku / Papua)</option>
                </select>
              </div>

              <div className="pt-1">
                <div className="p-3 bg-teal-50/60 dark:bg-teal-950/30 border border-teal-200 dark:border-teal-900/40 rounded-xl flex items-start gap-2.5">
                  <div className="mt-0.5 text-teal-600 dark:text-teal-400">
                    <Lock className="w-4 h-4" />
                  </div>
                  <div>
                    <p className="text-xs font-semibold text-teal-900 dark:text-teal-200">Sesi Virtual Video Call</p>
                    <p className="text-[11px] text-teal-700 dark:text-teal-400 mt-0.5">
                      Tautan aman sesi tele-konseling akan diberikan setelah terkonfirmasi.
                    </p>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* STEP 3: DATA DIRI */}
          {currentStep === 3 && (
            <div className="space-y-3.5 animate-in fade-in duration-200">
              <div className="space-y-3">
                <div className="space-y-1">
                  <label className="block text-xs font-semibold text-secondary">Nama Lengkap</label>
                  <input type="text" value={studentName} onChange={(e) => setStudentName(e.target.value)} placeholder="Sesuai kartu identitas" className="w-full surface-muted border border-default rounded-xl px-3.5 py-2 text-base sm:text-sm text-primary focus:outline-none focus:border-teal-600 focus:ring-1 focus:ring-teal-600 transition-all min-h-[44px]" />
                </div>
                <div className="space-y-1">
                  <label className="block text-xs font-semibold text-secondary">NIM / Nomor Induk</label>
                  <input type="text" value={studentNIM} onChange={(e) => setStudentNIM(e.target.value)} placeholder="Cth: 12345678" className="w-full surface-muted border border-default rounded-xl px-3.5 py-2 text-base sm:text-sm text-primary focus:outline-none focus:border-teal-600 focus:ring-1 focus:ring-teal-600 transition-all min-h-[44px]" />
                </div>
                <div className="space-y-1">
                  <label className="block text-xs font-semibold text-secondary">Email Utama</label>
                  <input type="email" value={studentEmail} onChange={(e) => setStudentEmail(e.target.value)} placeholder="email@contoh.com" className="w-full surface-muted border border-default rounded-xl px-3.5 py-2 text-base sm:text-sm text-primary focus:outline-none focus:border-teal-600 focus:ring-1 focus:ring-teal-600 transition-all min-h-[44px]" />
                </div>
                <div className="space-y-1">
                  <label className="block text-xs font-semibold text-secondary">
                    Nomor WhatsApp / Telepon <span className="text-[10px] text-secondary font-normal">(Opsional)</span>
                  </label>
                  <input type="tel" value={studentPhone} onChange={(e) => setStudentPhone(e.target.value)} placeholder="0812... (opsional)" className="w-full surface-muted border border-default rounded-xl px-3.5 py-2 text-base sm:text-sm text-primary focus:outline-none focus:border-teal-600 focus:ring-1 focus:ring-teal-600 transition-all min-h-[44px]" />
                </div>
              </div>
            </div>
          )}

          {/* STEP 4: KONFIRMASI RINGKASAN */}
          {currentStep === 4 && (
            <div className="space-y-4 animate-in fade-in duration-200">
              <div className="surface-muted border border-default rounded-xl p-4 space-y-3">
                <div className="space-y-0.5">
                  <p className="text-[11px] font-semibold text-secondary">Konselor</p>
                  <p className="text-xs sm:text-sm font-bold text-primary">{counselors.find(c => c.id === selectedCounselorId)?.name || "-"}</p>
                </div>
                <div className="space-y-0.5">
                  <p className="text-[11px] font-semibold text-secondary">Jadwal Sesi</p>
                  <p className="text-xs sm:text-sm font-bold text-primary">
                    {date ? new Date(date).toLocaleDateString("id-ID", { weekday: "long", day: "numeric", month: "long", year: "numeric" }) : "-"} — {timeSlot} {timezone}
                  </p>
                </div>
                <div className="space-y-0.5">
                  <p className="text-[11px] font-semibold text-secondary">Data Pemesan</p>
                  <p className="text-xs sm:text-sm font-bold text-primary">{studentName}</p>
                  <p className="text-[11px] text-secondary mt-0.5">{studentEmail} {studentPhone ? `• ${studentPhone}` : ''}</p>
                </div>
              </div>

              <div className="p-3 surface-card border border-default rounded-xl">
                <p className="text-[11px] text-secondary leading-relaxed">
                  Dengan mengonfirmasi jadwal ini, Anda menyetujui bahwa pembatalan atau perubahan jadwal wajib dilakukan maksimal 24 jam sebelum sesi dimulai.
                </p>
              </div>
            </div>
          )}
        </div>

        {/* Sticky Footer Navigation Buttons */}
        <div className="sticky bottom-0 surface-card border-t border-default pt-3 pb-[max(env(safe-area-inset-bottom),_0.75rem)] mt-5 -mx-4 sm:-mx-6 px-4 sm:px-6 flex items-center justify-between gap-2.5 z-10">
          {currentStep > 1 ? (
            <button
              type="button"
              onClick={handlePrevStep}
              className="px-4 py-2 min-h-[44px] surface-card border border-default hover:bg-slate-100 dark:hover:bg-slate-800 text-secondary text-xs sm:text-sm font-semibold rounded-xl transition-colors flex items-center gap-1.5 cursor-pointer active:scale-[0.98]"
            >
              <ChevronLeft className="w-4 h-4" />
              <span>Kembali</span>
            </button>
          ) : (
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 min-h-[44px] text-secondary hover:text-primary text-xs sm:text-sm font-semibold rounded-xl transition-colors cursor-pointer active:scale-[0.98]"
            >
              Batal
            </button>
          )}

          {currentStep < 4 ? (
            <button
              type="button"
              onClick={handleNextStep}
              className="px-5 py-2 min-h-[44px] bg-slate-800 dark:bg-white hover:bg-slate-900 dark:hover:bg-slate-100 text-white dark:text-slate-900 text-xs sm:text-sm font-semibold rounded-xl shadow-3xs transition-all flex items-center gap-1.5 cursor-pointer ml-auto active:scale-[0.98]"
            >
              <span>Lanjut</span>
              <ChevronRight className="w-4 h-4" />
            </button>
          ) : (
            <button
              type="button"
              onClick={handleCreateAppointment}
              disabled={isSubmitting}
              className="px-5 py-2 min-h-[44px] bg-teal-600 hover:bg-teal-700 text-white text-xs sm:text-sm font-semibold rounded-xl shadow-3xs transition-all disabled:opacity-50 cursor-pointer ml-auto active:scale-[0.98] flex items-center gap-1.5"
            >
              {isSubmitting ? "Memproses..." : "Konfirmasi Sesi"}
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

import { useEscapeKey } from '../../hooks/useEscapeKey';
import React, { useState, useEffect } from 'react';
import { Send, Bot, AlertCircle, XCircle, Check } from 'lucide-react';
import { Appointment } from '../../types';
import { useCounselors } from '../../hooks/useCounselors';
import { apiClient } from '../../lib/apiClient';

interface CounselorChatSimulationProps {
  appointment: Appointment | null;
  onClose: () => void;
  onCompleteSession: (appointmentId: string, summaryNotes: string) => void;
  showToast: (message: string, type: 'success' | 'error' | 'warning' | 'info') => void;
}

export const CounselorChatSimulation: React.FC<CounselorChatSimulationProps> = ({
  appointment,
  onClose,
  onCompleteSession,
  showToast
}) => {
  const { counselors } = useCounselors();
  useEscapeKey(onClose, true);

  const [chatMessages, setChatMessages] = useState<{ role: 'user' | 'assistant'; content: string; timestamp: string }[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [isGeneratingResponse, setIsGeneratingResponse] = useState(false);
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);

  useEffect(() => {
    if (appointment) {
      const savedChatKey = `ruangtenang_chat_${appointment.id}`;
      const savedChat = null;
      if (savedChat) {
        try {
          setChatMessages(JSON.parse(savedChat));
        } catch (e) {
          initializeNewChat(appointment);
        }
      } else {
        initializeNewChat(appointment);
      }
    }
  }, [appointment]);

  const initializeNewChat = (apt: Appointment) => {
    if (counselors.length === 0) return;
    const counselor = counselors.find(c => c.id === apt.counselorId) || counselors[0];
    const initialGreeting = `Halo ${apt.studentName}! Selamat datang di Sesi Konseling Virtual RuangTenang Kampus 🤍. Saya ${counselor.name} 👋. Saya di sini siap merangkul, mendengarkan ceritamu, dan mendampingimu terkait masalah "${apt.primaryConcern}". Jangan ragu atau takut bercerita yaa, sesi ini sepenuhnya privat, aman, & rahasia 🔐✨. Apa yang paling berat atau sedang mengganjal di hatimu saat ini, kawan?`;

    const initialMsg = {
      role: 'assistant' as const,
      content: initialGreeting,
      timestamp: new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })
    };
    setChatMessages([initialMsg]);

  };

  if (!appointment) return null;

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim() || isGeneratingResponse) return;

    const userMsg = {
      role: 'user' as const,
      content: chatInput.trim(),
      timestamp: new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })
    };

    const updatedMessages = [...chatMessages, userMsg];
    setChatMessages(updatedMessages);
    setChatInput('');
    setIsGeneratingResponse(true);

    const savedChatKey = `ruangtenang_chat_${appointment.id}`;


    try {
      const counselor = counselors.find(c => c.id === appointment.counselorId) || counselors[0];
      const res = await apiClient.post<any>('/api/v1/counselor-chat', {
        messages: updatedMessages.map(m => ({ role: m.role, content: m.content })),
        counselorName: counselor.name,
        counselorTitle: counselor.title,
        counselorUniversity: counselor.university,
        counselorSpecialties: counselor.specialties,
        studentName: appointment.studentName,
        concern: appointment.primaryConcern
      });

      const data = res.data;
      const botMsg = {
        role: 'assistant' as const,
        content: (data && data.reply) || `Terima kasih atas ceritanya, ${appointment.studentName}. Saya sangat menghargai keberanian Anda berbagi rasa ini. Silakan ceritakan lebih lanjut, saya terus menyimak.`,
        timestamp: new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })
      };

      const finalMessages = [...updatedMessages, botMsg];
      setChatMessages(finalMessages);

    } catch (err) {
      console.warn('Counselor simulation API error:', err);
      const fallbackMsg = {
        role: 'assistant' as const,
        content: `Terima kasih sudah berbagi cerita, ${appointment.studentName}. Sebagai konselor Anda, saya sangat mendengarkan kecemasan dan apa yang mengganggu kenyamanan Anda. Kita akan melaluinya pelan-pelan bersama-sama. Silakan utarakan apa lagi yang Anda rasakan.`,
        timestamp: new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })
      };
      const finalMessages = [...updatedMessages, fallbackMsg];
      setChatMessages(finalMessages);

    } finally {
      setIsGeneratingResponse(false);
    }
  };

  const handleCompleteClick = async () => {
    setIsGeneratingSummary(true);

    try {
      const counselor = counselors.find(c => c.id === appointment.counselorId) || counselors[0];

      const summaryPrompt = [
        {
          role: 'user',
          content: `Tolong buatkan Ringkasan Hasil Konseling Klinis yang sangat formal, profesional, dan realistis berdasarkan percakapan bimbingan konseling simulasi berikut ini:
          ${JSON.stringify(chatMessages)}

          Ringkasan HARUS mencakup bab-bab berikut dengan gaya penulisan psikolog profesional:
          1. ANALISIS KONDISI EMOSIONAL MAHASISWA (menguraikan mood, tingkat kecemasan, serta distress akademis yang dirasakan).
          2. MASALAH UTAMA YANG TERIDENTIFIKASI (penyebab stres, burnout, bimbingan dosen, atau overthinking).
          3. REKOMENDASI TERAPEUTIK & COPING STRATEGY (teknik grounding, pembagian waktu, restrukturisasi kognitif, dll).
          4. RENCANA TINDAK LANJUT (follow-up plan).

          PENTING: Jawab dalam Bahasa Indonesia yang formal dan profesional. Jangan gunakan bahasa gaul.`
        }
      ];

      let summaryTextResult = '';

      try {
        const res = await apiClient.post<any>('/api/v1/counselor-chat', {
          messages: summaryPrompt,
          counselorName: counselor.name,
          counselorTitle: counselor.title,
          counselorUniversity: counselor.university,
          counselorSpecialties: counselor.specialties,
          studentName: appointment.studentName,
          concern: appointment.primaryConcern
        });
        const data = res.data;
        summaryTextResult = data?.reply || '';
      } catch (e) {
        summaryTextResult = `RINGKASAN SESI KONSELING SIMULASI\n` +
          `Konselor: ${counselor.name}\n` +
          `Mahasiswa: ${appointment.studentName} (${appointment.studentNIM || 'N/A'})\n` +
          `Keluhan Utama: ${appointment.primaryConcern}\n\n` +
          `1. ANALISIS EMOSIONAL:\nMahasiswa menunjukkan tingkat kelelahan emosional (burnout) yang dipicu oleh beban akademis dan kecemasan terkait masa depan.\n\n` +
          `2. COPING STRATEGY:\n- Latih teknik pernapasan 4-7-8 untuk menenangkan detak jantung saat panik.\n- Membagi draf pengerjaan skripsi menjadi bagian kecil terstruktur.\n- Mengurangi screen-time gawai sebelum tidur malam.`;
      }

      onCompleteSession(appointment.id, summaryTextResult);
      onClose();
      showToast('Sesi Konseling berhasil diselesaikan! Ringkasan & saran psikologis telah diterbitkan.', 'success');
    } catch (err) {
      console.error(err);
      showToast('Gagal menyelesaikan sesi secara formal.', 'error');
    } finally {
      setIsGeneratingSummary(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-2 sm:p-4 animate-in fade-in duration-200">
      <div className="bg-slate-50 text-slate-800 rounded-xl max-w-2xl w-full h-[90vh] sm:h-[80vh] flex flex-col shadow-xl relative overflow-hidden">
        {/* Header */}
        <div className="p-4 bg-white border-b border-slate-200 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-3">
            <img
              src={appointment.counselorAvatar}
              alt={appointment.counselorName}
              width={40}
              height={40}
              loading="lazy"
              decoding="async"
              className="w-10 h-10 rounded-full object-cover border border-slate-200"
            />
            <div>
              <h3 className="font-sans font-semibold tracking-tight text-slate-900 text-sm sm:text-base leading-tight">
                {appointment.counselorName}
              </h3>
              <p className="text-xs text-emerald-600 font-medium flex items-center gap-1 mt-0.5">
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span>
                Sesi Konseling Aktif (Simulasi)
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={handleCompleteClick}
              disabled={isGeneratingSummary}
              className="px-3.5 py-1.5 bg-slate-800 hover:bg-slate-900 text-white rounded-lg text-xs font-semibold shadow-xs flex items-center gap-1.5 transition-all disabled:opacity-50"
              title="Selesaikan sesi ini dan buat Ringkasan & Saran Klinis otomatis"
            >
              <Check className="w-3.5 h-3.5" />
              <span>Selesaikan & Ringkas</span>
            </button>
            <button
              onClick={onClose}
              disabled={isGeneratingSummary}
              className="p-1.5 text-slate-600 hover:text-slate-700 hover:bg-slate-100 rounded-lg transition-colors"
              title="Tutup jendela chat"
            >
              <XCircle className="w-5 h-5" />
            </button>
          </div>
        </div>

        {/* Info and Warning Strip */}
        <div className="bg-amber-50 border-b border-amber-100 px-4 py-2 flex items-start gap-2.5 shrink-0 text-[11px] sm:text-xs text-amber-600">
          <AlertCircle className="w-4 h-4 text-amber-500 shrink-0 mt-0.5" />
          <div>
            <p className="font-semibold">Sesi Simulasi Interaktif Aktif</p>
            <p className="opacity-90">Ini adalah sesi bimbingan konseling simulasi untuk proyek Anda. Seluruh tanggapan psikolog dihasilkan secara virtual oleh AI.</p>
          </div>
        </div>

        {/* Chat History Messages */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-100/50">
          {chatMessages.map((msg, idx) => {
            const isUser = msg.role === 'user';
            return (
              <div
                key={idx}
                className={`flex ${isUser ? 'justify-end' : 'justify-start'} items-start gap-2.5 animate-in fade-in slide-in-from-bottom-2 duration-150`}
              >
                {!isUser && (
                  <div className="w-7 h-7 rounded-full bg-slate-200 border border-slate-300 flex items-center justify-center shrink-0">
                    <Bot className="w-4 h-4 text-slate-600" />
                  </div>
                )}
                <div className="max-w-[85%] sm:max-w-[75%] flex flex-col">
                  <span className={`text-[10px] font-medium mb-1 ${isUser ? 'text-right text-slate-600' : 'text-slate-600'}`}>
                    {isUser ? 'Anda' : appointment.counselorName}
                  </span>
                  <div
                    className={`rounded-2xl px-4 py-2.5 text-sm leading-relaxed shadow-xs whitespace-pre-wrap ${
                      isUser
                        ? 'bg-slate-800 text-white rounded-tr-none'
                        : 'bg-white text-slate-800 border border-slate-200 rounded-tl-none'
                    }`}
                  >
                    {msg.content}
                  </div>
                  <span className={`text-[9px] text-slate-600 mt-1 ${isUser ? 'text-right' : 'text-left'}`}>
                    {msg.timestamp}
                  </span>
                </div>
              </div>
            );
          })}

          {isGeneratingResponse && (
            <div className="flex justify-start items-start gap-2.5 animate-pulse">
              <div className="w-7 h-7 rounded-full bg-slate-200 border border-slate-300 flex items-center justify-center shrink-0">
                <Bot className="w-4 h-4 text-slate-600" />
              </div>
              <div className="flex flex-col">
                <span className="text-[10px] font-medium text-slate-600 mb-1">{appointment.counselorName}</span>
                <div className="surface-card rounded-2xl rounded-tl-none px-4 py-3 text-sm text-slate-600 flex items-center gap-2">
                  <span className="w-1.5 h-1.5 rounded-full bg-slate-500 animate-bounce [animation-delay:-0.3s]"></span>
                  <span className="w-1.5 h-1.5 rounded-full bg-slate-500 animate-bounce [animation-delay:-0.15s]"></span>
                  <span className="w-1.5 h-1.5 rounded-full bg-slate-500 animate-bounce"></span>
                  <span className="font-medium text-xs text-slate-600 ml-1">Sedang mengetik tanggapan...</span>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Input Form */}
        <form onSubmit={handleSendMessage} className="p-3 bg-white border-t border-slate-200 flex items-center gap-2 shrink-0">
          <input
            type="text"
            value={chatInput}
            onChange={(e) => setChatInput(e.target.value)}
            disabled={isGeneratingResponse || isGeneratingSummary}
            placeholder={isGeneratingResponse ? "Harap tunggu jawaban konselor..." : "Ketik pesan Anda terkait beban atau kecemasan..."}
            className="flex-1 bg-slate-50 rounded-xl px-4 py-3 text-base sm:text-sm focus:outline-none focus:border-slate-800 focus:bg-white text-slate-800 transition-colors"
