              <Download className="w-3.5 h-3.5 text-slate-600" />
              <span>Audit</span>
            </button>
          </div>
        </div>

        <div className="space-y-2.5">
          {filteredAlerts.map((alertItem) => (
            <div
              key={alertItem.id}
              className={`p-3 rounded-lg border space-y-2 transition-all text-xs ${
                alertItem.riskLevel === 'Tinggi'
