                className={`px-3 py-1.5 rounded-lg border font-medium transition-all ${
                  apptStatusFilter === filter
                    ? 'bg-slate-800 text-white border-slate-800'
                    : 'bg-white text-slate-600 border-slate-200 hover:border-slate-300'
                }`}
              >
                {filter === 'Semua'
                  ? 'Semua Status'
                  : filter === 'PENDING'
                  ? '⏳ Menunggu Konfirmasi'
                  : filter === 'CONFIRMED'
                  ? '✅ Terkonfirmasi'
