  const renderDelta = (delta: number, isLowerBetter: boolean = true) => {
    if (delta === 0) return (
      <span className="text-[11px] font-semibold text-teal-600 bg-teal-50 px-2 py-0.5 rounded border border-teal-200">
        ↓ Terpantau Stabil
