              </h4>
              <p className="text-[11px] text-secondary leading-relaxed">
                Berdasarkan skor evaluasi awal Anda, berikut langkah terbaik yang disarankan untuk menjaga kesehatan emosional Anda:
              </p>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5 pt-0.5">
                <button
                  onClick={() => {
                    onClose();
                    navigate('/');
                  }}
                  className="p-3 rounded-lg border border-teal-200/60 dark:border-teal-900 hover:border-teal-300 dark:hover:border-teal-800 bg-teal-50/40 dark:bg-teal-950/20 hover:bg-teal-50 dark:hover:bg-teal-950/40 text-left transition-all group flex items-start gap-2.5 cursor-pointer"
                >
                  <MessageSquare className="w-4 h-4 text-teal-600 dark:text-teal-400 mt-0.5 shrink-0 group-hover:scale-110 transition-transform" />
                  <div>
                    <span className="text-xs font-bold text-teal-800 dark:text-teal-300 block mb-0.5">Diskusikan Hasil di Chat</span>
                    <span className="text-[10.5px] text-teal-600 dark:text-teal-400/80 leading-snug block">Bimbing asisten AI untuk mengurai perasaan Anda secara aman dan personal.</span>
                  </div>
                </button>

                <button
                  onClick={() => {
                    onClose();
                    navigate('/counselors');
                  }}
                  className="p-3 rounded-lg border border-indigo-200/60 dark:border-indigo-900 hover:border-indigo-300 dark:hover:border-indigo-800 bg-indigo-50/40 dark:bg-indigo-950/20 hover:bg-indigo-50 dark:hover:bg-indigo-950/40 text-left transition-all group flex items-start gap-2.5 cursor-pointer"
                >
                  <Calendar className="w-4 h-4 text-indigo-600 dark:text-indigo-400 mt-0.5 shrink-0 group-hover:scale-110 transition-transform" />
                  <div>
                    <span className="text-xs font-bold text-indigo-800 dark:text-indigo-300 block mb-0.5">Jadwalkan Sesi Konseling</span>
                    <span className="text-[10.5px] text-indigo-600 dark:text-indigo-400/80 leading-snug block">Temui psikolog profesional kampus berlisensi untuk penanganan terarah.</span>
                  </div>
                </button>
              </div>
            </div>

            <div className="bg-amber-50/60 dark:bg-amber-950/30 border border-amber-200/60 dark:border-amber-900/60 rounded-lg p-2.5">
              <p className="text-xs text-amber-800 dark:text-amber-200 text-center font-medium">
                ⚠️ Skor ini hanya alat skrining awal, bukan diagnosis medis.
              </p>
            </div>

            <div className="flex flex-col sm:flex-row items-center justify-between gap-2.5 pt-3 border-t border-slate-100 dark:border-slate-800">
              <button
                onClick={() => downloadReportTxt(finalResult)}
                className="w-full sm:w-auto flex items-center justify-center gap-1.5 px-3.5 py-2 min-h-[44px] sm:min-h-[36px] bg-white dark:bg-slate-800 hover:bg-stone-50 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 text-xs font-semibold rounded-lg border border-slate-200/60 dark:border-slate-700 transition-all cursor-pointer"
              >
                <Download className="w-3.5 h-3.5" />
                <span>Unduh Laporan (.txt)</span>
              </button>

              <div className="flex flex-col sm:flex-row w-full sm:w-auto items-center gap-2">
                <button
                  onClick={() => setStep('intro')}
                  className="w-full sm:w-auto flex items-center justify-center gap-1.5 px-3.5 py-2 min-h-[44px] sm:min-h-[36px] bg-stone-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 text-secondary text-xs font-semibold rounded-lg transition-all cursor-pointer"
                >
                  <RotateCcw className="w-3.5 h-3.5" />
                  <span>Tes Ulang</span>
                </button>
                <button
                  onClick={onClose}
                  className="w-full sm:w-auto px-5 py-2 min-h-[44px] sm:min-h-[36px] bg-teal-600 hover:bg-teal-700 text-white text-xs font-bold rounded-lg shadow-3xs transition-all cursor-pointer flex items-center justify-center"
                >
                  Selesai
                </button>
              </div>
            </div>
          </div>
        )}

        {/* SAFETY CHECK MODAL OVERLAY (Triggered when PHQ-9 Item 9 > 0) */}
        <SafetyCheckModal
          isOpen={showSafetyCheckModal}
          onClose={() => setShowSafetyCheckModal(false)}
          safetyAssessment={safetyAssessment}
          setSafetyAssessment={setSafetyAssessment}
        />
      </div>
    </div>
  );
};

import { useEscapeKey } from '../../hooks/useEscapeKey';
import React, { useState, useEffect, useCallback } from 'react';
import { User,
  ShieldCheck,
  CreditCard,
  Check,
  Sparkles,
  Zap,
  RotateCcw,
  ShieldAlert,
  UserCheck,
  Terminal,
  KeyRound,
  Lock,
  X,
  ChevronRight,
  ChevronLeft
} from 'lucide-react';
import { UserSession, SubscriptionTier } from '../../types';
import { Brain, MessageSquare, Gauge, Cpu, CheckCircle2, History, Calendar, Bell } from 'lucide-react';
import { DEFAULT_AI_MODEL_ID, AVAILABLE_AI_MODELS } from '../../lib/aiModels';
import { safeLocalStorage } from '../../lib/storage';
import { AiQuotaBadge } from '../../components/AiQuotaBadge';
import { apiClient } from '../../lib/apiClient';
import { CURRENT_APP_VERSION, LAST_UPDATED_DATE, APP_CHANGELOG, CATEGORY_METADATA } from '../../data/changelogData';

interface SettingsPageProps {
  userSession: UserSession | null;
  setUserSession: (session: UserSession) => void;
  onOpenScreening: () => void;
  onOpenLegal: () => void;
  onOpenPrivacyCenter?: () => void;
  onOpenAuth?: () => void;
  onOpenChangelog?: () => void;
  // screeningResult removed
}

const DEFAULT_GUEST_USER: UserSession = {
  id: 'guest',
  name: 'Tamu / Belum Masuk',
  email: 'tamu@ruangtenang.id',
  role: 'guest',
  tier: 'Free',
  usageStats: { chatMessagesSent: 0, appointmentsBooked: 0 }
};

export const SettingsPage: React.FC<SettingsPageProps> = ({
  userSession,
  setUserSession,
  onOpenLegal,
  onOpenPrivacyCenter,
  onOpenAuth,
  onOpenChangelog,
}) => {
  const safeUser = userSession || DEFAULT_GUEST_USER;
  const [loading, setLoading] = useState(false);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [showDevModal, setShowDevModal] = useState(false);
  useEscapeKey(() => setShowDevModal(false), showDevModal);
  const [devPassword, setDevPassword] = useState('');
  const [devError, setDevError] = useState<string | null>(null);

  const [aiModel, setAiModel] = useState(() => safeLocalStorage.getItem('aiModel') || DEFAULT_AI_MODEL_ID);
  const [responseStyle, setResponseStyle] = useState(() => safeLocalStorage.getItem('responseStyle') || 'Seimbang');

  const [prefDailyReminders, setPrefDailyReminders] = useState(() => safeLocalStorage.getItem('pref_daily_reminders') !== 'false');
  const [prefCounselingUpdates, setPrefCounselingUpdates] = useState(() => safeLocalStorage.getItem('pref_counseling_updates') !== 'false');
  const [prefNewsletter, setPrefNewsletter] = useState(() => safeLocalStorage.getItem('pref_newsletter') === 'true');

  const triggerNotificationSaved = () => {
    setSuccessMsg('Preferensi notifikasi berhasil diperbarui.');
    setTimeout(() => setSuccessMsg(null), 3000);
  };

  const handleSelectAiModel = (modelId: string) => {
    setAiModel(modelId);
    safeLocalStorage.setItem('aiModel', modelId);
    setSuccessMsg(`Model AI berhasil diubah ke ${AVAILABLE_AI_MODELS.find(m => m.id === modelId)?.name || modelId}.`);
    setTimeout(() => setSuccessMsg(null), 3000);
  };

  const handleSelectResponseStyle = (style: string) => {
    setResponseStyle(style);
    safeLocalStorage.setItem('responseStyle', style);
    setSuccessMsg(`Gaya respons AI diperbarui ke ${style}.`);
    setTimeout(() => setSuccessMsg(null), 3000);
  };

  const [, setUsageStats] = useState<{
    dailyLimit: number;
    dailyUsage: number;
    userTier: string;
  } | null>(null);

  // Security & Sessions State
  const [sessions, setSessions] = useState<any[]>([]);
  const [loginHistory, setLoginHistory] = useState<any[]>([]);
  const [secTab, setSecTab] = useState<'sessions' | 'history' | 'password'>('sessions');
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [secMsg, setSecMsg] = useState<{ type: 'success' | 'error'; text: string } | null>(null);

  const fetchSecurityData = useCallback(async () => {
    if (safeUser.id === 'guest') return;
    try {
      // Active Sessions
      const resSess = await apiClient.get<any>('/api/v1/auth/sessions');
      if (resSess.success && resSess.data) {
        setSessions(resSess.data.sessions || []);
      }

      // Login History
      const resHist = await apiClient.get<any>('/api/v1/auth/login-history');
      if (resHist.success && resHist.data) {
        setLoginHistory(resHist.data.history || []);
      }
    } catch (err) {
      console.error('Error loading security info:', err);
    }
  }, [safeUser.id]);

  useEffect(() => {
    fetchSecurityData();
  }, [fetchSecurityData]);

  const handleRevokeSession = async (sessionId: string) => {
    try {
      setSecMsg(null);
      const res = await apiClient.post<any>('/api/v1/auth/sessions/revoke', { sessionId });
      if (res.success) {
        setSecMsg({ type: 'success', text: 'Sesi perangkat berhasil dicabut.' });
        fetchSecurityData();
      } else {
        setSecMsg({ type: 'error', text: res.error || 'Gagal mencabut sesi.' });
      }
    } catch (err) {
      setSecMsg({ type: 'error', text: 'Koneksi gagal.' });
    }
  };

  const handleLogoutAllDevices = async () => {
    try {
      setSecMsg(null);
      const res = await apiClient.post<any>('/api/v1/auth/logout-all', {});
      if (res.success) {
        setSecMsg({ type: 'success', text: 'Seluruh sesi perangkat telah berhasil dicabut.' });
        fetchSecurityData();
      } else {
        setSecMsg({ type: 'error', text: res.error || 'Gagal mencabut seluruh sesi.' });
      }
    } catch (err) {
      setSecMsg({ type: 'error', text: 'Koneksi gagal.' });
    }
  };

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    setSecMsg(null);

    if (newPassword !== confirmPassword) {
      setSecMsg({ type: 'error', text: 'Konfirmasi kata sandi baru tidak cocok.' });
      return;
    }

    if (newPassword.length < 10) {
      setSecMsg({ type: 'error', text: 'Kata sandi baru minimal 10 karakter.' });
      return;
    }

    try {
      const res = await apiClient.post<any>('/api/v1/auth/change-password', { currentPassword, newPassword });
      if (res.success) {
        setSecMsg({ type: 'success', text: 'Kata sandi berhasil diperbarui. Seluruh sesi lain telah dicabut.' });
        setCurrentPassword('');
        setNewPassword('');
        setConfirmPassword('');
        fetchSecurityData();
      } else {
        setSecMsg({ type: 'error', text: res.error || 'Gagal mengubah kata sandi.' });
      }
    } catch (err) {
      setSecMsg({ type: 'error', text: 'Koneksi gagal.' });
    }
  };

  const fetchUsage = useCallback(async () => {
    try {
      const res = await apiClient.get<any>(`/api/v1/user/usage-stats?userId=${safeUser.id}&userTier=${safeUser.tier}`);
      if (res.success && res.data) {
        const data = res.data;
        setUsageStats({
          dailyLimit: data.dailyLimit,
          dailyUsage: data.dailyUsage,
          userTier: data.userTier || safeUser.tier
        });
      }
    } catch (err) {
      console.error('Error fetching usage stats in settings:', err);
    }
  }, [safeUser.id, safeUser.tier]);

  useEffect(() => {
    fetchUsage();
  }, [fetchUsage]);

  const handleSelectTier = async (selectedTier: SubscriptionTier, password?: string) => {
    if (selectedTier === 'Developer' && !password) {
      setDevPassword('');
      setDevError(null);
      setShowDevModal(true);
      return;
    }

    setLoading(true);
    setErrorMsg(null);
    setSuccessMsg(null);
    setDevError(null);

    try {
      const response = await apiClient.post<any>('/api/v1/auth/update-tier', { tier: selectedTier, password });

      if (response.success) {
        setUserSession({
          ...safeUser,
          tier: selectedTier
        });
        setSuccessMsg(
          selectedTier === 'Developer'
            ? 'Mode Developer Aktif! Anda mendapatkan akses Tanpa Limit (Unlimited chat).'
            : selectedTier === 'Pro'
            ? 'Selamat! Paket Anda beralih ke Pendamping Pro (100 pesan/hari).'
            : 'Paket beralih ke Standard (25 pesan/hari).'
        );
        setShowDevModal(false);
        setDevPassword('');
        fetchUsage();
      } else {
        if (selectedTier === 'Developer') {
          setDevError(response.error || 'Password Developer salah!');
        } else {
          setErrorMsg(response.error || 'Gagal mengubah paket.');
        }
      }
    } catch (err) {
      setErrorMsg('Koneksi ke server gagal.');
    } finally {
      setLoading(false);
      setTimeout(() => setSuccessMsg(null), 5000);
    }
  };

  const [activeTab, setActiveTab] = useState<'akun'|'ai'|'privasi'|'memory'|'keamanan'|'langganan'|'versi'|'notifikasi'>('akun');
  const [showMobileDetail, setShowMobileDetail] = useState(false);

  const TABS = [
    { id: 'akun', label: 'Akun', icon: User },
    { id: 'ai', label: 'Preferensi AI', icon: Brain },
    { id: 'notifikasi', label: 'Notifikasi', icon: Bell },
    { id: 'privasi', label: 'Privasi', icon: ShieldCheck },
    { id: 'memory', label: 'Memory', icon: RotateCcw },
    { id: 'keamanan', label: 'Keamanan', icon: Lock },
    { id: 'langganan', label: 'Langganan', icon: CreditCard },
    { id: 'versi', label: 'Versi & Pembaruan', icon: Sparkles }
  ] as const;

  return (
    <div className="w-full max-w-5xl mx-auto px-4 sm:px-6 lg:px-6 py-4 sm:py-6 min-w-0 flex flex-col md:flex-row gap-4 lg:gap-6 h-full">

      {/* Sidebar Tabs for Desktop & Menu List for Mobile */}
      <div className={`w-full md:w-64 shrink-0 flex flex-col gap-2 ${showMobileDetail ? 'hidden md:flex' : 'flex'}`}>
        <h2 className="text-lg font-bold text-primary mb-2 px-2 hidden md:block">Pengaturan</h2>
        <div className="flex flex-col gap-1.5 md:gap-1">
          {TABS.map(tab => {
            const Icon = tab.icon;
            return (
              <button
                key={tab.id}
                onClick={() => {
                  setActiveTab(tab.id);
                  setShowMobileDetail(true);
                }}
                className={`flex items-center justify-between md:justify-start gap-3 px-4 py-3 sm:py-3.5 md:py-2.5 rounded-xl text-sm font-medium transition-colors border border-transparent cursor-pointer ${
                  activeTab === tab.id 
                    ? 'bg-teal-50 text-teal-700 md:bg-teal-50 md:text-teal-700' 
                    : 'text-secondary hover:surface-muted surface-muted/50 md:bg-transparent'
                }`}
              >
                <div className="flex items-center gap-3 min-w-0">
                  <Icon className={`w-5 h-5 shrink-0 ${activeTab === tab.id ? 'text-teal-600' : 'text-muted'}`} />
                  <span className="truncate">{tab.label}</span>
                </div>
                <ChevronRight className="w-4 h-4 text-muted md:hidden shrink-0" />
              </button>
            )
          })}
        </div>
      </div>

      {/* Main Content Area */}
      <div className={`flex-1 min-w-0 space-y-4 pb-20 ${!showMobileDetail ? 'hidden md:block' : 'block'}`}>
        {/* Mobile Back Button */}
        {showMobileDetail && (
          <button 
            onClick={() => setShowMobileDetail(false)} 
            className="md:hidden flex items-center gap-1.5 text-xs sm:text-sm font-semibold text-teal-600 hover:text-teal-700 px-3.5 py-2 mb-2 rounded-lg bg-teal-50 hover:bg-teal-100 cursor-pointer transition-all self-start min-h-[44px]"
          >
            <ChevronLeft className="w-4 h-4" /> Kembali ke Daftar Pengaturan
          </button>
        )}

      {successMsg && (
        <div className="p-4 bg-teal-50 border border-teal-200 rounded-xl text-teal-800 text-xs sm:text-sm flex items-center gap-2.5 shadow-xs animate-in fade-in duration-300">
          <div className="p-1 bg-teal-600 text-white rounded-full">
            <Check className="w-4 h-4" />
          </div>
          <p className="font-medium">{successMsg}</p>
        </div>
      )}

      {errorMsg && (
        <div className="p-4 bg-rose-50 border border-rose-200 rounded-xl text-rose-800 text-xs sm:text-sm flex items-center gap-2.5 shadow-xs animate-in fade-in duration-300">
          <div className="p-1 bg-rose-600 text-white rounded-full shrink-0">
            <ShieldAlert className="w-4 h-4" />
          </div>
          <p className="font-medium">{errorMsg}</p>
        </div>
      )}

      {activeTab === 'akun' && (
        <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-300">
          <div className="surface-card rounded-xl p-4 sm:p-5 space-y-4">
            <h3 className="text-sm font-bold text-primary flex items-center gap-2 border-b border-default pb-2">
              <UserCheck className="w-4.5 h-4.5 text-secondary" />
              Profil Sesi
            </h3>

            <div className="space-y-3">
              <div className="p-3 surface-muted border border-slate-150 rounded-lg flex items-center gap-3">
                <div className="w-10 h-10 rounded-full bg-slate-800 text-white flex items-center justify-center font-bold text-sm shrink-0 shadow-sm">
                  {safeUser.name ? safeUser.name.charAt(0).toUpperCase() : 'G'}
                </div>
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-semibold text-primary truncate">{safeUser.name}</p>
                  <p className="text-xs text-muted capitalize">
                    {safeUser.role === 'konselor' ? 'Konselor / Psikolog' : safeUser.role === 'admin' ? 'Administrator' : 'Mahasiswa'}
                  </p>
                </div>
              </div>

              <div className="pt-2">
                <button
                  onClick={onOpenAuth}
                  className="w-full py-2.5 surface-card hover:surface-muted active:bg-slate-100 text-secondary border border-default rounded-xl text-sm font-medium transition-colors shadow-sm flex items-center justify-center gap-2"
                >
                  Ganti Peran / Keluar Sesi
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'ai' && (
        <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-300">
          {/* Header Card */}
          <div className="surface-card rounded-xl p-4 sm:p-5 space-y-4">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between border-b border-default pb-3 gap-2">
              <div>
                <h3 className="text-sm font-bold text-primary flex items-center gap-2">
                  <Brain className="w-4.5 h-4.5 text-teal-600" />
                  Preferensi & Pilihan Model AI
                </h3>
                <p className="text-xs text-muted mt-0.5">
                  Pilih model kecerdasan buatan yang sesuai dengan kebutuhan refleksi dan kecepatan respon Anda.
                </p>
              </div>
              <span className="text-[11px] font-semibold text-teal-700 bg-teal-50 px-2.5 py-1 rounded-full border border-teal-200 self-start sm:self-auto">
                Default Aktif: {AVAILABLE_AI_MODELS.find(m => m.id === aiModel)?.name || 'Gemini 3.1 Flash Lite'}
              </span>
            </div>

            {/* Model Selection Grid */}
            <div className="space-y-3">
              <label className="text-xs font-bold text-secondary uppercase tracking-wide">
                Daftar Model AI Tersedia
              </label>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-3.5">
                {AVAILABLE_AI_MODELS.map((model) => {
                  const isSelected = aiModel === model.id;
                  return (
                    <div
                      key={model.id}
                      onClick={() => handleSelectAiModel(model.id)}
                      className={`relative p-4 rounded-xl border transition-all cursor-pointer flex flex-col justify-between ${
                        isSelected
                          ? 'border-teal-600 bg-teal-50/40 shadow-xs ring-1 ring-teal-500'
                          : 'border-default hover:border-default hover:surface-muted surface-card'
                      }`}
                    >
                      <div className="space-y-2">
                        <div className="flex items-start justify-between gap-2">
                          <div className="flex items-center gap-2">
