import { lazy, ComponentType } from 'react';
import { safeSessionStorage } from './storage';

const CHUNK_RELOAD_KEY = 'ruangtenang_chunk_reload_guard';

export function lazyWithRetry<T extends ComponentType<any>>(
  factory: () => Promise<{ default: T } | any>
) {
  return lazy(() =>
    factory().catch(async (err: any) => {
      const isChunkError =
        err?.name === 'ChunkLoadError' ||
        /loading chunk/i.test(err?.message || '') ||
        /failed to fetch dynamically imported module/i.test(err?.message || '') ||
        /importing a module script failed/i.test(err?.message || '');

      console.warn('Dynamic import failed:', err);

      try {
        await new Promise((resolve) => setTimeout(resolve, 300));
        return await factory();
      } catch (retryErr: any) {
        const isRetryChunkError =
          isChunkError ||
          retryErr?.name === 'ChunkLoadError' ||
          /loading chunk/i.test(retryErr?.message || '') ||
          /failed to fetch dynamically imported module/i.test(retryErr?.message || '') ||
          /importing a module script failed/i.test(retryErr?.message || '');

        if (isRetryChunkError && typeof window !== 'undefined') {
          const lastReload = safeSessionStorage.getItem(CHUNK_RELOAD_KEY);
          const now = Date.now();
          if (!lastReload || now - parseInt(lastReload, 10) > 10000) {
            safeSessionStorage.setItem(CHUNK_RELOAD_KEY, now.toString());
            window.location.reload();
          }
        }
        throw retryErr;
      }
    })
  );
}

import { safeLocalStorage } from './storage';

export interface AppNotification {
  id: string;
  title: string;
  message: string;
  timestamp: string;
  read: boolean;
  type: 'info' | 'success' | 'warning' | 'alert';
}

export function getActiveUserId(): string {
  if (typeof window === 'undefined') return 'guest';
  return safeLocalStorage.getItem('rt_active_user_id') || 'guest';
}

export function getNotifications(): AppNotification[] {
  const userId = getActiveUserId();
  const stored = safeLocalStorage.getItem(`ruangtenang_app_notifications_${userId}`);
  if (!stored) {
    return [];
  }
  try {
    return JSON.parse(stored);
  } catch {
    return [];
  }
}

export function saveNotifications(notifs: AppNotification[]) {
  const userId = getActiveUserId();
  safeLocalStorage.setItem(`ruangtenang_app_notifications_${userId}`, JSON.stringify(notifs));
  // Dispatch a custom event to update other mounted components reactively
  if (typeof window !== 'undefined') {
    try {
      window.dispatchEvent(new Event('ruangtenang_notifications_updated'));
    } catch {}
  }
}

export function addNotification(title: string, message: string, type: AppNotification['type'] = 'info') {
  const notifs = getNotifications();
  const newNotif: AppNotification = {
    id: 'n-' + Date.now() + '-' + Math.random().toString(36).substring(2, 6),
    title,
    message,
    timestamp: new Date().toISOString(),
    read: false,
    type
  };
  notifs.unshift(newNotif);
  saveNotifications(notifs);
}

