  // 5. Test Zod Validation Schema - Invalid Email
  try {
    const invalidBooking = {
      studentName: 'Ahmad Fauzi',
      studentNIM: '2106123456',
      studentEmail: 'email-salah-format',
      studentPhone: '0812',
      date: '2026-08-10',
